INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高中生是读高中的学生，比小学生大很多。", "primary_collocate": null, "pronunciation": "gāo zhōng shēng", "ipa": "kau˥ ʈʂʊŋ˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "我哥哥是高中生，今年十七岁。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中生每天要上八节课。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个高中生已经比妈妈高了。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小学生们很喜欢听高中生讲故事。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中生要准备很多考试。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那几个高中生正在公交车站等车。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是高中生，个子已经比爸爸还高了。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是高中生，每天六点就起床。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个暑假，高中生们去山里做了志愿者。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当高中生比当小学生累多了。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "读高中、年纪比小学生大得多的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高中生", "is_correct": true, "explanation": "高中生：读高中的学生，年龄与“今年十七岁”相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生一般只有六七岁，与“今年十七岁”矛盾。"}, {"text": "研究生", "is_correct": false, "explanation": "语义：研究生需要先读完本科，十七岁一般不会已是研究生，与句意不符。"}, {"text": "娃娃", "is_correct": false, "explanation": "语域：“娃娃”是口语中指小孩子的词，与“哥哥”和“十七岁”的描述都不合。"}], "explanations": {"高中生": "高中生：读高中的学生，年龄与“今年十七岁”相符。", "小学生": "语义：小学生一般只有六七岁，与“今年十七岁”矛盾。", "研究生": "语义：研究生需要先读完本科，十七岁一般不会已是研究生，与句意不符。", "娃娃": "语域：“娃娃”是口语中指小孩子的词，与“哥哥”和“十七岁”的描述都不合。"}, "sentence_index": 0, "correct_answer": "高中生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一只高中生。", "explanation": "这里应该用〈个〉或〈名〉。“只”多用于动物，或用于成对物件中的一个，不用来数人。"}, {"text": "他是一条高中生，每天骑车上学。", "explanation": "这里应该用〈个〉。“条”用于细长或成条状的事物，不用来数人。"}, {"text": "这间教室里坐着一把高中生。", "explanation": "这里应该用〈个〉或〈名〉。“把”用于有柄或有靠背的器具，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高中生", "is_correct": true, "explanation": "高中生：读高中的学生，“他是高中生”指人的身份，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是人，“他是桌子”不成句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是人，“他是冰箱”不成句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是人，“他是椅子”不成句意。"}], "explanations": {"高中生": "高中生：读高中的学生，“他是高中生”指人的身份，符合句意。", "桌子": "语义：桌子是家具，不是人，“他是桌子”不成句意。", "冰箱": "语义：冰箱是家电，不是人，“他是冰箱”不成句意。", "椅子": "语义：椅子是家具，不是人，“他是椅子”不成句意。"}, "sentence_index": 6, "correct_answer": "高中生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班来了一头高中生。", "explanation": "这里应该用〈个〉。“头”用于大型牲畜，不用来数人。"}, {"text": "他是一本高中生，每天背很多书。", "explanation": "这里应该用〈个〉。“本”用于书册，不能用来数人。"}, {"text": "这张椅子旁边坐着一张高中生。", "explanation": "这里应该用〈个〉。“张”用于平面的物品，如桌子、纸张，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个很聪明高中生考上了名牌大学。", "corrected_sentence": "这个很聪明的高中生考上了名牌大学。", "error_description": "错误：修饰语“很聪明”与中心词“高中生”之间漏掉了结构助词“的”。应为“很聪明的高中生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个高中生们一起去了图书馆。", "corrected_sentence": "三个高中生一起去了图书馆。", "error_description": "错误：“们”不能与数量词连用。数量词后的名词不加“们”，应为“三个高中生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
