INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在高级中学就读的学生。", "primary_collocate": null, "pronunciation": "gāo zhōng shēng", "ipa": "kau˥ ʈʂʊŋ˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "他是我们学校一年级的高中生。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校有两千多名高中生。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中生可以申请这个奖学金。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里举行了高中生英语比赛。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为高中生，你要学会自己安排时间。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家图书馆为高中生准备了很多参考书。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多高中生周末还要上补习班。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中生需要参加高考才能上大学。", "target_word": "高中生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是重点中学的高中生，成绩很好。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名参加比赛的高中生一共有三十人。", "target_word": "高中生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "在高级中学就读的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高中生", "is_correct": true, "explanation": "高中生：在高级中学就读的学生，与“一年级”的身份相符。"}, {"text": "教授", "is_correct": false, "explanation": "语义：教授是大学的教师职称，不可能是一年级的学生。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“幼儿园”指机构，不能用来指“他”这样的人。"}, {"text": "院长", "is_correct": false, "explanation": "语义：院长是管理人员，不可能是一年级的学生，与句意矛盾。"}], "explanations": {"高中生": "高中生：在高级中学就读的学生，与“一年级”的身份相符。", "教授": "语义：教授是大学的教师职称，不可能是一年级的学生。", "幼儿园": "搭配：“幼儿园”指机构，不能用来指“他”这样的人。", "院长": "语义：院长是管理人员，不可能是一年级的学生，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "高中生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校来了一棵高中生。", "explanation": "这里应该用〈个〉。“棵”用于树木等植物，不用来数人。"}, {"text": "图书馆里坐着一块高中生。", "explanation": "这里应该用〈个〉。“块”用于成块的物体，不用来数人。"}, {"text": "校门口站着一辆高中生。", "explanation": "这里应该用〈个〉。“辆”用于车辆，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高中生", "is_correct": true, "explanation": "高中生：在高级中学就读的学生，与“周末还要上补习班”的情形相符。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不需要上补习班，句意不通。"}, {"text": "电视机", "is_correct": false, "explanation": "语义：电视机是家用电器，不可能去上补习班。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“工厂”是机构或场所，不能作为去上补习班的对象。"}], "explanations": {"高中生": "高中生：在高级中学就读的学生，与“周末还要上补习班”的情形相符。", "猫": "语义：猫不需要上补习班，句意不通。", "电视机": "语义：电视机是家用电器，不可能去上补习班。", "工厂": "搭配：“工厂”是机构或场所，不能作为去上补习班的对象。"}, "sentence_index": 6, "correct_answer": "高中生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班来了一头高中生，同学们都很惊讶。", "explanation": "这里应该用〈个〉。“头”用于大型牲畜，不用来数人。"}, {"text": "教室里坐着一本高中生。", "explanation": "这里应该用〈个〉。“本”用于书册，不能用来数人。"}, {"text": "讲台上站着一张高中生。", "explanation": "这里应该用〈个〉。“张”用于平面的物品，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位很努力高中生。", "corrected_sentence": "他是一位很努力的高中生。", "error_description": "错误：“很努力”修饰“高中生”时，中间漏掉了结构助词“的”。应为“很努力的高中生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "五个高中生们一起报名参加了比赛。", "corrected_sentence": "五个高中生一起报名参加了比赛。", "error_description": "错误：“们”不能与数量词连用。数量词后的名词不加“们”，应为“五个高中生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
