INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89373, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "杂志是一本一本的,里面有很多文章和图片。", "primary_collocate": null, "pronunciation": "zá zhì", "ipa": "tsa˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有一本杂志。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在咖啡店里看杂志。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本杂志里有很多漂亮的图片。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在书店买了两本杂志。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈喜欢躺着看杂志。", "target_word": "杂志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那本杂志给我。", "target_word": "杂志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的办公室里放着很多杂志。", "target_word": "杂志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没看过这种杂志。", "target_word": "杂志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上有免费的杂志。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本杂志太重了，我拿不动。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "杂志社", "label": "复合"}, {"form": "雜誌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一本本的读物，里面有文章和图片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杂志", "is_correct": true, "explanation": "“杂志”是成册的读物，可以用“一本”计量，放在桌子上，句意完整。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸一般用“份”计量，不说“一本报纸”，搭配不当。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑一般用“台”计量，不说“一本电脑”，搭配不当。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不是读物，“桌子上有一本花瓶”句意不通。"}], "explanations": {"杂志": "“杂志”是成册的读物，可以用“一本”计量，放在桌子上，句意完整。", "报纸": "搭配：报纸一般用“份”计量，不说“一本报纸”，搭配不当。", "电脑": "搭配：电脑一般用“台”计量，不说“一本电脑”，搭配不当。", "花瓶": "语义：花瓶是器物，不是读物，“桌子上有一本花瓶”句意不通。"}, "sentence_index": 0, "correct_answer": "杂志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水里有很多杂志，要过滤一下。", "explanation": "这里应该用〈杂质〉。“杂志”是印刷品，水中的沉淀物应说“杂质”。"}, {"text": "他在舞台上表演杂志。", "explanation": "这里应该用〈杂技〉。杂技是表演，“杂志”是印刷品，不能用来表演。"}, {"text": "我每天用杂志喝水。", "explanation": "这里应该用〈杯子〉。杂志是印刷品，不能用来盛水喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂志", "is_correct": true, "explanation": "“杂志”是成册的读物，放在医生的办公室里合乎常理，句意完整。"}, {"text": "螃蟹", "is_correct": false, "explanation": "语义：螃蟹是动物，不是读物，放在医生的办公室里句意不通。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是大型动物，不能放在办公室里，句意荒谬。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云在天上，不能放在办公室里，句意不通。"}], "explanations": {"杂志": "“杂志”是成册的读物，放在医生的办公室里合乎常理，句意完整。", "螃蟹": "语义：螃蟹是动物，不是读物，放在医生的办公室里句意不通。", "大象": "语义：大象是大型动物，不能放在办公室里，句意荒谬。", "白云": "语义：白云在天上，不能放在办公室里，句意不通。"}, "sentence_index": 6, "correct_answer": "杂志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收音机里有很多杂志，声音很难听。", "explanation": "这里应该用〈杂音〉。“杂音”指声音里的噪声，“杂志”是印刷品，不能用来指噪声。"}, {"text": "这本杂志太重了，我用它打电话。", "explanation": "这里应该用〈手机〉。杂志是印刷品，不能用来打电话。"}, {"text": "他很有杂志，从来不轻易放弃。", "explanation": "这里应该用〈志气〉。“杂志”是印刷品，不能用来形容一个人有志气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每个月都买一只杂志。", "corrected_sentence": "他每个月都买一本杂志。", "error_description": "错误：“杂志”的量词用错。“只”用于动物或成对物品之一，应用“本”，即“一本杂志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都看这只杂志。", "corrected_sentence": "我每天都看这本杂志。", "error_description": "错误：“杂志”的量词用错。“只”用于动物或成对物品之一，不能用于杂志，应用“本”，即“这本杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
