INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "定期出版的刊物,内容有文章、图片等。", "primary_collocate": null, "pronunciation": "zá zhì", "ipa": "tsa˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这本杂志每个月出一次。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸订了一份英文杂志。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的文章发表在一份有名的杂志上。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给这份杂志投过稿。", "target_word": "杂志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份杂志已经出版了二十年。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这份杂志的编辑。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月的杂志还没有到。", "target_word": "杂志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "图书馆里有最新一期的杂志。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份杂志的读者大多是年轻人。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份杂志每期都有一篇旅游文章。", "target_word": "杂志", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "杂志社", "label": "复合"}, {"form": "雜誌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定期出版的刊物，有编辑、期数，可订阅和投稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杂志", "is_correct": true, "explanation": "“杂志”是定期出版的刊物，“每个月出一次”正合它的特点，句意完整。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸一般用“份”计量，不说“这本报纸”，搭配不当。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机一般用“部”或“款”计量，不说“这本手机”，搭配不当。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是出版物，“每个月出一次”句意不通。"}], "explanations": {"杂志": "“杂志”是定期出版的刊物，“每个月出一次”正合它的特点，句意完整。", "报纸": "搭配：报纸一般用“份”计量，不说“这本报纸”，搭配不当。", "手机": "搭配：手机一般用“部”或“款”计量，不说“这本手机”，搭配不当。", "汽车": "语义：汽车不是出版物，“每个月出一次”句意不通。"}, "sentence_index": 0, "correct_answer": "杂志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份杂志每天早上都帮我做早饭。", "explanation": "这里应该用〈妈妈〉。杂志是刊物，不能做早饭；做早饭的应是人。"}, {"text": "这份杂志是我的上司，每个月给我发工资。", "explanation": "这里应该用〈公司〉。杂志是刊物，不能当上司发工资；发工资的应是公司。"}, {"text": "他是这份杂志的邻居。", "explanation": "这里应该用〈读者〉。杂志是出版物，不住在哪里，不会有邻居；人可以是杂志的读者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂志", "is_correct": true, "explanation": "“杂志”作主语，指按期出版的刊物还没有送到，句意完整。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，句中说的是出版物“还没有到”，句意不通。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是水的运动，不能用“这个月的……还没有到”来表达，句意不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是按期送来的出版物，“这个月的月亮还没有到”句意不通。"}], "explanations": {"杂志": "“杂志”作主语，指按期出版的刊物还没有送到，句意完整。", "太阳": "语义：太阳是天体，句中说的是出版物“还没有到”，句意不通。", "海浪": "语义：海浪是水的运动，不能用“这个月的……还没有到”来表达，句意不通。", "月亮": "语义：月亮是天体，不是按期送来的出版物，“这个月的月亮还没有到”句意不通。"}, "sentence_index": 6, "correct_answer": "杂志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份杂志是我们的老师，每周都给我们上课。", "explanation": "这里应该用〈课本〉。杂志是定期出版的刊物，不能给学生上课；上课用的是课本。"}, {"text": "我用这份杂志来煮面条。", "explanation": "这里应该用〈锅〉。杂志是刊物，不能用来煮面条，煮面条要用锅。"}, {"text": "我把这份杂志插进插座里照明。", "explanation": "这里应该用〈灯〉。杂志是刊物，不能插进插座照明，照明应用灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每个月都给这只杂志写稿。", "corrected_sentence": "他每个月都给这份杂志写稿。", "error_description": "错误：“杂志”的量词用错。“只”用于动物或成对物品之一，不能用于杂志，应用“份”，即“这份杂志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份的杂志每个月出一次。", "corrected_sentence": "这份杂志每个月出一次。", "error_description": "错误：指示词“这份”与名词之间不能加“的”，应说“这份杂志”，不说“这份的杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
