INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她笑着谢他一声过。", "corrected_sentence": "她笑着谢他一声。", "error_description": "“过”不能放在动量补语“一声”之后；若要表示完成，应说“谢过他一声”。本题的错误形式“谢他一声过”，正确形式为“谢他一声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下车的时候，奶奶回头谢着司机。", "corrected_sentence": "下车的时候，奶奶回头谢了司机。", "error_description": "体标错误：回头道谢是一次完成的动作，不能用表示持续的“着”。应说“谢了司机”，不能说“谢着司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
