INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感谢；向人表示感激。", "primary_collocate": null, "pronunciation": "xiè", "ipa": "ɕjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "他帮了我，我该谢他。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不用谢，这是我应该做的。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮了我这么多，我怎么谢你？", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天我想当面谢老师。", "target_word": "谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我回家，我谢了他很多次。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我一定要谢你。", "target_word": "谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都来谢他，因为他救了孩子。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友送我一本书，我得好好谢他。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用谢我，我们是好朋友。", "target_word": "谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把花送给老师，想谢老师这一年的照顾。", "target_word": "谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谢谢", "label": "重叠"}, {"form": "谢了", "label": "体标"}, {"form": "多谢", "label": "复合"}, {"form": "感谢", "label": "复合"}, {"form": "謝", "label": "繁体"}], "register": "通用", "sense_fingerprint": "谢：对帮助自己的人表示感激，后接对象，如“谢你”“谢老师”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4935a66f-b0a5-4cd5-b0f8-380dba48c616') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89376, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谢", "is_correct": true, "explanation": "正确。谢：对帮助自己的人表示感激。"}, {"text": "歇", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是休息。"}, {"text": "鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是鞋子。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xiè（第四声）声调不同，意思是书写。"}, {"text": "借", "is_correct": false, "explanation": "jiè 与 xiè 声母不同（j 与 x），意思是借用。"}, {"text": "血", "is_correct": false, "explanation": "xuè 与 xiè 的介音不同（u 与 i），意思是血液。"}], "explanations": {"谢": "正确。谢：对帮助自己的人表示感激。", "歇": "xiē（第一声）与 xiè（第四声）声调不同，意思是休息。", "鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是鞋子。", "写": "xiě（第三声）与 xiè（第四声）声调不同，意思是书写。", "借": "jiè 与 xiè 声母不同（j 与 x），意思是借用。", "血": "xuè 与 xiè 的介音不同（u 与 i），意思是血液。"}, "sentence_index": null, "correct_answer": "谢"}, "level_3": {"options": [{"text": "谢", "is_correct": true, "explanation": "谢：对帮助自己的人表示感激，符合句意。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”与“他帮了我”的感激语境相反，不能说“我该骂他”。"}, {"text": "怨", "is_correct": false, "explanation": "语义：“怨”是埋怨，与“他帮了我”的语境矛盾。"}, {"text": "瞪", "is_correct": false, "explanation": "语义：“瞪他”是瞪眼的神态动作，与“他帮了我”的感激语境不合。"}], "explanations": {"谢": "谢：对帮助自己的人表示感激，符合句意。", "骂": "语义：“骂”与“他帮了我”的感激语境相反，不能说“我该骂他”。", "怨": "语义：“怨”是埋怨，与“他帮了我”的语境矛盾。", "瞪": "语义：“瞪他”是瞪眼的神态动作，与“他帮了我”的感激语境不合。"}, "sentence_index": 0, "correct_answer": "谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把桌子谢干净了。", "explanation": "这里应该用〈擦〉。谢是道谢，不能用于擦拭桌子。"}, {"text": "他谢我一支笔。", "explanation": "这里应该用〈送〉。谢是道谢，不能带“我”和“一支笔”两个宾语表示赠送。"}, {"text": "他谢我一个好消息。", "explanation": "这里应该用〈告诉〉。谢是表示感激，不能带“消息”作宾语表示告知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89376, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "谢", "is_correct": true, "explanation": "正确。谢：对帮助自己的人表示感激。"}, {"text": "斜", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是倾斜。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是一些。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 xiè 声母不同（j 与 x），意思是界限。"}, {"text": "协", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是配合。"}], "explanations": {"谢": "正确。谢：对帮助自己的人表示感激。", "斜": "xié（第二声）与 xiè（第四声）声调不同，意思是倾斜。", "些": "xiē（第一声）与 xiè（第四声）声调不同，意思是一些。", "界": "jiè 与 xiè 声母不同（j 与 x），意思是界限。", "协": "xié（第二声）与 xiè（第四声）声调不同，意思是配合。"}, "sentence_index": null, "correct_answer": "谢"}, "level_3": {"options": [{"text": "谢", "is_correct": true, "explanation": "谢：对帮助过别人的人表示感激，符合句意。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是攻击，与“因为他救了孩子”的褒扬语境矛盾。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是回避，与“因为他救了孩子”的感激语境相反。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑他”指嘲笑，与“因为他救了孩子”的正面语境不搭配。"}], "explanations": {"谢": "谢：对帮助过别人的人表示感激，符合句意。", "打": "语义：“打”是攻击，与“因为他救了孩子”的褒扬语境矛盾。", "躲": "语义：“躲”是回避，与“因为他救了孩子”的感激语境相反。", "笑": "搭配：“笑他”指嘲笑，与“因为他救了孩子”的正面语境不搭配。"}, "sentence_index": 6, "correct_answer": "谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真地谢了我的情况。", "explanation": "这里应该用〈询问〉。谢是对帮助表示感激，不能用来打听情况。"}, {"text": "妈妈谢我早点睡。", "explanation": "这里应该用〈吩咐〉。谢表示感激，不能用来表示命令或嘱咐。"}, {"text": "他谢了比赛结果。", "explanation": "这里应该用〈宣布〉。谢不能带“比赛结果”作宾语表示公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下次见到他，我要好好跟他谢。", "corrected_sentence": "下次见到他，我要好好谢他。", "error_description": "“谢”是及物动词，前面不能加“跟”，应直接说“谢他”。错误形式为“跟他谢”，正确形式为“谢他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份礼物，我一定要当面谢了他。", "corrected_sentence": "这份礼物，我一定要当面谢他。", "error_description": "“一定要”表示将来的决心，动词后加“了”表示完成，与句意矛盾。错误形式“当面谢了他”，正确形式为“当面谢他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
