INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "而后是说在那件事之后，接着做下一件事。", "primary_collocate": null, "pronunciation": "ér hòu", "ipa": "ɚ˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "他先洗手，而后坐下吃饭。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先开会，而后一起去吃饭。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先做完作业，而后才能出去玩。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先想了想，而后慢慢地回答。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先看了看，而后买了一本书。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先学会写字，而后再学写文章。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先检查，而后给我开了药。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家先唱歌，而后分蛋糕。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先打了个电话，而后出门了。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先读一遍课文，而后做练习。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "先做一件事，接着做下一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“先洗手”之后接着做下一件事，“而后”正表示这种先后承接。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同时进行，与“先洗手”的先后顺序相矛盾。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”表示共同进行，与“先洗手”的先后次序不合。"}, {"text": "早已", "is_correct": false, "explanation": "搭配：“早已”表示已经在此之前完成，与“先”叠用不当，也不能承接后一个动作。"}], "explanations": {"而后": "正确。“先洗手”之后接着做下一件事，“而后”正表示这种先后承接。", "同时": "语义：“同时”表示同时进行，与“先洗手”的先后顺序相矛盾。", "一齐": "语义：“一齐”表示共同进行，与“先洗手”的先后次序不合。", "早已": "搭配：“早已”表示已经在此之前完成，与“先”叠用不当，也不能承接后一个动作。"}, "sentence_index": 0, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他虽然很累，而后还是坚持工作。", "explanation": "这里应该用〈但是〉。而后只表示先后承接，不表示转折，“虽然……但是……”结构中不能用而后。"}, {"text": "他不仅很聪明，而后也很努力。", "explanation": "这里应该用〈而且〉。“不仅……”要和“而且”搭配表示递进，而后只表示先后，不能用于此。"}, {"text": "他明明已经答应了，而后没有来。", "explanation": "这里应该用〈却〉。“明明”表示与结果相反，应用〈却〉表示转折；而后只表示承接，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“医生先检查”之后接着开药，“而后”表示这种先后承接。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同进行，与“先检查”的先后顺序不合。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：“反复”修饰多次重复的动作，与“检查”“开药”各一次的情形不搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突发，与“先检查，再开药”的有序安排不合。"}], "explanations": {"而后": "正确。“医生先检查”之后接着开药，“而后”表示这种先后承接。", "一起": "语义：“一起”表示共同进行，与“先检查”的先后顺序不合。", "反复": "搭配：“反复”修饰多次重复的动作，与“检查”“开药”各一次的情形不搭配。", "忽然": "语义：“忽然”表示突发，与“先检查，再开药”的有序安排不合。"}, "sentence_index": 6, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论成败，他而后都会努力。", "explanation": "这里应该用〈始终〉。“无论……都……”表示条件无关、一贯如此，而后只表示先后承接，不能用于此。"}, {"text": "而后，我们的第一步是确定目标。", "explanation": "这里应该用〈首先〉。“第一步”表示开始，而后表示承接前面的动作，二者矛盾，应用首先。"}, {"text": "这不是他的错，而后是我的错。", "explanation": "这里应该用〈而是〉。表示对立的判断要用而是，而后表示先后，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先吃饭，而后了出门散步。", "corrected_sentence": "他先吃饭，而后出门散步。", "error_description": "错误：“而后”是连词，后面不能带动态助词“了”。“而后”之后直接接下一个动作，应删去“了”，说“而后出门散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先吃饭，然后而后一起去散步。", "corrected_sentence": "我们先吃饭，而后一起去散步。", "error_description": "错误：“然后”与“而后”同义，不能叠用。正确形式是只用“而后”，说“我们先吃饭，而后一起去散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
