INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "然后，表示承接前面的动作或情况。", "primary_collocate": null, "pronunciation": "ér hòu", "ipa": "ɚ˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "先把窗户关好，而后再睡觉。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝完茶，而后站起来走了。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先写名字，而后写日期。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先笑了笑，而后点了点头。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先坐地铁，而后换公共汽车。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲课文，而后让学生回答问题。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先到银行取钱，而后去超市买菜。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把菜洗干净，而后再切。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先吃了饭，而后写作业。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家先热身，而后开始跑步。", "target_word": "而后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "承接前面的动作，表示然后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“先把窗户关好”之后再睡觉，“而后”表示这种承接关系。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同时进行，与“先关好窗户”的先后顺序相矛盾。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”表示共同进行，与“先”所示的先后次序不合。"}, {"text": "早已", "is_correct": false, "explanation": "搭配：“早已”表示先前已完成，与“先……再……”的承接结构叠用，语义重复且不通顺。"}], "explanations": {"而后": "正确。“先把窗户关好”之后再睡觉，“而后”表示这种承接关系。", "同时": "语义：“同时”表示同时进行，与“先关好窗户”的先后顺序相矛盾。", "一齐": "语义：“一齐”表示共同进行，与“先”所示的先后次序不合。", "早已": "搭配：“早已”表示先前已完成，与“先……再……”的承接结构叠用，语义重复且不通顺。"}, "sentence_index": 0, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他虽然很累，而后还是坚持把工作做完了。", "explanation": "这里应该用〈但是〉。而后只表示承接，不表示转折，“虽然……还是……”的让步结构中不能用而后。"}, {"text": "他不但会唱歌，而后也会跳舞。", "explanation": "这里应该用〈而且〉。“不但……”需要和“而且”搭配表示递进，而后只表示先后，不能用于此。"}, {"text": "这件事明明很简单，而后没有人做好。", "explanation": "这里应该用〈却〉。“明明”表示与结果相反，应用〈却〉表示转折；而后只表示承接，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而后", "is_correct": true, "explanation": "正确。“他先到银行取钱”之后去超市买菜，“而后”表示这种先后承接。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同行动，与“先到银行取钱”的先后顺序不合。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：“反复”修饰多次重复的动作，与“取钱”这一次性行动不搭配。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突发，与“先取钱，再去买菜”的有序安排不合。"}], "explanations": {"而后": "正确。“他先到银行取钱”之后去超市买菜，“而后”表示这种先后承接。", "一起": "语义：“一起”表示共同行动，与“先到银行取钱”的先后顺序不合。", "反复": "搭配：“反复”修饰多次重复的动作，与“取钱”这一次性行动不搭配。", "忽然": "语义：“忽然”表示突发，与“先取钱，再去买菜”的有序安排不合。"}, "sentence_index": 6, "correct_answer": "而后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论天气如何，我们而后都会出发。", "explanation": "这里应该用〈始终〉。“无论……都……”表示条件无关、一贯如此，而后只表示先后承接，不能用于此。"}, {"text": "这不是他的错，而后是我的错。", "explanation": "这里应该用〈而是〉。表示对立的判断要用而是，而后表示先后，不能用于此。"}, {"text": "而后，我们的第一步是复习课文。", "explanation": "这里应该用〈首先〉。“第一步”表示开始，而后表示承接前面的动作，二者矛盾，应用首先。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先把门锁好，再而后出门。", "corrected_sentence": "先把门锁好，而后出门。", "error_description": "错误：“而后”是连词，应放在后一分句开头，“再”可以放在它后面，不能放在它前面。“再而后”语序错误，应删去“再”或改为“而后再”，如“先把门锁好，而后出门。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她先去超市买菜，然后而后回家做饭。", "corrected_sentence": "她先去超市买菜，而后回家做饭。", "error_description": "错误：“然后”与“而后”同义，不能叠用。正确形式是只用“而后”，说“她先去超市买菜，而后回家做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盲文，用凸起的点表示的文字，供盲人触摸阅读。", "primary_collocate": null, "pronunciation": "diǎn zì", "ipa": "tjɛn˨˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "盲人用手指摸点字，就能读书。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是用点字印的。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯按钮旁边有点字，盲人也能用。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学习点字，现在可以自己读报。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲校的老师教孩子们摸点字。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点字是由很多凸起的小点组成的。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手指轻轻摸着点字，读得很慢。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药盒上也印着点字，盲人可以知道药名。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会点字以后，他每天晚上都读一会儿。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点字要用手摸，不能用眼睛看。", "target_word": "点字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "點字", "label": "繁体"}, {"form": "点字书", "label": "复合"}], "register": "中性", "sense_fingerprint": "盲人用手指触摸的凸点文字（盲文）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点字", "is_correct": true, "explanation": "正确：点字是盲文，用凸起的小点表示，盲人用手指摸着读。"}, {"text": "电子", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，“电子”指带电的微粒或电子产品，不是盲文。"}, {"text": "点子", "is_correct": false, "explanation": "“子”读轻声，与 zì（第四声）声调不同，“点子”指主意或窍门。"}, {"text": "垫子", "is_correct": false, "explanation": "diàn（第四声）与 diǎn（第三声）声调不同，且“子”读轻声，“垫子”指垫在下面的东西。"}], "explanations": {"点字": "正确：点字是盲文，用凸起的小点表示，盲人用手指摸着读。", "电子": "diàn（第四声）与 diǎn（第三声）声调不同，“电子”指带电的微粒或电子产品，不是盲文。", "点子": "“子”读轻声，与 zì（第四声）声调不同，“点子”指主意或窍门。", "垫子": "diàn（第四声）与 diǎn（第三声）声调不同，且“子”读轻声，“垫子”指垫在下面的东西。"}, "sentence_index": null, "correct_answer": "点字"}, "level_3": {"options": [{"text": "点字", "is_correct": true, "explanation": "正确：盲人用手指摸的凸点文字就是点字，可以“摸点字读书”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是建筑物，摸墙不能读书，与“就能读书”的句意不合。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“摸”要接可以触摸的东西，“味道”不能用手摸。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“摸”的对象要能被触摸，“声音”不能用手摸。"}], "explanations": {"点字": "正确：盲人用手指摸的凸点文字就是点字，可以“摸点字读书”。", "墙": "语义：墙是建筑物，摸墙不能读书，与“就能读书”的句意不合。", "味道": "搭配：“摸”要接可以触摸的东西，“味道”不能用手摸。", "声音": "搭配：“摸”的对象要能被触摸，“声音”不能用手摸。"}, "sentence_index": 0, "correct_answer": "点字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他尝了尝点字，觉得有点咸。", "explanation": "这里应该用〈菜〉。点字是用手指摸读的凸点文字，不能吃，也没有咸淡。"}, {"text": "他用点字修好了电脑。", "explanation": "这里应该用〈工具〉。点字是盲人阅读的凸点文字，不是修理用的工具，不能说“用点字修好”。"}, {"text": "他听到了窗外的点字。", "explanation": "这里应该用〈声音〉。点字是用手摸读的文字，不能被耳朵听到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点字", "is_correct": true, "explanation": "正确：“摸着点字读得很慢”，点字是可以用手指摸读的文字。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以读的文字，“读得很慢”与窗户不合。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是器皿，不能被读，句子的“读”与“水杯”不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“摸”要接实物，“颜色”不能用手摸着读。"}], "explanations": {"点字": "正确：“摸着点字读得很慢”，点字是可以用手指摸读的文字。", "窗户": "语义：窗户不是可以读的文字，“读得很慢”与窗户不合。", "水杯": "语义：水杯是器皿，不能被读，句子的“读”与“水杯”不合。", "颜色": "搭配：“摸”要接实物，“颜色”不能用手摸着读。"}, "sentence_index": 6, "correct_answer": "点字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的点字很甜。", "explanation": "这里应该用〈味道〉。点字是凸点文字，不是食物的属性，不能说“很甜”。"}, {"text": "我们去餐厅点了几个点字。", "explanation": "这里应该用〈菜〉。“点”后接菜、饮料等可以点的东西，点字是文字，不能被点。"}, {"text": "他把点字放进了冰箱。", "explanation": "这里应该用〈牛奶〉。点字是一种文字形式，不是能放进冰箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些纸上印满了点字过。", "corrected_sentence": "这些纸上印满了点字。", "error_description": "体标错误：“过”只能用在动词后，表示经历，“点字”是名词，后面不能加“过”。应删去“过”，改为“印满了点字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学会了一把点字，现在能自己读书。", "corrected_sentence": "她学会了一种点字，现在能自己读书。", "error_description": "量词错误：“把”用于有柄的器具，不能计量点字。应改为“种”，表示一种文字系统。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
