INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89383, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电视台是制作并播出电视节目的地方。", "primary_collocate": null, "pronunciation": "diàn shì tái", "ipa": "tjɛn˥˩ ʂʅ˥˩ tʰaɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这个电视台每天都有新闻。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在电视台工作。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台做了很多好看的节目。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们昨天去电视台参观了。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电视台的节目很有意思。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台的门口站着很多人。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去电视台当主持人。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台离我家不远。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台今晚有一个唱歌节目。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带我去过电视台一次。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "制作并播出电视节目的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视台", "is_correct": true, "explanation": "正确：电视台是做节目的机构，每天播出新闻，符合句意。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不播放新闻，“这个超市每天都有新闻”说不通。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不发布新闻，句子说不通。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“新闻”通常由媒体发布，菜市场不与“有新闻”搭配。"}], "explanations": {"电视台": "正确：电视台是做节目的机构，每天播出新闻，符合句意。", "超市": "语义：超市不播放新闻，“这个超市每天都有新闻”说不通。", "理发店": "语义：理发店不发布新闻，句子说不通。", "菜市场": "搭配：“新闻”通常由媒体发布，菜市场不与“有新闻”搭配。"}, "sentence_index": 0, "correct_answer": "电视台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客厅里的电视台坏了，我们只好去修。", "explanation": "替换用错：〈电视台〉是播节目的机构，不是电视机。说“坏了”应用〈电视机〉。"}, {"text": "我家附近有一台电视台，很有名。", "explanation": "量词用错：〈电视台〉是机构，应用〈家〉，“台”多用于电视机等机器。"}, {"text": "这个电视台很小，屏幕只有十四寸。", "explanation": "语义用错：〈电视台〉指机构，没有屏幕；有屏幕的应说〈电视机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视台", "is_correct": true, "explanation": "正确：电视台是制作节目的机构，“当主持人”需要在这样的单位工作。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不制作节目，去医院当主持人说不通。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场不招主持人，句子说不通。"}, {"text": "洗衣店", "is_correct": false, "explanation": "搭配：“当主持人”一般指在节目机构工作，洗衣店不与之搭配。"}], "explanations": {"电视台": "正确：电视台是制作节目的机构，“当主持人”需要在这样的单位工作。", "医院": "语义：医院不制作节目，去医院当主持人说不通。", "停车场": "语义：停车场不招主持人，句子说不通。", "洗衣店": "搭配：“当主持人”一般指在节目机构工作，洗衣店不与之搭配。"}, "sentence_index": 6, "correct_answer": "电视台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天晚上都电视台新闻。", "explanation": "词性用错：〈电视台〉是名词，不能作动词，播放新闻应说“播新闻”。"}, {"text": "我每天开车时都收听电视台，里面的音乐很好听。", "explanation": "语义用错：〈电视台〉播放的是电视节目，收听广播应说〈电台〉。"}, {"text": "我们周末去电视台爬山，山上的风景很好。", "explanation": "语义用错：〈电视台〉是制作播放节目的机构，不是可以爬的地方；爬山应去〈山〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视台每天都播新闻。", "corrected_sentence": "这家电视台每天都播新闻。", "error_description": "错误：量词用错。〈电视台〉是机构，应用“家”，“台”用于电视机等机器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友电视台工作。", "corrected_sentence": "我的朋友在电视台工作。", "error_description": "错误：漏掉介词“在”。“在电视台”表示工作地点，应说“在电视台工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
