INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "制作并播放电视节目的机构。", "primary_collocate": null, "pronunciation": "diàn shì tái", "ipa": "tjɛn˥˩ ʂʅ˥˩ tʰaɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这家电视台是一九五八年成立的。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台正在找新的节目主持人。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家电视台播放了这场比赛。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视台负责制作和播放节目。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方电视台的新闻很受欢迎。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台请了很多演员来演电视剧。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们电视台明年要做新节目。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电视台的春节晚会很有名。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台决定下周播这部电视剧。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电视台有三百多个工作人员。", "target_word": "电视台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "制作并播放电视节目的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视台", "is_correct": true, "explanation": "正确：电视台是机构，一九五八年成立，符合“成立”的语境。"}, {"text": "电视机", "is_correct": false, "explanation": "语义：电视机是机器，不能“成立”，句子说不通。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不是机构，不能说“是……成立的”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“成立”一般用于机构，“电影”不与“成立”搭配。"}], "explanations": {"电视台": "正确：电视台是机构，一九五八年成立，符合“成立”的语境。", "电视机": "语义：电视机是机器，不能“成立”，句子说不通。", "西瓜": "语义：西瓜不是机构，不能说“是……成立的”。", "电影": "搭配：“成立”一般用于机构，“电影”不与“成立”搭配。"}, "sentence_index": 0, "correct_answer": "电视台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这家电视台摆在客厅的桌子上。", "explanation": "语义用错：〈电视台〉是机构，不能摆放；指电视机应说〈电视机〉。"}, {"text": "我妈妈每天去这家电视台买书，因为那里的书很便宜。", "explanation": "语义用错：〈电视台〉是制作播放节目的机构，不是卖书的地方；买书应去〈书店〉。"}, {"text": "我们每天晚上都电视台一会儿。", "explanation": "词性用错：把〈电视台〉当成了“看”“播放”一类的动词用，但它是名词，应说“看电视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视台", "is_correct": true, "explanation": "正确：“做新节目”需要制作节目的机构，电视台符合句意。"}, {"text": "加油站", "is_correct": false, "explanation": "语义：加油站不制作节目，句子说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁不制作节目，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“做节目”指制作节目的单位，厨房不与之搭配。"}], "explanations": {"电视台": "正确：“做新节目”需要制作节目的机构，电视台符合句意。", "加油站": "语义：加油站不制作节目，句子说不通。", "地铁": "语义：地铁不制作节目，句子说不通。", "厨房": "搭配：“做节目”指制作节目的单位，厨房不与之搭配。"}, "sentence_index": 6, "correct_answer": "电视台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在电视台看病，医生说没什么大事。", "explanation": "语义用错：〈电视台〉是制作播放节目的机构，不是看病的地方；看病应去〈医院〉。"}, {"text": "我昨天去这家电视台存钱，窗口排了很长的队。", "explanation": "语义用错：〈电视台〉是制作播放节目的机构，不办理存取款；存钱应去〈银行〉。"}, {"text": "这家电视台是一只小鸟，飞得很快。", "explanation": "语义用错：〈电视台〉是机构，不是动物，也不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电视台最近搬了新址。", "corrected_sentence": "这家电视台最近搬了新址。", "error_description": "错误：量词用错。〈电视台〉是机构，应用“家”，“台”用于电视机等机器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥想进一只电视台工作。", "corrected_sentence": "我表哥想进一家电视台工作。", "error_description": "错误：量词用错。〈电视台〉是机构，应用“家”，“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
