INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89386, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "自己，也指自己家里或自己一方。", "primary_collocate": null, "pronunciation": "zì jiā", "ipa": "tsɨ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他不吃外面的饭，只吃自家做的。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人的事少管，自家的事要管好。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，自家球队赢了对手。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人的话可以不听，自家的错要承认。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在自家门口种了两棵树。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是自家的东西，你随便用。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先管好自家，再去帮别人。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷都来为自家的队伍加油。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自家的小狗带到了公园。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在自家的花园里请客吃饭。", "target_word": "自家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自家人", "label": "复合"}], "register": "口语", "sense_fingerprint": "泛指自己，或自己家里、自己一方，常与别人、对方相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会做饭，「只吃桌子做的」说不通。"}, {"text": "对方", "is_correct": false, "explanation": "语义：「对方」指另一方，不是做饭的人，与句意不合。"}, {"text": "自家", "is_correct": true, "explanation": "正确：「自家做的」指自己家做的，与「不吃外面的饭」相对，符合句意。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不做饭，「只吃银行做的」说不通。"}], "explanations": {"桌子": "语义：桌子不会做饭，「只吃桌子做的」说不通。", "对方": "语义：「对方」指另一方，不是做饭的人，与句意不合。", "自家": "正确：「自家做的」指自己家做的，与「不吃外面的饭」相对，符合句意。", "银行": "语义：银行不做饭，「只吃银行做的」说不通。"}, "sentence_index": 0, "correct_answer": "自家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事自家们都知道了。", "explanation": "这里应该用〈大家〉。〈自家〉是代词，后面不能加「们」。"}, {"text": "自家，你们好！今天我们一起上课。", "explanation": "这里应该用〈大家〉。〈自家〉指自己或自己一方，不能用来称呼在场的别人。"}, {"text": "两个自家在花园里聊天。", "explanation": "这里应该用〈两个人〉。〈自家〉是代词，不能直接受数量词修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：「管好」不接「天气」，「先管好天气」说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：「管好」不接「月亮」，「先管好月亮」说不通。"}, {"text": "自家", "is_correct": true, "explanation": "正确：「管好自家」指管好自己家或自己一方，符合句意。"}, {"text": "别人", "is_correct": false, "explanation": "语义：「管好别人，再去帮别人」自相矛盾。"}], "explanations": {"天气": "搭配：「管好」不接「天气」，「先管好天气」说不通。", "月亮": "搭配：「管好」不接「月亮」，「先管好月亮」说不通。", "自家": "正确：「管好自家」指管好自己家或自己一方，符合句意。", "别人": "语义：「管好别人，再去帮别人」自相矛盾。"}, "sentence_index": 6, "correct_answer": "自家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三位自家在门口等你。", "explanation": "这里应该用〈三位朋友〉。〈自家〉是代词，不能和量词「位」组合。"}, {"text": "他听了这个消息，很自家地笑了。", "explanation": "这里应该用〈开心〉。〈自家〉是代词，不能受「很」修饰，也不能描写笑的样子。"}, {"text": "大家一下子自家都安静了。", "explanation": "这里应该用〈突然〉。〈自家〉没有“突然”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总自家门口晒太阳。", "corrected_sentence": "他总在自家门口晒太阳。", "error_description": "介词缺失：表示地点的「自家门口」前应加介词「在」，漏了「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在自家们院子里玩耍。", "corrected_sentence": "她在自家院子里玩耍。", "error_description": "多余的后缀：「们」不能加在「自家」后面，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
