INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89391, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "航空公司是有很多飞机，带人坐飞机去远方的公司。", "primary_collocate": null, "pronunciation": "háng kōng gōng sī", "ipa": "xɑŋ˧˥ kʰʊŋ˥ kʊŋ˥ sɨ˥", "syllable_count": 4, "sentences": [{"text": "这家航空公司的飞机很新。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在一家航空公司工作。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪家航空公司的机票最便宜？", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司每天有三个航班去上海。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司给我们换了一个座位。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当航空公司的飞行员。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给航空公司打了电话，问行李的事。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司的服务特别好。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司把我的行李送到了酒店。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内有很多航空公司。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "有飞机、卖机票、带乘客飞到远方的公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空公司", "is_correct": true, "explanation": "正确：航空公司拥有飞机，可以说“这家航空公司的飞机很新”。"}, {"text": "火车站", "is_correct": false, "explanation": "语义：火车站没有飞机，“这家火车站的飞机很新”说不通。"}, {"text": "出版社", "is_correct": false, "explanation": "语义：出版社不经营空中运输，与飞机无关，句子说不通。"}, {"text": "旅游团", "is_correct": false, "explanation": "搭配：“这家”修饰企业或店铺，“旅游团”应说“这个”或“这支”，不能说“这家旅游团”。"}], "explanations": {"航空公司": "正确：航空公司拥有飞机，可以说“这家航空公司的飞机很新”。", "火车站": "语义：火车站没有飞机，“这家火车站的飞机很新”说不通。", "出版社": "语义：出版社不经营空中运输，与飞机无关，句子说不通。", "旅游团": "搭配：“这家”修饰企业或店铺，“旅游团”应说“这个”或“这支”，不能说“这家旅游团”。"}, "sentence_index": 0, "correct_answer": "航空公司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家航空公司每年出版很多小说。", "explanation": "这里应该用〈出版社〉。出版图书是出版社的业务，航空公司经营的是客货空中运输，不出版小说。"}, {"text": "这家航空公司每天下午三点下课。", "explanation": "这里应该用〈学校〉。下课是学校或班级的事，航空公司是企业，不能下课。"}, {"text": "这家航空公司每天有三班渡轮去上海。", "explanation": "这里应该用〈航运公司〉。渡轮班次属于航运业务，航空公司经营的是飞机运输，不提供渡轮服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空公司", "is_correct": true, "explanation": "正确：航空公司有人工作、可以接受咨询，可以说“我给航空公司打了电话”。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不处理行李问题，“问行李的事”说不通。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园与航班行李无关，句子说不通。"}, {"text": "天气预报", "is_correct": false, "explanation": "搭配：“给……打电话”的对象应是能接电话办事的机构，“天气预报”不能咨询行李的事。"}], "explanations": {"航空公司": "正确：航空公司有人工作、可以接受咨询，可以说“我给航空公司打了电话”。", "图书馆": "语义：图书馆不处理行李问题，“问行李的事”说不通。", "幼儿园": "语义：幼儿园与航班行李无关，句子说不通。", "天气预报": "搭配：“给……打电话”的对象应是能接电话办事的机构，“天气预报”不能咨询行李的事。"}, "sentence_index": 6, "correct_answer": "航空公司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐航空公司去北京。", "explanation": "这里应该用〈飞机〉。“坐”后接交通工具，航空公司是企业，不能当交通工具。"}, {"text": "飞机在航空公司降落。", "explanation": "这里应该用〈机场〉。飞机降落的地点是机场，航空公司是企业，不是场所。"}, {"text": "这家航空公司每天接待很多病人。", "explanation": "这里应该用〈医院〉。接待病人是医院的职能，航空公司经营客货空中运输，不接待病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位航空公司的总部在上海。", "corrected_sentence": "这家航空公司的总部在上海。", "error_description": "量词错误：“航空公司”是企业，应用量词“家”，“位”用于人，不能修饰公司。应说“这家航空公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家航空公司的招了很多飞行员。", "corrected_sentence": "这家航空公司招了很多飞行员。", "error_description": "错误：“航空公司的招了”，“的”不能加在主语和动词之间。正确：“航空公司招了”，去掉多余的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
