INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拥有飞机，经营客货空中运输业务的企业。", "primary_collocate": null, "pronunciation": "háng kōng gōng sī", "ipa": "xɑŋ˧˥ kʰʊŋ˥ kʊŋ˥ sɨ˥", "syllable_count": 4, "sentences": [{"text": "这家航空公司拥有两百架飞机。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司不但运送乘客，还运送货物。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司今年新开了十条国际航线。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司去年的利润增加了不少。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家航空公司同时提高了货运价格。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司需要定期检查每一架飞机。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司的货运生意做得很大。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家大型航空公司负责货运业务。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司从海外引进了十架新飞机。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司招聘了很多新员工。", "target_word": "航空公司", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "拥有飞机、经营客运和货运航空业务的企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空公司", "is_correct": true, "explanation": "正确：只有拥有飞机的企业才能说“拥有两百架飞机”。"}, {"text": "出租车公司", "is_correct": false, "explanation": "语义：出租车公司只经营出租车，不拥有飞机，句子说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不经营空中运输，也不拥有飞机，句子说不通。"}, {"text": "旅游团", "is_correct": false, "explanation": "搭配：“这家”修饰企业或店铺，“旅游团”应说“这个”或“这支”，不能说“这家旅游团”。"}], "explanations": {"航空公司": "正确：只有拥有飞机的企业才能说“拥有两百架飞机”。", "出租车公司": "语义：出租车公司只经营出租车，不拥有飞机，句子说不通。", "医院": "语义：医院不经营空中运输，也不拥有飞机，句子说不通。", "旅游团": "搭配：“这家”修饰企业或店铺，“旅游团”应说“这个”或“这支”，不能说“这家旅游团”。"}, "sentence_index": 0, "correct_answer": "航空公司"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家航空公司去年生产了五十万辆汽车。", "explanation": "这里应该用〈汽车厂〉。生产汽车是汽车厂的业务，航空公司经营的是客货空中运输，不生产汽车。"}, {"text": "这家航空公司拥有很多货船。", "explanation": "这里应该用〈航运公司〉。航运公司经营货船，航空公司经营的是飞机，不能拥有货船。"}, {"text": "这家航空公司成功发射了一颗卫星。", "explanation": "这里应该用〈航天公司〉。发射卫星是航天公司的业务，航空公司经营的是客货空中运输。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空公司", "is_correct": true, "explanation": "正确：航空公司经营货运业务，才能说“货运生意做得很大”。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不做货运，“货运生意”与银行无关，句子说不通。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园不做货运，句子说不通。"}, {"text": "拆迁队", "is_correct": false, "explanation": "搭配：“这家”修饰企业或店铺，“拆迁队”应说“一支”或“一个”，不能说“这家拆迁队”。"}], "explanations": {"航空公司": "正确：航空公司经营货运业务，才能说“货运生意做得很大”。", "银行": "语义：银行不做货运，“货运生意”与银行无关，句子说不通。", "幼儿园": "语义：幼儿园不做货运，句子说不通。", "拆迁队": "搭配：“这家”修饰企业或店铺，“拆迁队”应说“一支”或“一个”，不能说“这家拆迁队”。"}, "sentence_index": 6, "correct_answer": "航空公司"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "货船在航空公司靠岸。", "explanation": "这里应该用〈码头〉。货船靠岸的地方是码头，航空公司是企业，不是场所。"}, {"text": "航空公司治好了他的病。", "explanation": "这里应该用〈医院〉。治病是医院的职能，航空公司不能治病。"}, {"text": "航空公司开学了。", "explanation": "这里应该用〈学校〉。开学是学校的事，航空公司是企业，不能开学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条航空公司去年新买了五十架飞机。", "corrected_sentence": "这家航空公司去年新买了五十架飞机。", "error_description": "量词错误：“航空公司”应用量词“家”，“条”用于细长的物件，不能修饰公司。应说“这家航空公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们和一家航空公司的签了合同。", "corrected_sentence": "我们和一家航空公司签了合同。", "error_description": "错误：“航空公司的签了”，“的”后面不能直接接动词，应去掉。正确：去掉多余的“的”，说“航空公司签了合同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
