INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89395, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人生是一个人从生下来到老的一辈子。", "primary_collocate": null, "pronunciation": "rén shēng", "ipa": "ʐən˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "人生很长,也很短,要好好过。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从出生到老去,这就是一个人的人生。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的人生过得平平安安。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的人生一直都很简单,只想过平静的日子。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生这么长,你不要怕失败。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说,人生有高兴的事,也有难过的事。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的人生不可能一直顺利。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生只有一次,所以我们要做喜欢的事。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人回头看自己的人生,觉得没有后悔的事。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的人生才刚刚开始。", "target_word": "人生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段人生", "label": "量词"}, {"form": "人生观", "label": "复合"}, {"form": "人生路", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词:一个人从出生到老去的一辈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9529bd-5bd4-47cc-94ca-e0bf014980b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89395, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生（rén shēng）指一个人从出生到老去的一辈子，是正确答案。"}, {"text": "人称", "is_correct": false, "explanation": "sh 与 ch 声母不同，人称（rén chēng）指第一人称、第二人称等，不是一辈子。"}, {"text": "人身", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（ng 与 n），人身指人的身体。"}, {"text": "认生", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，认生指小孩怕见陌生人。"}], "explanations": {"人生": "人生（rén shēng）指一个人从出生到老去的一辈子，是正确答案。", "人称": "sh 与 ch 声母不同，人称（rén chēng）指第一人称、第二人称等，不是一辈子。", "人身": "shēng 与 shēn 韵母不同（ng 与 n），人身指人的身体。", "认生": "rén（第二声）与 rèn（第四声）声调不同，认生指小孩怕见陌生人。"}, "sentence_index": null, "correct_answer": "人生"}, "level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生指一个人的一辈子，可以说“很长”“很短”，也可以说“过”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“很长、很短”来描写，也不能“过”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“过”不搭配“作业”，应说“做”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是物品，不是可以“很长、很短”地“过”的经历。"}], "explanations": {"人生": "人生指一个人的一辈子，可以说“很长”“很短”，也可以说“过”。", "天气": "语义：天气不能用“很长、很短”来描写，也不能“过”。", "作业": "搭配：“过”不搭配“作业”，应说“做”。", "电脑": "语义：电脑是物品，不是可以“很长、很短”地“过”的经历。"}, "sentence_index": 0, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在超市买了一斤人生。", "explanation": "这里不这么用。人生是抽象的一辈子，不是能称重买卖的物品，不能用“斤”计量。"}, {"text": "教室里坐着三十个人生。", "explanation": "这里不这么用。人生不用来数人，指人应说“人”，“人生”是抽象概念。"}, {"text": "她把人生洗干净挂在了阳台上。", "explanation": "这里不这么用。“人生”指人的一辈子，不是可以洗、可以挂的具体物件；洗、挂的对象应是〈衣服〉这类具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人生", "is_correct": true, "explanation": "人生指一个人的一辈子，可以说“一个人的人生不可能一直顺利”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“顺利”形容事情的进展，不说“工资顺利”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是物体，不会“一直顺利”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能“一直顺利”。"}], "explanations": {"人生": "人生指一个人的一辈子，可以说“一个人的人生不可能一直顺利”。", "工资": "搭配：“顺利”形容事情的进展，不说“工资顺利”。", "房子": "语义：房子是物体，不会“一直顺利”。", "手机": "语义：手机是物品，不能“一直顺利”。"}, "sentence_index": 6, "correct_answer": "人生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的人生有十年。", "explanation": "这里应该用〈寿命〉。“人生”只用于人，车辆等物品的使用年限要说“寿命”。"}, {"text": "我每天早上用人生刷牙。", "explanation": "这里不这么用。“人生”指人的一辈子，是抽象的，不是可以拿来刷牙的工具；刷牙要用〈牙刷〉。"}, {"text": "人生的小明今天去上学了。", "explanation": "这里不这么用。“人生”指一个人的一辈子，不是人，不能用“人生的”修饰某个人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一座很长的人生。", "corrected_sentence": "这是一段很长的人生。", "error_description": "错误：“人生”指一段经历，量词应为“段”，不能用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只有一座人生，要好好珍惜。", "corrected_sentence": "他只有一次人生，要好好珍惜。", "error_description": "错误：“人生”指一辈子，计量应用“次”，不能用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
