INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89397, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "着花是说植物开出花来。", "primary_collocate": null, "pronunciation": "zhuó huā", "ipa": "ʈʂwo˧˥ xwa˥", "syllable_count": 2, "sentences": [{"text": "这棵桃树今年三月就着花了。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的梅树还没有着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果树要等到四月才着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆兰花养了两年，终于着花了。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，山上的树都着花了。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏树着花以后，山上特别好看。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草不着花，只长叶子。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，梨树今年着花很晚。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷种的石榴树去年没着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，果树着花比去年早。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "着花了", "label": "体标"}, {"form": "着过花", "label": "体标"}], "register": "书面", "sense_fingerprint": "植物到了时候开出花来，主语多是树、草、盆栽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着花", "is_correct": true, "explanation": "正确：“着花了”说植物开出花来，与“三月就”的时间搭配。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：下雪是天气现象，桃树不会下雪，句子说不通。"}, {"text": "入睡", "is_correct": false, "explanation": "搭配：“入睡”的主语须是人或动物，不能与“桃树”搭配。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：只有金属等物件才会生锈，树不会生锈。"}], "explanations": {"着花": "正确：“着花了”说植物开出花来，与“三月就”的时间搭配。", "下雪": "语义：下雪是天气现象，桃树不会下雪，句子说不通。", "入睡": "搭配：“入睡”的主语须是人或动物，不能与“桃树”搭配。", "生锈": "语义：只有金属等物件才会生锈，树不会生锈。"}, "sentence_index": 0, "correct_answer": "着花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "种子终于着花了。", "explanation": "这里应该用〈发芽〉。种子长出幼芽时说发芽，着花是植物开花，种子不会开花。"}, {"text": "河水终于着花了。", "explanation": "这里应该用〈结冰〉。着花只用于植物，河水不能开花。"}, {"text": "这把旧铁锁着花了。", "explanation": "这里应该用〈生锈〉。着花只用于植物，铁锁不能开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着花", "is_correct": true, "explanation": "正确：草是植物，“不着花”说的是草不开花，只长叶子。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，与草开不开花无关，“不下雨”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：草不会唱歌，“不唱歌”说不通。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”的主语须是能写字的人，草不能写字。"}], "explanations": {"着花": "正确：草是植物，“不着花”说的是草不开花，只长叶子。", "下雨": "语义：下雨是天气现象，与草开不开花无关，“不下雨”说不通。", "唱歌": "语义：草不会唱歌，“不唱歌”说不通。", "写字": "搭配：“写字”的主语须是能写字的人，草不能写字。"}, "sentence_index": 6, "correct_answer": "着花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗终于着花了。", "explanation": "这里应该用〈长毛〉。着花只用于植物，小狗不会开花。"}, {"text": "这块木板终于着花了。", "explanation": "这里应该用〈发霉〉。木板受潮会发霉，着花只用于植物。"}, {"text": "这座桥终于着花了。", "explanation": "这里应该用〈竣工〉。桥修好时说竣工，着花只用于植物，桥不会开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆梅花去年冬天就着花过。", "corrected_sentence": "这盆梅花去年冬天就着花了。", "error_description": "体标位置错误：“着花”是动宾结构，体标“过”不能放在“花”后。这里表示已经开花，应说“着花了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这株仙人掌从来没着花了。", "corrected_sentence": "这株仙人掌从来没着过花。", "error_description": "体标错误：“从来没”表示从未有过的经历，动词后应用“过”，不能用“了”。“着花了”应改为“着过花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
