INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "植物开花。", "primary_collocate": null, "pronunciation": "zhuó huā", "ipa": "ʈʂwo˧˥ xwa˥", "syllable_count": 2, "sentences": [{"text": "这棵梨树栽了五年，今年第一次着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园子里的樱桃树已经着花了。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种竹子一辈子只着花一次。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台上的茶花天气一暖就着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桃树着花以后，蜜蜂都飞来了。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆花长得很好，可是一直不着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上的野梅一到二月就着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老树去年着花了，今年却没有。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要多浇水，这棵树才会着花。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果树先着花，然后才结果子。", "target_word": "着花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "着花了", "label": "体标"}, {"form": "着过花", "label": "体标"}], "register": "书面", "sense_fingerprint": "植物开花，说明树木或花草进入开花的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着花", "is_correct": true, "explanation": "正确：梨树是植物，“今年第一次着花”说它开出了第一次花。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：树木不会冒烟，“第一次冒烟”说不通。"}, {"text": "打鼾", "is_correct": false, "explanation": "搭配：“打鼾”的主语须是人或动物，不能与“梨树”搭配。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：树不会结婚，“第一次结婚”说不通。"}], "explanations": {"着花": "正确：梨树是植物，“今年第一次着花”说它开出了第一次花。", "冒烟": "语义：树木不会冒烟，“第一次冒烟”说不通。", "打鼾": "搭配：“打鼾”的主语须是人或动物，不能与“梨树”搭配。", "结婚": "语义：树不会结婚，“第一次结婚”说不通。"}, "sentence_index": 0, "correct_answer": "着花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只母鸡天气一暖就着花了。", "explanation": "这里应该用〈下蛋〉。着花只用于植物，母鸡不会开花。"}, {"text": "这把椅子一到春天就着花了。", "explanation": "这里应该用〈发霉〉。椅子受潮会发霉，着花只用于植物。"}, {"text": "河面天气一暖就着花了。", "explanation": "这里应该用〈化冻〉。河面天气变暖时说化冻，着花只用于植物，水面不会开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着花", "is_correct": true, "explanation": "正确：野梅是植物，“一到二月就着花”说它二月开花。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：梅树不会生锈，“就生锈”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：梅树不会唱歌，句子说不通。"}, {"text": "签字", "is_correct": false, "explanation": "搭配：“签字”的主语须是人，不能与“野梅”搭配。"}], "explanations": {"着花": "正确：野梅是植物，“一到二月就着花”说它二月开花。", "生锈": "语义：梅树不会生锈，“就生锈”说不通。", "唱歌": "语义：梅树不会唱歌，句子说不通。", "签字": "搭配：“签字”的主语须是人，不能与“野梅”搭配。"}, "sentence_index": 6, "correct_answer": "着花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头一到春天就着花了。", "explanation": "这里应该用〈风化〉。石头会风化，不会开花；着花只用于植物。"}, {"text": "这台电脑一到春天就着花了。", "explanation": "这里应该用〈死机〉。电脑出故障说死机，着花只用于植物。"}, {"text": "他听到表扬就着花了。", "explanation": "这里应该用〈脸红〉。着花只用于植物，不能形容人的脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆茶花今年冬天第一次着花过。", "corrected_sentence": "这盆茶花今年冬天第一次着花。", "error_description": "体标错误：“过”须紧跟“着”，应说“着过花”，不能说“着花过”。这里强调首次开花，也可直接说“第一次着花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵老梨树以前过着花。", "corrected_sentence": "这棵老梨树以前着过花。", "error_description": "体标位置错误：“过”应紧跟动词“着”，说“着过花”，表示曾经开过花；不能放在“着”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
