INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89399, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱给需要的人，帮他做事或读书。", "primary_collocate": null, "pronunciation": "zī zhù", "ipa": "tsɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "王先生资助这个女孩上大学。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想资助他读完高中。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位好心人资助他们一家开了小店。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月资助弟弟读书。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用退休金资助了两个穷孩子上学。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司资助他去国外学习了两年。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不是叔叔资助，我就不能念书了。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠别人资助，才读完了大学。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位校长资助过很多没钱的学生。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想资助一个山区的孩子读书。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "资助了", "label": "体标"}, {"form": "资助过", "label": "体标"}, {"form": "资助者", "label": "复合"}], "register": "正式", "sense_fingerprint": "出钱帮人读书或做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确答案。资助指把钱给需要的人，帮他做事或读书。"}, {"text": "支柱", "is_correct": false, "explanation": "zhī（第一声）与 zī（第一声）声母不同（zh 与 z），意思是支撑物体的柱子。"}, {"text": "自主", "is_correct": false, "explanation": "zì zhǔ 与 zī zhù 两个音节的声调都不同，意思是自己做主。"}, {"text": "资质", "is_correct": false, "explanation": "zhì（第四声）与 zhù（第四声）韵母不同（i 与 u），意思是资格或素质。"}, {"text": "自住", "is_correct": false, "explanation": "zì（第四声）与 zī（第一声）声调不同，意思是自己居住。"}], "explanations": {"资助": "正确答案。资助指把钱给需要的人，帮他做事或读书。", "支柱": "zhī（第一声）与 zī（第一声）声母不同（zh 与 z），意思是支撑物体的柱子。", "自主": "zì zhǔ 与 zī zhù 两个音节的声调都不同，意思是自己做主。", "资质": "zhì（第四声）与 zhù（第四声）韵母不同（i 与 u），意思是资格或素质。", "自住": "zì（第四声）与 zī（第一声）声调不同，意思是自己居住。"}, "sentence_index": null, "correct_answer": "资助"}, "level_3": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确。资助指出钱帮人读书，与“王先生出钱让女孩上大学”相符。"}, {"text": "哺育", "is_correct": false, "explanation": "语义：哺育指喂养婴幼儿，不说哺育大学生，与句中的“上大学”不合。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：拍卖是把物品公开卖给出价最高的人，对象是物品，不能说“拍卖这个女孩上大学”，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑人，与出钱帮人读书的意思相反。"}], "explanations": {"资助": "正确。资助指出钱帮人读书，与“王先生出钱让女孩上大学”相符。", "哺育": "语义：哺育指喂养婴幼儿，不说哺育大学生，与句中的“上大学”不合。", "拍卖": "语义：拍卖是把物品公开卖给出价最高的人，对象是物品，不能说“拍卖这个女孩上大学”，句意不通。", "嘲笑": "语义：嘲笑是取笑人，与出钱帮人读书的意思相反。"}, "sentence_index": 0, "correct_answer": "资助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他资助我一个拥抱，让我很感动。", "explanation": "这里的“资助”被用成了“给予”的意思（如“给我一个拥抱”）。资助只指把钱给需要的人，或帮人读书做事，不能用于拥抱这类感情表达。"}, {"text": "医生资助了他一只肾。", "explanation": "资助的对象是钱物，不能用来指捐献器官；器官应说“捐献”。"}, {"text": "她每天资助弟弟一个小时。", "explanation": "资助的对象是钱，不能按时间计算；陪弟弟一个小时应说“陪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确。资助指出钱帮人读书，与“叔叔出钱让我能念书”相符。"}, {"text": "阻拦", "is_correct": false, "explanation": "语义：阻拦是阻止，要不是叔叔阻拦，我就不能念书，句意矛盾。"}, {"text": "拖欠", "is_correct": false, "explanation": "配价：拖欠需要带钱款作宾语，单说“叔叔拖欠”不完整，句意不通。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是解雇，要不是叔叔辞退，我就不能念书，句意矛盾。"}], "explanations": {"资助": "正确。资助指出钱帮人读书，与“叔叔出钱让我能念书”相符。", "阻拦": "语义：阻拦是阻止，要不是叔叔阻拦，我就不能念书，句意矛盾。", "拖欠": "配价：拖欠需要带钱款作宾语，单说“叔叔拖欠”不完整，句意不通。", "辞退": "语义：辞退是解雇，要不是叔叔辞退，我就不能念书，句意矛盾。"}, "sentence_index": 6, "correct_answer": "资助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想资助一个落水的孩子。", "explanation": "这里应该用〈救助〉。资助是把钱给需要的人或帮人读书做事，不能用于把落水的人救上来。"}, {"text": "我想资助一个山区孩子的咳嗽。", "explanation": "这里的“资助”被用成了“治疗、缓解”的意思。资助只指把钱给需要的人，或帮人读书做事，不能用于咳嗽这类病症。"}, {"text": "我想资助他三个小时。", "explanation": "资助的对象是钱物，不能按时间计算；陪他三个小时应说“陪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲明年资助了侄子上学。", "corrected_sentence": "父亲明年资助侄子上学。", "error_description": "错误在“资助”后加了“了”。“明年”指将来，尚未发生，不能用“了”表示完成，应说“明年资助侄子上学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他资助者了弟弟读书。", "corrected_sentence": "他资助了弟弟读书。", "error_description": "错误在“资助”后多了“者”。“资助者”是名词，指出钱帮人的人，不能作谓语。应去掉“者”，说“他资助了弟弟读书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
