INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用财物帮助他人。", "primary_collocate": null, "pronunciation": "zī zhù", "ipa": "tsɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "公司资助了几位贫困学生。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都资助山区的小学。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂资助过一个孤儿院。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人用粮食和衣服资助这户人家。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一部分收入拿来资助别人。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校友们资助学校买了新桌椅。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多亏邻居资助，我们才度过了难关。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸想资助那位生病的老人。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板长期资助附近的小医院。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位好心的老人资助了那个失学的孩子。", "target_word": "资助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "资助了", "label": "体标"}, {"form": "资助过", "label": "体标"}, {"form": "资助者", "label": "复合"}], "register": "正式", "sense_fingerprint": "用财物帮助别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确答案。资助指用财物帮助他人。"}, {"text": "支柱", "is_correct": false, "explanation": "zhī（第一声）与 zī（第一声）声母不同（zh 与 z），意思是支撑物体的柱子。"}, {"text": "自主", "is_correct": false, "explanation": "zì zhǔ 与 zī zhù 两个音节的声调都不同，意思是自己做主。"}, {"text": "资质", "is_correct": false, "explanation": "zhì（第四声）与 zhù（第四声）韵母不同（i 与 u），意思是资格或素质。"}, {"text": "自住", "is_correct": false, "explanation": "zì（第四声）与 zī（第一声）声调不同，意思是自己居住。"}], "explanations": {"资助": "正确答案。资助指用财物帮助他人。", "支柱": "zhī（第一声）与 zī（第一声）声母不同（zh 与 z），意思是支撑物体的柱子。", "自主": "zì zhǔ 与 zī zhù 两个音节的声调都不同，意思是自己做主。", "资质": "zhì（第四声）与 zhù（第四声）韵母不同（i 与 u），意思是资格或素质。", "自住": "zì（第四声）与 zī（第一声）声调不同，意思是自己居住。"}, "sentence_index": null, "correct_answer": "资助"}, "level_3": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确。资助指出钱帮助别人，与“公司帮助贫困学生”相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，公司不会咬学生，句意荒谬。"}, {"text": "批发", "is_correct": false, "explanation": "搭配：批发的对象是货物，不能说批发学生。"}, {"text": "收购", "is_correct": false, "explanation": "搭配：收购的对象是企业或资产，不能用来收购人。"}], "explanations": {"资助": "正确。资助指出钱帮助别人，与“公司帮助贫困学生”相符。", "咬": "语义：咬是用牙齿夹住，公司不会咬学生，句意荒谬。", "批发": "搭配：批发的对象是货物，不能说批发学生。", "收购": "搭配：收购的对象是企业或资产，不能用来收购人。"}, "sentence_index": 0, "correct_answer": "资助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈资助我的决定，希望我能去留学。", "explanation": "这里应该用〈支持〉。资助指用财物帮助他人，不能用来表示赞成别人的决定。"}, {"text": "同事资助我整理了这些文件。", "explanation": "这里应该用〈帮助〉。资助只指提供钱物，不能用于动手帮忙做事。"}, {"text": "我资助你的说法。", "explanation": "这里应该用〈赞同〉。资助指用财物帮助他人，不能用来表示同意某种说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资助", "is_correct": true, "explanation": "正确。资助指用钱物帮助人，与“邻居帮了我们，我们才渡过难关”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝表示不接受或不帮忙，与“多亏”所表示的感激语气相反。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：拖累是连累、拖后腿，与“多亏”的感激语气相反，句意矛盾。"}, {"text": "拖欠", "is_correct": false, "explanation": "配价：拖欠需要带钱款作宾语，单说“邻居拖欠”不完整，句意不通。"}], "explanations": {"资助": "正确。资助指用钱物帮助人，与“邻居帮了我们，我们才渡过难关”相符。", "拒绝": "语义：拒绝表示不接受或不帮忙，与“多亏”所表示的感激语气相反。", "拖累": "语义：拖累是连累、拖后腿，与“多亏”的感激语气相反，句意矛盾。", "拖欠": "配价：拖欠需要带钱款作宾语，单说“邻居拖欠”不完整，句意不通。"}, "sentence_index": 6, "correct_answer": "资助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我资助了她一个微笑，让她安心了不少。", "explanation": "这里的“资助”被用成了“给予”的意思。资助只指用钱物帮助他人，不能用于微笑这类无形的东西。"}, {"text": "医生资助了他一颗心脏。", "explanation": "资助的对象是钱物，不能用来指捐献器官；器官应说“捐献”或“移植”。"}, {"text": "我资助了他三个小时。", "explanation": "资助的对象是钱物，不能用来计算时间；陪他三个小时应说“陪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家资助了这所山区小学吧。", "corrected_sentence": "请大家资助这所山区小学吧。", "error_description": "错误在“资助”后多加了“了”。“请……吧”是祈使句，表示尚未发生的请求，不能用“了”表示完成，应说“请大家资助这所山区小学吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他决定资助起山区的孩子。", "corrected_sentence": "他决定资助山区的孩子。", "error_description": "错误在“资助”后多加了“起”。“起”不能接在“资助”之后，“资助”后直接接受助对象，应说“他决定资助山区的孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
