INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做为是把一个东西当成另一个东西来用。", "primary_collocate": null, "pronunciation": "zuò wéi", "ipa": "tswo˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我把这个旧箱子做为桌子。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把外衣做为枕头。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把客厅做为教室。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧瓶子做为花盆。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这本书做为礼物送给朋友。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把椅子做为游戏里的小船。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把空盒子做为笔筒。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个房间做为书房。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这张照片做为例子。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把学校的大楼做为临时医院。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把甲物当成乙物来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烧成", "is_correct": false, "explanation": "语义：“烧成”指经火烧变成另一种状态，旧箱子不能被烧成可用的桌子。"}, {"text": "做为", "is_correct": true, "explanation": "“做为”表示把旧箱子当作桌子来用，与句中“把……做为……”的结构相符。"}, {"text": "摔成", "is_correct": false, "explanation": "搭配：“摔成”后接碎片、两半之类的破碎结果，不能接“桌子”这类器具。"}, {"text": "煮成", "is_correct": false, "explanation": "语义：“煮成”用于食物或液体的加热，箱子不能被煮成桌子。"}], "explanations": {"烧成": "语义：“烧成”指经火烧变成另一种状态，旧箱子不能被烧成可用的桌子。", "做为": "“做为”表示把旧箱子当作桌子来用，与句中“把……做为……”的结构相符。", "摔成": "搭配：“摔成”后接碎片、两半之类的破碎结果，不能接“桌子”这类器具。", "煮成": "语义：“煮成”用于食物或液体的加热，箱子不能被煮成桌子。"}, "sentence_index": 0, "correct_answer": "做为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把面粉做为面包。", "explanation": "这里应该用〈做成〉。做为表示把某物当作另一物来用，不表示把原料加工成成品；面粉做成面包要用“做成”。"}, {"text": "我把这段话做为英文。", "explanation": "这里应该用〈翻译成〉。做为不表示语言之间的转换，把中文翻译成英文要用“翻译成”。"}, {"text": "他把水做为了冰。", "explanation": "这里应该用〈变成〉。做为表示把某物当作另一物来用，不表示物质发生变化；水变成冰要用“变成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熔成", "is_correct": false, "explanation": "语义：“熔成”需要可熔化的材料，空盒子不能熔成笔筒。"}, {"text": "做为", "is_correct": true, "explanation": "“做为”表示把空盒子当作笔筒来用，符合句意。"}, {"text": "砸成", "is_correct": false, "explanation": "语义：“砸成”指打碎成碎块，不能砸成笔筒这样的器物。"}, {"text": "堆成", "is_correct": false, "explanation": "语义：“堆成”指把东西一层层堆起来形成某物，一个空盒子无法堆成笔筒，句意不通。"}], "explanations": {"熔成": "语义：“熔成”需要可熔化的材料，空盒子不能熔成笔筒。", "做为": "“做为”表示把空盒子当作笔筒来用，符合句意。", "砸成": "语义：“砸成”指打碎成碎块，不能砸成笔筒这样的器物。", "堆成": "语义：“堆成”指把东西一层层堆起来形成某物，一个空盒子无法堆成笔筒，句意不通。"}, "sentence_index": 6, "correct_answer": "做为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把纸做为灰。", "explanation": "这里应该用〈烧成〉。做为表示把某物当作另一物来用，不表示用火烧使物质变成别的东西；纸烧成灰要用“烧成”。"}, {"text": "他把瓶子做为碎片。", "explanation": "这里应该用〈砸成〉。做为不表示打碎或破坏；把瓶子打碎成碎片要用“砸成”。"}, {"text": "他把铁做为铁水。", "explanation": "这里应该用〈熔成〉。做为不表示加热熔化；把铁熔化成铁水要用“熔成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这张报纸做为成包装纸。", "corrected_sentence": "我把这张报纸做为包装纸。", "error_description": "错误：“做为”后多加了“成”。正确：“做为”后直接接宾语，应说“我把这张报纸做为包装纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧木板做为成书架。", "corrected_sentence": "他把旧木板做为书架。", "error_description": "错误：“做为”后多加了“成”。正确：“做为”后直接接宾语，应说“他把旧木板做为书架”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
