INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89406, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "当作;以某种身份或资格。", "primary_collocate": null, "pronunciation": "zuò wéi", "ipa": "tswo˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "做为学生，我每天都要认真学习。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做为老师，他对每个孩子都很耐心。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做为妈妈，她最关心孩子的健康。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做为我们的代表去开会。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做为班长，小李要帮助同学。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做为客人参加了朋友的婚礼。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做为朋友，我一定会帮你。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做为一名医生，他每天工作很忙。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们做为公司的新人，要多向同事学习。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做为中国人，很了解中国的文化。", "target_word": "做为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以某种身份或资格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，学生不能被代替，句意不通。"}, {"text": "做为", "is_correct": true, "explanation": "“做为”表示以学生的身份，与后面的“我每天都要认真学习”相符。"}, {"text": "在", "is_correct": false, "explanation": "配价：“在”需要处所或范围作宾语，“学生”不能作处所，不能说“在学生”。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示依据，“按学生”不能说明我的身份，句意不通。"}], "explanations": {"替": "语义：“替”表示代替，学生不能被代替，句意不通。", "做为": "“做为”表示以学生的身份，与后面的“我每天都要认真学习”相符。", "在": "配价：“在”需要处所或范围作宾语，“学生”不能作处所，不能说“在学生”。", "按": "语义：“按”表示依据，“按学生”不能说明我的身份，句意不通。"}, "sentence_index": 0, "correct_answer": "做为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做为公司的名义去开会。", "explanation": "这里应该用〈以……名义〉。做为表示身份或资格，不能表示以某人或单位的名义行事。"}, {"text": "他做为我们去开会。", "explanation": "这里应该用〈代替〉。做为表示以某种身份或资格，不表示替别人做事；替我们去开会要用“代替”。"}, {"text": "他做为公司的证件进了会场。", "explanation": "这里应该用〈凭〉。做为表示以身份或资格，不能表示凭借证件进入某处；凭证件进场要用“凭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，“从朋友”不能表示我以朋友的身份帮忙，句意不通。"}, {"text": "做为", "is_correct": true, "explanation": "“做为”表示以朋友的身份，与“我一定会帮你”的语气相符。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”表示手持或取用，朋友不能被拿来表示身份，句意不通。"}, {"text": "用", "is_correct": false, "explanation": "语义：“用朋友”不能表示以朋友的身份帮忙，句意不通。"}], "explanations": {"从": "语义：“从”表示起点，“从朋友”不能表示我以朋友的身份帮忙，句意不通。", "做为": "“做为”表示以朋友的身份，与“我一定会帮你”的语气相符。", "拿": "语义：“拿”表示手持或取用，朋友不能被拿来表示身份，句意不通。", "用": "语义：“用朋友”不能表示以朋友的身份帮忙，句意不通。"}, "sentence_index": 6, "correct_answer": "做为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做为字典读懂了文章。", "explanation": "这里应该用〈借助〉。做为表示身份或资格，不能表示借用工具；借助字典读懂文章要用“借助”。"}, {"text": "我做为你的帮助完成了工作。", "explanation": "这里应该用〈依靠〉。做为不能表示依靠某人的帮助；依靠你的帮助完成工作要用“依靠”。"}, {"text": "他做为笔写字。", "explanation": "这里应该用〈用〉。做为表示以身份或资格，不表示使用某物来做事；用笔写字要用“用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做为成一名老师，她最关心学生的成长。", "corrected_sentence": "做为一名老师，她最关心学生的成长。", "error_description": "错误：“做为”后多加了“成”。“做为”后直接接身份名词，应说“做为一名老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做为的老师，我一定会鼓励你。", "corrected_sentence": "做为老师，我一定会鼓励你。", "error_description": "错误：“的”不能插在“做为”和身份名词之间。正确：应说“做为老师”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
