INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89407, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "动作要很快，不要慢慢来。", "primary_collocate": null, "pronunciation": "gǎn kuài", "ipa": "kan˨˩ kʰuaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "快迟到了，你赶快起床！", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨了，赶快收衣服。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，大家赶快来吃吧。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你赶快给妈妈打个电话。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子病了，赶快送他去医院。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们赶快回家吧。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车要开了，你赶快上来。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你赶快把作业写完，再去玩。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见着火了，赶快跑了出去。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜凉了，赶快吃吧。", "target_word": "赶快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趕快", "label": "繁体"}], "register": "中性", "sense_fingerprint": "催促马上行动，不要拖，多用于命令或建议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4935a66f-b0a5-4cd5-b0f8-380dba48c616') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶快", "is_correct": true, "explanation": "正确答案：“快迟到了，你赶快起床”表示催促马上行动，与语境吻合。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“快迟到了”时说“慢慢起床”与紧迫语境相反。"}, {"text": "先别", "is_correct": false, "explanation": "语义：“快迟到了”时说“先别起床”，与催促的语境相反。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“快迟到了”时说“不必起床”，与语境矛盾。"}], "explanations": {"赶快": "正确答案：“快迟到了，你赶快起床”表示催促马上行动，与语境吻合。", "慢慢": "语义：“快迟到了”时说“慢慢起床”与紧迫语境相反。", "先别": "语义：“快迟到了”时说“先别起床”，与催促的语境相反。", "不必": "语义：“快迟到了”时说“不必起床”，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "赶快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸赶快红了。", "explanation": "这里应该用〈立刻〉。赶快要求有人抓紧行动，脸红是不由自主的变化，不能说“赶快红”。"}, {"text": "天气赶快热起来了。", "explanation": "这里应该用〈渐渐〉。赶快表示抓紧行动，天气逐步变化要说渐渐。"}, {"text": "雨赶快停了。", "explanation": "这里应该用〈一下子〉。赶快强调加快行动，雨自己停下要说一下子或突然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶快", "is_correct": true, "explanation": "正确答案：“车要开了，你赶快上来”表示催促马上行动，与语境吻合。"}, {"text": "缓缓", "is_correct": false, "explanation": "语义：“车要开了”时说“缓缓上来”，与催促的语境相反。"}, {"text": "悠然", "is_correct": false, "explanation": "语域：“悠然”偏书面，与这种口语催促的语境不符。"}, {"text": "从容", "is_correct": false, "explanation": "语义：从容不迫与“车要开了”的紧迫相冲突。"}], "explanations": {"赶快": "正确答案：“车要开了，你赶快上来”表示催促马上行动，与语境吻合。", "缓缓": "语义：“车要开了”时说“缓缓上来”，与催促的语境相反。", "悠然": "语域：“悠然”偏书面，与这种口语催促的语境不符。", "从容": "语义：从容不迫与“车要开了”的紧迫相冲突。"}, "sentence_index": 6, "correct_answer": "赶快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的头发赶快白了。", "explanation": "这里应该用〈慢慢〉。赶快强调抓紧行动，头发变白是逐渐变化，要说慢慢。"}, {"text": "我赶快住在这里。", "explanation": "这里应该用〈一直〉。赶快表示抓紧行动，长期居住不能说赶快。"}, {"text": "他赶快喜欢上了这个小村子，每天都舍不得走。", "explanation": "这里应该用〈慢慢〉。赶快表示抓紧行动，对一个地方产生感情是逐渐的，要说慢慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天要下雨了，你赶快了把衣服收进来。", "corrected_sentence": "天要下雨了，你赶快把衣服收进来。", "error_description": "助词错误：“赶快”是副词，后面不能直接加“了”，应说“你赶快把衣服收进来”，不能说“赶快了把衣服收进来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭快凉了，你很赶快把汤喝了。", "corrected_sentence": "饭快凉了，你赶快把汤喝了。", "error_description": "程度副词错误：“赶快”是副词，不能受程度副词“很”修饰，应说“你赶快把汤喝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
