INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指未曾有过性行为的女子。", "primary_collocate": null, "pronunciation": "chǔ nǚ", "ipa": "ʈʂʰu˨˩ ny˨˩", "syllable_count": 2, "sentences": [{"text": "医生说，这种检查不能判断一个女子是否为处女。", "target_word": "处女", "complexity_tier": "T3", "furigana": "yī shēng shuō, zhè zhǒng jiǎn chá bù néng pàn duàn yí gè nǚ zǐ shì fǒu wéi chǔ nǚ.", "sentence_source": "generated"}, {"text": "古代的父母很看重女儿是否为处女。", "target_word": "处女", "complexity_tier": "T3", "furigana": "gǔ dài de fù mǔ hěn kàn zhòng nǚ ér shì fǒu wéi chǔ nǚ.", "sentence_source": "generated"}, {"text": "他在小说里描写了一位仍是处女的少女。", "target_word": "处女", "complexity_tier": "T3", "furigana": "tā zài xiǎo shuō lǐ miáo xiě le yí wèi réng shì chǔ nǚ de shào nǚ.", "sentence_source": "generated"}, {"text": "社会对女性是否为处女的评价往往带有偏见。", "target_word": "处女", "complexity_tier": "T3", "furigana": "shè huì duì nǚ xìng shì fǒu wéi chǔ nǚ de píng jià wǎng wǎng dài yǒu piān jiàn.", "sentence_source": "generated"}, {"text": "他很在意女友是不是处女，这让人很不舒服。", "target_word": "处女", "complexity_tier": "T3", "furigana": "tā hěn zài yì nǚ yǒu shì bu shì chǔ nǚ, zhè ràng rén hěn bù shū fu.", "sentence_source": "generated"}, {"text": "她坚持到结婚那天才发生关系，婚前一直保持着处女之身。", "target_word": "处女", "complexity_tier": "T3", "furigana": "tā jiān chí dào jié hūn nà tiān cái fā shēng guān xì, hūn qián yì zhí bǎo chí zhe chǔ nǚ zhī shēn.", "sentence_source": "generated"}, {"text": "这部小说讲述了一个被迫失去处女身份的女子。", "target_word": "处女", "complexity_tier": "T3", "furigana": "zhè bù xiǎo shuō jiǎng shù le yí gè bèi pò shī qù chǔ nǚ shēn fèn de nǚ zǐ.", "sentence_source": "generated"}, {"text": "在古代，处女的价值常常与贞操直接挂钩。", "target_word": "处女", "complexity_tier": "T3", "furigana": "zài gǔ dài, chǔ nǚ de jià zhí cháng cháng yǔ zhēn cāo zhí jiē guà gōu.", "sentence_source": "generated"}, {"text": "有人认为，婚前失去处女之身是一件很丢人的事。", "target_word": "处女", "complexity_tier": "T3", "furigana": "yǒu rén rèn wéi, hūn qián shī qù chǔ nǚ shì yí jiàn hěn diū rén de shì.", "sentence_source": "generated"}, {"text": "这种观念认为女子在婚前必须是处女。", "target_word": "处女", "complexity_tier": "T3", "furigana": "zhè zhǒng guān niàn rèn wéi nǚ zǐ zài hūn qián bì xū shì chǔ nǚ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "處女", "label": "繁体"}], "register": "书面", "sense_fingerprint": "未曾有过性行为的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处女", "is_correct": true, "explanation": "处女指未曾有过性行为的女子，符合“判断一个女子是否为……”的所指。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：女子不可能是桌子，“判断一个女子是否为……”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：女子不可能是石头，这种判断说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“是否为”后应接人的类别，女子不可能是汽车。"}], "explanations": {"处女": "处女指未曾有过性行为的女子，符合“判断一个女子是否为……”的所指。", "桌子": "语义：女子不可能是桌子，“判断一个女子是否为……”说不通。", "石头": "语义：女子不可能是石头，这种判断说不通。", "汽车": "语义：“是否为”后应接人的类别，女子不可能是汽车。"}, "sentence_index": 0, "correct_answer": "处女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我们班的处女，每次考试都考第一名。", "explanation": "这里应该用〈学霸〉。处女指未曾有过性行为的女子，与考试成绩无关。"}, {"text": "她是一位处女，在医院给病人打针。", "explanation": "这里应该用〈护士〉。处女不是职业，在医院给病人打针的是护士。"}, {"text": "他是一个处女，今年二十八岁，还没谈过恋爱。", "explanation": "这里应该用〈处男〉。处女专指女性，指男性的童贞要说“处男”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处女", "is_correct": true, "explanation": "处女指未曾有过性行为的女子，符合“被迫失去……身份的女子”的语境。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不是可以失去的身份，与“被迫失去……身份的女子”相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有身份，无法与“失去身份”搭配，句意不通。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“身份”指人的社会角色，不能与“机器”搭配。"}], "explanations": {"处女": "处女指未曾有过性行为的女子，符合“被迫失去……身份的女子”的语境。", "书本": "语义：书本不是可以失去的身份，与“被迫失去……身份的女子”相矛盾。", "桌子": "语义：桌子没有身份，无法与“失去身份”搭配，句意不通。", "机器": "搭配：“身份”指人的社会角色，不能与“机器”搭配。"}, "sentence_index": 6, "correct_answer": "处女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她嫁人十年，孩子都上学了，还是处女。", "explanation": "这里应该用〈妻子〉。已婚多年、有了孩子的女子不能称“处女”，应称“妻子”。"}, {"text": "这位处女在饭馆里给客人端菜。", "explanation": "这里应该用〈服务员〉。处女不是职业，给客人端菜的是服务员。"}, {"text": "她在学校教书，每天都很忙，是一位出色的处女。", "explanation": "这里应该用〈老师〉。“处女”指未曾有过性行为的女子，不用来形容职业身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说里的女主角是一只处女。", "corrected_sentence": "这部小说里的女主角是一位处女。", "error_description": "量词错误：“处女”指人，应用“位”（或“个”）来数，不能用“只”。“只”多用于动物，正确说法是“一位处女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书中写的是一位保持着处女身份地女子。", "corrected_sentence": "书中写的是一位保持着处女身份的女子。", "error_description": "结构助词错误：修饰名词“女子”的短语应用“的”连接，不能用“地”（“地”用于修饰动词）。正确说法是“保持着处女身份的女子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
