INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89411, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优秀是特别好,比大多数人都好。", "primary_collocate": null, "pronunciation": "yōu xiù", "ipa": "joʊ˥ ɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她是我们班最优秀的学生。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩很优秀，老师常夸他。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员非常优秀。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成为优秀的医生，要学很多年。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比同事更优秀，所以升职了。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李工作认真，是个优秀的员工。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子又聪明又优秀，大家都喜欢。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就很优秀，每年都拿第一。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找一位优秀的设计师。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很优秀，可是一点儿也不骄傲。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更优秀", "label": "比较"}, {"form": "最优秀", "label": "最高级"}, {"form": "優秀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "特别好，比大多数人都好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "搭配：“透明”多用于玻璃、水等物体，不用来形容学生。"}, {"text": "优秀", "is_correct": true, "explanation": "优秀：特别好，比大多数人都好，符合“最…的学生”的语境。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”形容价格高，学生不能用价格来形容，句意不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气、土地等，不用来修饰人。"}], "explanations": {"透明": "搭配：“透明”多用于玻璃、水等物体，不用来形容学生。", "优秀": "优秀：特别好，比大多数人都好，符合“最…的学生”的语境。", "昂贵": "语义：“昂贵”形容价格高，学生不能用价格来形容，句意不通。", "潮湿": "搭配：“潮湿”形容空气、土地等，不用来修饰人。"}, "sentence_index": 0, "correct_answer": "优秀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的价格很优秀，大家都爱来买。", "explanation": "这里应该用〈优惠〉。“优秀”形容人或事物的突出水平，不用来形容价格，形容价格便宜要用〈优惠〉。"}, {"text": "这家公司给员工的待遇很优秀。", "explanation": "这里应该用〈优厚〉。“优秀”形容人或工作的突出，形容待遇、条件要用〈优厚〉。"}, {"text": "这个孩子的身高很优秀。", "explanation": "这里的“优秀”不能用来评价身高这类身体特征。“优秀”评价的是人的能力、品行或成绩，不用于描述身体的外形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”指分量大或心情压抑，与“聪明”并列，不能形容孩子的优点，句意不通。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多用于空气、土地、皮肤，不用来形容人的品性。"}, {"text": "优秀", "is_correct": true, "explanation": "优秀：特别好，比大多数人都好，与“聪明”并列，描述孩子的品质，句意通顺。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡、悬崖等地形，不用于形容人。"}], "explanations": {"沉重": "语义：“沉重”指分量大或心情压抑，与“聪明”并列，不能形容孩子的优点，句意不通。", "干燥": "搭配：“干燥”多用于空气、土地、皮肤，不用来形容人的品性。", "优秀": "优秀：特别好，比大多数人都好，与“聪明”并列，描述孩子的品质，句意通顺。", "陡峭": "搭配：“陡峭”形容山坡、悬崖等地形，不用于形容人。"}, "sentence_index": 6, "correct_answer": "优秀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很优秀。", "explanation": "这里应该用〈好吃〉。“优秀”不用于评价食物的味道，形容菜好吃要用〈好吃〉。"}, {"text": "这里的生活条件很优秀。", "explanation": "这里应该用〈优越〉。“优秀”形容人或表现突出，形容生活条件好要用〈优越〉。"}, {"text": "这块布的颜色很优秀。", "explanation": "这里应该用〈鲜艳〉。“优秀”不用于描述颜色，形容颜色好看要用〈鲜艳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是公司里最优秀地程序员。", "corrected_sentence": "他是公司里最优秀的程序员。", "error_description": "错误：“优秀地程序员”。正确：“优秀的程序员”。“地”用来修饰动词，修饰名词“程序员”要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的口语非常很优秀，老师很满意。", "corrected_sentence": "她的口语非常优秀，老师很满意。", "error_description": "错误：“非常很”重复使用程度副词。正确：“非常优秀”。“非常”和“很”都表示程度，不能同时修饰“优秀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
