INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89412, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "品行、学问、成绩等非常好。", "primary_collocate": null, "pronunciation": "yōu xiù", "ipa": "joʊ˥ ɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他以优秀的成绩考上了大学。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这篇文章选为优秀作文。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的品质很优秀，朋友都信任他。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿到了优秀毕业生的证书。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，全班有十个人成绩优秀。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名优秀的中学教师。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的品行优秀，被评为三好学生。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她各门功课都很优秀。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给成绩优秀的同学发了奖状。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "优秀的品行比高分更重要。", "target_word": "优秀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更优秀", "label": "比较"}, {"form": "最优秀", "label": "最高级"}, {"form": "優秀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "品行、学问、成绩等非常好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地或触感，不用来形容成绩，句意不通。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色、衣服等，不能修饰成绩。"}, {"text": "优秀", "is_correct": true, "explanation": "优秀：品行、学问、成绩等非常好，与“成绩”相符，句意通顺。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”形容物体表面，不能用来形容成绩。"}], "explanations": {"柔软": "语义：“柔软”形容质地或触感，不用来形容成绩，句意不通。", "鲜艳": "搭配：“鲜艳”形容颜色、衣服等，不能修饰成绩。", "优秀": "优秀：品行、学问、成绩等非常好，与“成绩”相符，句意通顺。", "光滑": "搭配：“光滑”形容物体表面，不能用来形容成绩。"}, "sentence_index": 0, "correct_answer": "优秀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很优秀，我们去公园吧。", "explanation": "这里应该用〈好〉。“优秀”形容人品、学问或成绩的突出，不用来形容天气。"}, {"text": "两国之间的关系很优秀。", "explanation": "这里应该用〈良好〉。“优秀”指特别突出、超过大多数人，关系只是较好，要用〈良好〉。"}, {"text": "这个房间很优秀，地面没有一点灰。", "explanation": "这里应该用〈干净〉。“优秀”不用于形容房间的整洁，形容整洁要用〈干净〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不用来形容品行。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容食物味道或言辞尖锐，不用来形容品行。"}, {"text": "优秀", "is_correct": true, "explanation": "优秀：品行非常好，与“被评为三好学生”的语境相符。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，与品行无关，句意不通。"}], "explanations": {"响亮": "语义：“响亮”形容声音，不用来形容品行。", "辛辣": "搭配：“辛辣”形容食物味道或言辞尖锐，不用来形容品行。", "优秀": "优秀：品行非常好，与“被评为三好学生”的语境相符。", "香甜": "语义：“香甜”形容味道，与品行无关，句意不通。"}, "sentence_index": 6, "correct_answer": "优秀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里的桌椅摆得很优秀。", "explanation": "这里应该用〈整齐〉。“优秀”不用于形容摆放是否规整，形容桌椅摆放要用〈整齐〉。"}, {"text": "他的病情很优秀。", "explanation": "这里应该用〈稳定〉，或说“病情好转”。“优秀”形容品行、学问、成绩的突出，不用于描述病情。"}, {"text": "这件衣服很优秀。", "explanation": "这里应该用〈漂亮〉。“优秀”不用于形容衣服的样式或外观，形容衣服好看要用〈漂亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在数学竞赛中取得了优秀地成绩。", "corrected_sentence": "她在数学竞赛中取得了优秀的成绩。", "error_description": "错误：“优秀地成绩”。正确：“优秀的成绩”。“地”用来修饰动词，修饰名词“成绩”要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的学问非常很优秀，大家都请他去讲课。", "corrected_sentence": "他的学问很优秀，大家都请他去讲课。", "error_description": "错误：“非常很”重复使用程度副词。正确：“很优秀”。“非常”和“很”都表示程度，只用一个即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89413, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较差", "is_correct": true, "explanation": "正确：“较差”与“较好”构成反义，指比别的稍差一点。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指明白、不模糊，与比较的程度义无关。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”指使用起来容易，与“较好”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与“吵闹”相对，与“较好”没有反义关系。"}], "correct_answer": "较差", "explanations": {"较差": "正确：“较差”与“较好”构成反义，指比别的稍差一点。", "清楚": "语义：“清楚”指明白、不模糊，与比较的程度义无关。", "方便": "语义：“方便”指使用起来容易，与“较好”没有反义关系。", "安静": "语义：“安静”与“吵闹”相对，与“较好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89413, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较差", "is_correct": true, "explanation": "正确：“较差”与“较好”构成反义，指比别的稍差一点。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”与“贵”相对，与“较好”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污物，与比较的程度义无关。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”指光线充足，与“较好”没有反义关系。"}], "correct_answer": "较差", "explanations": {"较差": "正确：“较差”与“较好”构成反义，指比别的稍差一点。", "便宜": "语义：“便宜”与“贵”相对，与“较好”没有反义关系。", "干净": "语义：“干净”指没有污物，与比较的程度义无关。", "明亮": "语义：“明亮”指光线充足，与“较好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89413, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比别的更好一点。", "primary_collocate": null, "pronunciation": "jiào hǎo", "ipa": "tɕjɑʊ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个办法里，第二个较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三家公司比起来，这家的服务较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些方法里，我觉得早点出发较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京，坐高铁较好，飞机太贵。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这两个城市中，上海的机会较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人里，他的想法较好，大家都同意。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，在家看书较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书，第一本的内容较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三种菜里，鱼的味道较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几所学校里，这所学校的老师较好。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "较好：在几个选择或对象中比其他的更好一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较好", "is_correct": true, "explanation": "正确：“第二个较好”表示在两个办法中，第二个比第一个更好一点。"}, {"text": "较甜", "is_correct": false, "explanation": "搭配：“办法”不能用甜、苦来形容。"}, {"text": "较远", "is_correct": false, "explanation": "语义：“办法”没有远近之分，与句意不符。"}, {"text": "较热", "is_correct": false, "explanation": "搭配：“办法”不能说冷热。"}], "explanations": {"较好": "正确：“第二个较好”表示在两个办法中，第二个比第一个更好一点。", "较甜": "搭配：“办法”不能用甜、苦来形容。", "较远": "语义：“办法”没有远近之分，与句意不符。", "较热": "搭配：“办法”不能说冷热。"}, "sentence_index": 0, "correct_answer": "较好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去北京，坐高铁的速度较好。", "explanation": "这里应该用〈较快〉。“速度”说快慢，不说好坏。"}, {"text": "三家公司里，这家的服务较好，好到让人惊叹。", "explanation": "这里应该用〈很好〉或〈最好〉。“较好”只表示略胜一筹，不能形容令人惊叹的程度。"}, {"text": "去北京，坐高铁的噪音较好。", "explanation": "这里应该用〈较小〉。“噪音”说大小，不说好坏，“较好”不能用于噪音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较好", "is_correct": true, "explanation": "正确：“在家看书较好”表示在下雨时，在家看书比其他选择更好一点。"}, {"text": "较吵", "is_correct": false, "explanation": "语义：“在家看书”需要安静，“较吵”与句意相矛盾。"}, {"text": "较冷", "is_correct": false, "explanation": "搭配：“看书”不说冷热。"}, {"text": "较脏", "is_correct": false, "explanation": "搭配：“看书”不能用“脏”来形容。"}], "explanations": {"较好": "正确：“在家看书较好”表示在下雨时，在家看书比其他选择更好一点。", "较吵": "语义：“在家看书”需要安静，“较吵”与句意相矛盾。", "较冷": "搭配：“看书”不说冷热。", "较脏": "搭配：“看书”不能用“脏”来形容。"}, "sentence_index": 6, "correct_answer": "较好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全国的学校里，这所学校的老师较好，远远超过所有学校。", "explanation": "这里应该用〈远胜〉。“较好”只表示比别的稍好一点，说远远超过要用“远胜”。"}, {"text": "几所学校里，这所学校的老师年龄较好。", "explanation": "搭配：这里应该用〈较大〉或〈较小〉。“年龄”说大小，不说好坏。"}, {"text": "几所学校里，这所学校的老师较好，是全世界最好的老师。", "explanation": "这里应该用〈顶尖〉。“较好”程度较轻，不能形容全世界最好这样的绝对水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
