INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89414, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "某方面的水平或条件比一般水平略好。", "primary_collocate": null, "pronunciation": "jiào hǎo", "ipa": "tɕjɑʊ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店的环境较好，价格也不高。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平较好，可以做翻译。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的天气较好，很少下雨。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体较好，很少生病。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的治安较好，晚上也很安全。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的睡眠质量较好，早上不觉得累。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩较好，老师很满意。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的交通较好，坐地铁十分钟就到。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的收入较好，所以很多人想做。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的经济条件较好，买得起大房子。", "target_word": "较好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "较好：某方面的水平或条件比一般水平略好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较好", "is_correct": true, "explanation": "正确：“环境较好”表示环境比一般水平略好，与“价格也不高”相呼应。"}, {"text": "较浅", "is_correct": false, "explanation": "搭配：“环境”不说深浅。"}, {"text": "较快", "is_correct": false, "explanation": "搭配：“环境”不能说快慢。"}, {"text": "较便宜", "is_correct": false, "explanation": "语义：“便宜”说的是价格，不能用来形容环境。"}], "explanations": {"较好": "正确：“环境较好”表示环境比一般水平略好，与“价格也不高”相呼应。", "较浅": "搭配：“环境”不说深浅。", "较快": "搭配：“环境”不能说快慢。", "较便宜": "语义：“便宜”说的是价格，不能用来形容环境。"}, "sentence_index": 0, "correct_answer": "较好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位选手在决赛中拿了冠军，表现较好。", "explanation": "这里应该用〈优秀〉。“较好”只表示比一般水平略好，程度较轻，不能形容拿冠军这样突出的表现。"}, {"text": "这个班一共五十个学生，人数较好。", "explanation": "这里应该用〈较多〉。“人数”只说多少，不能说好坏，“较好”不能用于数量。"}, {"text": "他的英语说得像母语一样，发音较好。", "explanation": "这里应该用〈非常标准〉。“较好”程度较轻，不能形容像母语一样的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较好", "is_correct": true, "explanation": "正确：“成绩较好”表示成绩比一般水平略好，与“老师很满意”一致。"}, {"text": "较低", "is_correct": false, "explanation": "语义：“成绩较低”与“老师很满意”的句意相矛盾。"}, {"text": "较慢", "is_correct": false, "explanation": "搭配：“成绩”不说快慢。"}, {"text": "较少", "is_correct": false, "explanation": "搭配：“成绩”不说多少，应说分数高低。"}], "explanations": {"较好": "正确：“成绩较好”表示成绩比一般水平略好，与“老师很满意”一致。", "较低": "语义：“成绩较低”与“老师很满意”的句意相矛盾。", "较慢": "搭配：“成绩”不说快慢。", "较少": "搭配：“成绩”不说多少，应说分数高低。"}, "sentence_index": 6, "correct_answer": "较好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的经济条件较好，买得起全世界最贵的房子。", "explanation": "这里应该用〈非常富有〉。“较好”只表示略好于一般水平，不能用于这样的极端情况。"}, {"text": "他的身高较好，打篮球很有优势。", "explanation": "这里应该用〈较高〉。“身高”说高矮，不说好坏，“较好”不能用于身高。"}, {"text": "他家的房子面积较好，有两百平方米。", "explanation": "这里应该用〈较大〉。“面积”说大小，不说好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的英语口语很较好，能跟外国人聊天。", "corrected_sentence": "他的英语口语较好，能跟外国人聊天。", "error_description": "程度错误：“较好”本身已含程度义，不能再与“很”连用，应直接说“较好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的经济条件很较好，买得起一套小房子。", "corrected_sentence": "他的经济条件较好，买得起一套小房子。", "error_description": "程度错误：“较好”不能与“很”连用，应直接说“较好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
