INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89415, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行动艺术是艺术家用自己的动作和表演来做出的艺术。", "primary_collocate": null, "pronunciation": "xíng dòng yì shù", "ipa": "ɕiŋ³⁵ tʊŋ⁵¹ i⁵¹ ʂu⁵¹", "syllable_count": 4, "sentences": [{"text": "他用行动艺术表达自己的想法。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺术家最喜欢做行动艺术。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们在公园看了一场行动艺术表演。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动艺术不用画笔，只用身体。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在街上做行动艺术，很多人停下来看。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是行动艺术。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对行动艺术很感兴趣。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场行动艺术让孩子们笑了。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢行动艺术。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有人在广场上做行动艺术。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "艺术家用动作和表演做出的艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动艺术", "is_correct": true, "explanation": "正确：“行动艺术”是一种表达方式，与“表达自己的想法”搭配。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，无法用来表达想法。"}, {"text": "扳手", "is_correct": false, "explanation": "搭配：“表达想法”通常借助语言、艺术等媒介，扳手不是表达的手段。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能用来表达想法。"}], "explanations": {"行动艺术": "正确：“行动艺术”是一种表达方式，与“表达自己的想法”搭配。", "粮食": "语义：粮食是食物，无法用来表达想法。", "扳手": "搭配：“表达想法”通常借助语言、艺术等媒介，扳手不是表达的手段。", "冰箱": "语义：冰箱是家用电器，不能用来表达想法。"}, "sentence_index": 0, "correct_answer": "行动艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天看了一把行动艺术。", "explanation": "这里应该用〈场〉。“把”用于有柄的器具，行动艺术应按场计算，如“一场行动艺术”。"}, {"text": "我昨天看了一条行动艺术。", "explanation": "这里应该用〈场〉。“条”用于细长的东西，不用于表演类的艺术。"}, {"text": "我昨天看了一只行动艺术。", "explanation": "这里应该用〈场〉。“只”用于动物或成对物品中的一个，不用于行动艺术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动艺术", "is_correct": true, "explanation": "正确：“行动艺术”是一种可以引起兴趣的艺术形式，与“感兴趣”搭配。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是可以引起兴趣的艺术或活动，句子读来不通。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头是建材，与“感兴趣”所指的艺术、活动不相关。"}, {"text": "鞋带", "is_correct": false, "explanation": "搭配：“感兴趣”常接艺术、学科、活动，不接鞋带这类日用小物。"}], "explanations": {"行动艺术": "正确：“行动艺术”是一种可以引起兴趣的艺术形式，与“感兴趣”搭配。", "垃圾": "语义：垃圾不是可以引起兴趣的艺术或活动，句子读来不通。", "砖头": "语义：砖头是建材，与“感兴趣”所指的艺术、活动不相关。", "鞋带": "搭配：“感兴趣”常接艺术、学科、活动，不接鞋带这类日用小物。"}, "sentence_index": 6, "correct_answer": "行动艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件行动艺术由很多旧轮胎组成。", "explanation": "这里应该用〈装置艺术〉。行动艺术以艺术家自身的行为和过程为表现形式，不是由物件组成的作品；由物件组装而成的才是装置艺术。"}, {"text": "她用行动艺术做了一桌好菜。", "explanation": "这里应该用〈烹饪〉。行动艺术指艺术家用动作和表演创作的艺术，不指做饭，这里的用法不对。"}, {"text": "她写了一部关于历史的行动艺术。", "explanation": "这里应该用〈小说〉。行动艺术是艺术家用自己的动作和表演做出的艺术，不能“写”，也不是书籍；写的历史作品应说“小说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我去看了一本行动艺术。", "corrected_sentence": "周末我去看了一场行动艺术。", "error_description": "错误：“一本行动艺术”。正确：“一场行动艺术”。“本”用于书籍，行动艺术是表演，应按“场”计算。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区里有人组织了一场的行动艺术。", "corrected_sentence": "社区里有人组织了一场行动艺术。", "error_description": "错误：“一场的行动艺术”。正确：“一场行动艺术”。数量短语修饰名词时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
