INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "艺术家以自身的行为和过程作为表现形式的艺术门类。", "primary_collocate": null, "pronunciation": "xíng dòng yì shù", "ipa": "ɕiŋ³⁵ tʊŋ⁵¹ i⁵¹ ʂu⁵¹", "syllable_count": 4, "sentences": [{"text": "行动艺术重视过程，不重视结果。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行动艺术的方式，在雪地里走了一整天。", "target_word": "行动艺术", "complexity_tier": "T3", "furigana": "xíng dòng yì shù", "sentence_source": "generated"}, {"text": "这位艺术家的行动艺术作品很有名。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动艺术的材料就是艺术家自己的行为。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三天的时间完成了一次行动艺术。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在行动艺术里，艺术家本人就是作品。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆今天有一场行动艺术展示。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动艺术和画画、雕塑不一样。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人说行动艺术很难看懂。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的行动艺术让大家想起了环境问题。", "target_word": "行动艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "以艺术家自身行为和过程为形式的艺术门类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动艺术", "is_correct": true, "explanation": "正确：“行动艺术”是以行为和过程为形式的艺术，作主语时与“重视过程”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有重视过程的能力，句子读来不通。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯是照明设备，不能重视过程。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“重视”多接人、工作、教育等，不接汽车这类物件。"}], "explanations": {"行动艺术": "正确：“行动艺术”是以行为和过程为形式的艺术，作主语时与“重视过程”相合。", "石头": "语义：石头没有重视过程的能力，句子读来不通。", "路灯": "语义：路灯是照明设备，不能重视过程。", "汽车": "搭配：“重视”多接人、工作、教育等，不接汽车这类物件。"}, "sentence_index": 0, "correct_answer": "行动艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在美术馆看了一本行动艺术。", "explanation": "这里应该用〈场〉。“本”用于书籍，行动艺术应按场计算，如“看了一场行动艺术”。"}, {"text": "他在美术馆看了一盏行动艺术。", "explanation": "这里应该用〈场〉。“盏”用于灯具，不用于行动艺术。"}, {"text": "他在美术馆看了一棵行动艺术。", "explanation": "这里应该用〈场〉。“棵”用于植物，不用于表演类的艺术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动艺术", "is_correct": true, "explanation": "正确：“行动艺术展示”指展示以行为和过程为形式的艺术作品，搭配自然。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以展示的艺术或作品，句子读来不通。"}, {"text": "体检", "is_correct": false, "explanation": "搭配：“展示”接作品、产品等，不接体检这类服务。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体症状，不能用于展示。"}], "explanations": {"行动艺术": "正确：“行动艺术展示”指展示以行为和过程为形式的艺术作品，搭配自然。", "空气": "语义：空气不是可以展示的艺术或作品，句子读来不通。", "体检": "搭配：“展示”接作品、产品等，不接体检这类服务。", "咳嗽": "语义：咳嗽是身体症状，不能用于展示。"}, "sentence_index": 6, "correct_answer": "行动艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅行动艺术挂在客厅的墙上，颜色很鲜艳。", "explanation": "这里应该用〈绘画〉。行动艺术以艺术家自身的行为和过程为表现形式；挂在墙上的平面作品是绘画，不是行动艺术。"}, {"text": "这位裁缝用行动艺术缝了一件衣服。", "explanation": "这里应该用〈缝纫〉。行动艺术指艺术家以自身行为为表现形式的艺术，不指缝制衣物的手艺。"}, {"text": "她在河边用行动艺术钓了一条鱼。", "explanation": "这里应该用〈鱼竿〉。行动艺术是以艺术家自身行为为表现形式的艺术门类，不是钓鱼的工具；钓鱼要用“鱼竿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里今天有一条行动艺术。", "corrected_sentence": "公园里今天有一场行动艺术。", "error_description": "错误：“一条行动艺术”。正确：“一场行动艺术”。“条”用于细长的东西，行动艺术应按“场”计算。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校组织了一场的行动艺术。", "corrected_sentence": "学校组织了一场行动艺术。", "error_description": "错误：“一场的行动艺术”。正确：“一场行动艺术”。数量短语修饰名词时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
