INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89417, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "刚刚是说事情才发生了一小会儿。", "primary_collocate": null, "pronunciation": "gāng gāng", "ipa": "kɑŋ˥ kɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他刚刚给我打了电话。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你刚刚说什么?我没听清。", "target_word": "刚刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子刚刚睡着,请小声一点。", "target_word": "刚刚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚刚到家,还没吃饭。", "target_word": "刚刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨刚刚停,路上都是水。", "target_word": "刚刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈刚刚出门,你去追她吧。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条消息是我刚刚看到的。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚刚下课,现在在吃午饭。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚刚还很热,现在突然下雨了。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚刚把作业交给了老师。", "target_word": "刚刚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚", "label": "单字形式"}], "register": "中性", "sense_fingerprint": "刚刚:指事情才发生不久,相当于刚才", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示事情发生在不久以前，与“打了电话”相合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示习惯性地反复发生，与“打了电话”这一次完成的动作不合。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行中，不能与表示完成的“了”同用。"}, {"text": "将", "is_correct": false, "explanation": "语法：“将”表示尚未发生，不能与表示完成的“了”同用。"}], "explanations": {"刚刚": "正确。“刚刚”表示事情发生在不久以前，与“打了电话”相合。", "总是": "语义：“总是”表示习惯性地反复发生，与“打了电话”这一次完成的动作不合。", "正在": "语法：“正在”表示动作进行中，不能与表示完成的“了”同用。", "将": "语法：“将”表示尚未发生，不能与表示完成的“了”同用。"}, "sentence_index": 0, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚刚每天都去跑步。", "explanation": "“刚刚”只表示事情才发生了一小会儿，是一次性的时间，不能与“每天都”这种表示习惯的时间搭配。"}, {"text": "我刚刚明年结婚。", "explanation": "这里误把“刚刚”当成“将要”的意思来用，与“明年”搭配；“刚刚”只能指刚发生不久的事情。"}, {"text": "她刚刚永远不会忘记你。", "explanation": "“刚刚”表示不久以前，与“永远”这种表示长久将来的词矛盾，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示事情发生在不久以前，与“是……的”强调的近期发生相合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“看到”这一次性的动作不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”通常与否定词连用，与肯定的“看到”不合。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行中，不能与“看到”这一已完成的结果同用。"}], "explanations": {"刚刚": "正确。“刚刚”表示事情发生在不久以前，与“是……的”强调的近期发生相合。", "一直": "语义：“一直”表示持续不断，与“看到”这一次性的动作不合。", "从来": "语义：“从来”通常与否定词连用，与肯定的“看到”不合。", "正在": "语法：“正在”表示动作进行中，不能与“看到”这一已完成的结果同用。"}, "sentence_index": 6, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚刚很聪明，一学就会。", "explanation": "“刚刚”表示事情才发生了一小会儿，不能与“很聪明”这种对人的长期评价搭配；这里误把它当成程度副词。"}, {"text": "我们刚刚认识，但已经认识三十年了。", "explanation": "“刚刚”只表示刚发生不久，与“已经认识三十年”这样的长时段矛盾，不能这样用。"}, {"text": "我们刚刚下个月去旅行。", "explanation": "“刚刚”只表示事情才发生不久，不能和“下个月”这种表示将来的时间搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚刚的起床，还没洗脸。", "corrected_sentence": "他刚刚起床，还没洗脸。", "error_description": "“刚刚”是副词，直接修饰动词“起床”，二者之间不能加“的”。“刚刚的起床”应说“刚刚起床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的刚刚打完电话，现在出去了。", "corrected_sentence": "她刚刚打完电话，现在出去了。", "error_description": "“刚刚”是副词，前面不能加“的”；“她的刚刚打完电话”应说“她刚刚打完电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
