INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示恰好、正好合适或正好够。", "primary_collocate": null, "pronunciation": "gāng gāng", "ipa": "kɑŋ˥ kɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这双鞋刚刚好,不大也不小。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些钱刚刚够买一张机票。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子刚刚放得下一张大床。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的天气刚刚好,不冷也不热。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间不大,放一张床刚刚好。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶水刚刚装满一杯,一点也没剩。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这袋米刚刚一斤,不多也不少。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的钱刚刚够交房租,没有多的了。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些座位刚刚够全班坐下。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子刚刚能放进车里。", "target_word": "刚刚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚", "label": "单字形式"}, {"form": "刚刚好", "label": "复合"}], "register": "中性", "sense_fingerprint": "刚刚:表示恰好,正好合适或正好够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示恰好合适，与“不大也不小”相呼应。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，但句中说的是鞋子现在的大小状况。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示推测，与“不大也不小”这种确定的评价不合。"}, {"text": "行将", "is_correct": false, "explanation": "语域：“行将”是书面语，且表示尚未发生，与口语化的评价句不合。"}], "explanations": {"刚刚": "正确。“刚刚”表示恰好合适，与“不大也不小”相呼应。", "马上": "语义：“马上”表示即将发生，但句中说的是鞋子现在的大小状况。", "大概": "语义：“大概”表示推测，与“不大也不小”这种确定的评价不合。", "行将": "语域：“行将”是书面语，且表示尚未发生，与口语化的评价句不合。"}, "sentence_index": 0, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋刚刚太大了,穿不上。", "explanation": "“刚刚”表示恰好合适，与表示过分的“太”矛盾，两者不能同用。"}, {"text": "这件外套刚刚很合身，你穿吧。", "explanation": "这里误把“刚刚”当成可以受“很”修饰的程度词，与“很合身”的程度义混在一起；这种“刚刚”不能与“很”同用。"}, {"text": "这些菜刚刚很多，我们吃不完。", "explanation": "这里误把“刚刚”当成可以修饰“很多”这类笼统数量的程度词；它不能与“很多”搭配，应说“正好够”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": true, "explanation": "正确。“刚刚”表示恰好是一斤，与“不多也不少”相合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能修饰“一斤”这样的数量。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将或立刻，与“一斤”这种既定数量不合。"}, {"text": "将", "is_correct": false, "explanation": "语域：“将”偏书面，且表示尚未发生，与“一斤”这种既定数量不合。"}], "explanations": {"刚刚": "正确。“刚刚”表示恰好是一斤，与“不多也不少”相合。", "正在": "搭配：“正在”表示动作进行中，不能修饰“一斤”这样的数量。", "马上": "语义：“马上”表示即将或立刻，与“一斤”这种既定数量不合。", "将": "语域：“将”偏书面，且表示尚未发生，与“一斤”这种既定数量不合。"}, "sentence_index": 6, "correct_answer": "刚刚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书刚刚太多，书架都放不下了。", "explanation": "“刚刚”表示恰好，与表示过分的“太”矛盾，不能同用。"}, {"text": "这间屋子刚刚很宽敞，住着很舒服。", "explanation": "这里误把“刚刚”当成可以受“很”修饰的程度词，与“很宽敞”的程度义混在一起；这种“刚刚”不能与“很”同用。"}, {"text": "他刚刚很聪明，一学就会。", "explanation": "这里误把“刚刚”当成程度副词来用；“刚刚”表示恰好，不能受“很”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裤子刚刚很合适,我就买了。", "corrected_sentence": "这条裤子刚刚好，我就买了。", "error_description": "“刚刚”表示恰好，不能受“很”修饰；“刚刚很合适”应去掉“很”，改为“刚刚好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些水刚刚很够大家喝。", "corrected_sentence": "这些水刚刚够大家喝。", "error_description": "“刚刚”表示恰好、正好够，不能再加程度副词“很”；“刚刚很够”应去掉“很”，说“刚刚够”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就职", "is_correct": true, "explanation": "就职：开始担任某项职务，与“辞职”构成反义。"}, {"text": "请假", "is_correct": false, "explanation": "请假：暂时不上班，与辞职的永久离开不构成反义。"}, {"text": "加班", "is_correct": false, "explanation": "加班：在规定时间之外继续工作，与辞职没有反义关系。"}, {"text": "毕业", "is_correct": false, "explanation": "毕业：完成学业离开学校，与辞职不构成反义。"}], "correct_answer": "就职", "explanations": {"就职": "就职：开始担任某项职务，与“辞职”构成反义。", "请假": "请假：暂时不上班，与辞职的永久离开不构成反义。", "加班": "加班：在规定时间之外继续工作，与辞职没有反义关系。", "毕业": "毕业：完成学业离开学校，与辞职不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就职", "is_correct": true, "explanation": "就职：开始担任某项职务，与“辞职”构成反义。"}, {"text": "出差", "is_correct": false, "explanation": "出差：因公到外地工作，与辞职没有反义关系。"}, {"text": "迟到", "is_correct": false, "explanation": "迟到：没有按时到达，与辞职没有反义关系。"}, {"text": "放假", "is_correct": false, "explanation": "放假：暂停工作或学习的一段时间，与辞职不构成反义。"}], "correct_answer": "就职", "explanations": {"就职": "就职：开始担任某项职务，与“辞职”构成反义。", "出差": "出差：因公到外地工作，与辞职没有反义关系。", "迟到": "迟到：没有按时到达，与辞职没有反义关系。", "放假": "放假：暂停工作或学习的一段时间，与辞职不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己说不想再做这份工作了，离开。", "primary_collocate": null, "pronunciation": "cí zhí", "ipa": "tsʰɨ˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "他不喜欢这份工作，所以辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太累了，想辞职回老家。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说工资太低，她要辞职。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天加班到很晚，一气之下辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李不想再做服务员，昨天辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经辞职了，下个月不用上班。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了照顾孩子，决定辞职。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受不了老板，今天早上就辞职走了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么突然辞职？这里不好吗？", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我辞职以后，想去国外旅游。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辞了职", "label": "体标"}, {"form": "辞过职", "label": "体标"}], "register": "中性", "sense_fingerprint": "辞职：因为不想再做这份工作而主动离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：因为不想再做这份工作而主动离开，是本词的意思。"}, {"text": "磁石", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同：sh 与 zh。磁石指磁铁，与辞职不同。"}, {"text": "此致", "is_correct": false, "explanation": "cǐ（第三声）与 cí（第二声）声调不同，zhì（第四声）与 zhí（第二声）声调不同。此致是书信结尾用语。"}, {"text": "瓷质", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是瓷器的质地。"}], "explanations": {"辞职": "辞职：因为不想再做这份工作而主动离开，是本词的意思。", "磁石": "shí（第二声）与 zhí（第二声）声母不同：sh 与 zh。磁石指磁铁，与辞职不同。", "此致": "cǐ（第三声）与 cí（第二声）声调不同，zhì（第四声）与 zhí（第二声）声调不同。此致是书信结尾用语。", "瓷质": "zhì（第四声）与 zhí（第二声）声调不同，意思是瓷器的质地。"}, "sentence_index": null, "correct_answer": "辞职"}, "level_3": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：因为不喜欢工作而主动离开，与前半句相符。"}, {"text": "退学", "is_correct": false, "explanation": "语义：“退学”指学生离开学校，与“这份工作”不符。"}, {"text": "罢课", "is_correct": false, "explanation": "搭配：“罢课”指学生停止上课，不能用于工作。"}, {"text": "转校", "is_correct": false, "explanation": "语义：“转校”指学生更换学校，与“这份工作”不符。"}], "explanations": {"辞职": "辞职：因为不喜欢工作而主动离开，与前半句相符。", "退学": "语义：“退学”指学生离开学校，与“这份工作”不符。", "罢课": "搭配：“罢课”指学生停止上课，不能用于工作。", "转校": "语义：“转校”指学生更换学校，与“这份工作”不符。"}, "sentence_index": 0, "correct_answer": "辞职"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司因为业绩下降，决定辞职。", "explanation": "这里应该用〈裁员〉。辞职是员工自己提出离开，公司不能辞职。"}, {"text": "他因为生病，向经理辞职三天。", "explanation": "这里应该用〈请假〉。辞职是永久离开工作，不能说“辞职三天”。"}, {"text": "这家饭店辞职了，老板很伤心。", "explanation": "这里应该用〈倒闭〉。辞职的主语必须是有职务的人，饭店作为机构停业要说倒闭或关门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：为照顾孩子而离开工作，与前半句相符。"}, {"text": "出家", "is_correct": false, "explanation": "语义：“出家”指离开家庭入寺修行，与“照顾孩子”矛盾。"}, {"text": "入伍", "is_correct": false, "explanation": "语义：“入伍”指加入军队，与“照顾孩子”不符。"}, {"text": "远航", "is_correct": false, "explanation": "搭配：“远航”指远渡海洋，不能与“为了照顾孩子”的决定搭配。"}], "explanations": {"辞职": "辞职：为照顾孩子而离开工作，与前半句相符。", "出家": "语义：“出家”指离开家庭入寺修行，与“照顾孩子”矛盾。", "入伍": "语义：“入伍”指加入军队，与“照顾孩子”不符。", "远航": "搭配：“远航”指远渡海洋，不能与“为了照顾孩子”的决定搭配。"}, "sentence_index": 6, "correct_answer": "辞职"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向路边的石头辞职了，石头没有回答。", "explanation": "这里是“告别”的意思，应该用〈告别〉。辞职只能向雇主或领导提出，石头不是雇主，不能用来向它告别。"}, {"text": "我每个星期都辞职一次。", "explanation": "这里应该用〈早退〉或〈请假〉，表示每星期中途离开或不来上班。辞职指一次性辞去工作，不能每星期重复。"}, {"text": "他对邻居的邀请辞职了，不想去。", "explanation": "这里“辞”是辞谢的意思，不是辞去工作。辞职只指离开职务，不能用于邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我决定下周辞职工作。", "corrected_sentence": "我决定下周辞职。", "error_description": "错误：“辞职”是不及物的动宾式词语，后面不能直接带宾语“工作”。正确写法是“我决定下周辞职。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她决定在领导辞职。", "corrected_sentence": "她决定向领导辞职。", "error_description": "错误：介词“在”不能引出辞职的对象，应使用“向”。正确写法是“她决定向领导辞职。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就职", "is_correct": true, "explanation": "就职：开始担任某项职务，与“辞职”构成反义。"}, {"text": "请假", "is_correct": false, "explanation": "请假：暂时不上班，与辞职的永久离开不构成反义。"}, {"text": "加班", "is_correct": false, "explanation": "加班：在规定时间之外继续工作，与辞职没有反义关系。"}, {"text": "毕业", "is_correct": false, "explanation": "毕业：完成学业离开学校，与辞职不构成反义。"}], "correct_answer": "就职", "explanations": {"就职": "就职：开始担任某项职务，与“辞职”构成反义。", "请假": "请假：暂时不上班，与辞职的永久离开不构成反义。", "加班": "加班：在规定时间之外继续工作，与辞职没有反义关系。", "毕业": "毕业：完成学业离开学校，与辞职不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就职", "is_correct": true, "explanation": "就职：开始担任某项职务，与“辞职”构成反义。"}, {"text": "出差", "is_correct": false, "explanation": "出差：因公到外地工作，与辞职没有反义关系。"}, {"text": "迟到", "is_correct": false, "explanation": "迟到：没有按时到达，与辞职没有反义关系。"}, {"text": "放假", "is_correct": false, "explanation": "放假：暂停工作或学习的一段时间，与辞职不构成反义。"}], "correct_answer": "就职", "explanations": {"就职": "就职：开始担任某项职务，与“辞职”构成反义。", "出差": "出差：因公到外地工作，与辞职没有反义关系。", "迟到": "迟到：没有按时到达，与辞职没有反义关系。", "放假": "放假：暂停工作或学习的一段时间，与辞职不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己提出辞去职务。", "primary_collocate": null, "pronunciation": "cí zhí", "ipa": "tsʰɨ˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "经理今天向公司提出辞职。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长因为身体原因，正式辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理下周要辞职，公司正在找新人。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向老板说明理由后，辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位校长因为工作失误辞职了。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板同意他辞职，还送了他礼物。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任决定下个月辞职，回家照顾父母。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导还没有批准他辞职。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上宣布辞职，大家都很吃惊。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理辞职以后，部门由小王负责。", "target_word": "辞职", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辞了职", "label": "体标"}, {"form": "辞过职", "label": "体标"}], "register": "中性", "sense_fingerprint": "辞职：向公司或领导正式提出辞去职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：自己提出辞去职务，是本词的意思。"}, {"text": "磁石", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同：sh 与 zh。磁石指磁铁，与辞职不同。"}, {"text": "此致", "is_correct": false, "explanation": "cǐ（第三声）与 cí（第二声）声调不同，zhì（第四声）与 zhí（第二声）声调不同。此致是书信结尾用语。"}, {"text": "瓷质", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是瓷器的质地。"}], "explanations": {"辞职": "辞职：自己提出辞去职务，是本词的意思。", "磁石": "shí（第二声）与 zhí（第二声）声母不同：sh 与 zh。磁石指磁铁，与辞职不同。", "此致": "cǐ（第三声）与 cí（第二声）声调不同，zhì（第四声）与 zhí（第二声）声调不同。此致是书信结尾用语。", "瓷质": "zhì（第四声）与 zhí（第二声）声调不同，意思是瓷器的质地。"}, "sentence_index": null, "correct_answer": "辞职"}, "level_3": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：自己提出辞去职务，与“向公司提出”相符。"}, {"text": "退学", "is_correct": false, "explanation": "语义：“退学”指学生离开学校，不能用于经理和公司。"}, {"text": "退役", "is_correct": false, "explanation": "语义：“退役”指军人或运动员离开岗位，与经理和公司不符。"}, {"text": "转学", "is_correct": false, "explanation": "搭配：“转学”只用于学生换学校，不能说向公司转学。"}], "explanations": {"辞职": "辞职：自己提出辞去职务，与“向公司提出”相符。", "退学": "语义：“退学”指学生离开学校，不能用于经理和公司。", "退役": "语义：“退役”指军人或运动员离开岗位，与经理和公司不符。", "转学": "搭配：“转学”只用于学生换学校，不能说向公司转学。"}, "sentence_index": 0, "correct_answer": "辞职"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司因为他经常迟到，决定辞职。", "explanation": "这里应该用〈辞退〉。辞职是职工自己提出离开，主语应是本人；由公司决定让人离开要说辞退。"}, {"text": "他因为生病，向公司辞职三天。", "explanation": "这里应该用〈请假〉。辞职是永久离开工作，不能说“辞职三天”；暂时不上班要说请假。"}, {"text": "他来看望朋友，今天向主人辞职。", "explanation": "这里应该用〈辞行〉。辞行是出发前向主人告别，不是辞去工作；辞职只指离开职务，不能对主人使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辞职", "is_correct": true, "explanation": "辞职：主动离开工作，才能回家照顾父母。"}, {"text": "出家", "is_correct": false, "explanation": "语义：“出家”指离开家庭入寺修行，与“回家照顾父母”矛盾。"}, {"text": "入伍", "is_correct": false, "explanation": "语义：“入伍”指加入军队，与“回家照顾父母”矛盾。"}, {"text": "远航", "is_correct": false, "explanation": "搭配：“远航”指远渡海洋，与“回家照顾父母”的方向相反，不能搭配。"}], "explanations": {"辞职": "辞职：主动离开工作，才能回家照顾父母。", "出家": "语义：“出家”指离开家庭入寺修行，与“回家照顾父母”矛盾。", "入伍": "语义：“入伍”指加入军队，与“回家照顾父母”矛盾。", "远航": "搭配：“远航”指远渡海洋，与“回家照顾父母”的方向相反，不能搭配。"}, "sentence_index": 6, "correct_answer": "辞职"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向路边的大树辞职了，大树没有同意。", "explanation": "这里是“告别”的意思，应该用〈告别〉。辞职只能向雇主或领导提出，大树不是雇主，不能用来向它告别。"}, {"text": "他每天都要辞职一次，很累。", "explanation": "这里应该用〈早退〉或〈请假〉，表示每天中途离开或不来上班。辞职指一次性辞去工作，不能每天重复。"}, {"text": "他对老板的礼物辞职了，不想收下。", "explanation": "这里“辞”是辞谢的意思，不是辞去工作。辞职只指离开职务，不能用于礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经辞职了工作。", "corrected_sentence": "他已经辞职了。", "error_description": "错误：“辞职”是不及物的动宾式词语，后面不能直接带宾语“工作”。正确写法是“他已经辞职了。”（或口语“他已经辞了工作。”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把公司辞职了。", "corrected_sentence": "他向公司辞职了。", "error_description": "错误在“把”。“辞职”是不及物动词，不能用“把”字句，应把“把”换成介词“向”，说“他向公司辞职了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
