INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "北是一个方向,跟南相反。", "primary_collocate": null, "pronunciation": "běi", "ipa": "pei˨˩˦", "syllable_count": 1, "sentences": [{"text": "小鸟冬天往南飞,春天往北飞。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向北看,那座高楼就是医院。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房子门朝北,冬天有点冷。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车一直往北开,天气越来越冷。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看地图时,上面一般是北,下面是南。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车从南到北,用了两天。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红箭头指的是北,蓝箭头指的是南。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你往北走过两个路口,就能看到银行。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口往北拐,第一家就是我家。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着自行车一路向北,去看海。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北边", "label": "复合词"}, {"form": "北方", "label": "复合词"}, {"form": "北面", "label": "复合词"}], "register": "中性", "sense_fingerprint": "北:一个方向,跟南相反,用来指路、看地图、说朝向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "北", "is_correct": true, "explanation": "北是一个方向，跟南相反。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是悲伤。"}, {"text": "倍", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是倍数。"}, {"text": "备", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是准备。"}, {"text": "辈", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是一辈、一代人。"}], "explanations": {"北": "北是一个方向，跟南相反。", "悲": "bēi（第一声）与 běi（第三声）声调不同，意思是悲伤。", "倍": "bèi（第四声）与 běi（第三声）声调不同，意思是倍数。", "备": "bèi（第四声）与 běi（第三声）声调不同，意思是准备。", "辈": "bèi（第四声）与 běi（第三声）声调不同，意思是一辈、一代人。"}, "sentence_index": null, "correct_answer": "北"}, "level_3": {"options": [{"text": "北", "is_correct": true, "explanation": "“北”与前文“往南飞”相对，“春天往北飞”表示朝北方飞，符合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是方向，不能作鸟飞的方向。"}, {"text": "土豆", "is_correct": false, "explanation": "搭配：“往……飞”后接方向或处所，“土豆”不能作飞行的终点。"}, {"text": "字典", "is_correct": false, "explanation": "语义：“字典”是书，不表示方位，句意不通。"}], "explanations": {"北": "“北”与前文“往南飞”相对，“春天往北飞”表示朝北方飞，符合句意。", "电脑": "语义：“电脑”不是方向，不能作鸟飞的方向。", "土豆": "搭配：“往……飞”后接方向或处所，“土豆”不能作飞行的终点。", "字典": "语义：“字典”是书，不表示方位，句意不通。"}, "sentence_index": 0, "correct_answer": "北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋天到了，燕子往北飞，去南方过冬。", "explanation": "这里应该用〈往南〉。秋天燕子往南飞去南方过冬，“往北”方向相反，与“去南方”矛盾。"}, {"text": "夕阳从北边落下，天边一片金黄。", "explanation": "这里应该用〈西〉。太阳从西边落下，“北”不能用来表示日落的方位。"}, {"text": "从我家出发，往北走五分钟就到学校，学校在我家南边。", "explanation": "这里应该用〈往南〉。学校在我家南边，应往南走，“往北”与句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89421, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "北", "is_correct": true, "explanation": "北是一个方向，跟南相反。"}, {"text": "背", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是用肩膀背东西，如背包。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是杯子。"}, {"text": "被", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是被子或被动。"}, {"text": "美", "is_correct": false, "explanation": "měi 与 běi 声母不同（m 与 b），意思是美丽。"}], "explanations": {"北": "北是一个方向，跟南相反。", "背": "bēi（第一声）与 běi（第三声）声调不同，意思是用肩膀背东西，如背包。", "杯": "bēi（第一声）与 běi（第三声）声调不同，意思是杯子。", "被": "bèi（第四声）与 běi（第三声）声调不同，意思是被子或被动。", "美": "měi 与 běi 声母不同（m 与 b），意思是美丽。"}, "sentence_index": null, "correct_answer": "北"}, "level_3": {"options": [{"text": "北", "is_correct": true, "explanation": "“北”与后文“南”相对，“红箭头指的是北”表示红色箭头指北方，符合句意。"}, {"text": "南", "is_correct": false, "explanation": "语义：后句已说“蓝箭头指的是南”，红箭头不能同样指南，句意矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不是方向，红箭头不能指向手机来表示方位。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“指的是”后接的是方向或标记，“作业”与地图箭头的指向不搭配。"}], "explanations": {"北": "“北”与后文“南”相对，“红箭头指的是北”表示红色箭头指北方，符合句意。", "南": "语义：后句已说“蓝箭头指的是南”，红箭头不能同样指南，句意矛盾。", "手机": "语义：“手机”不是方向，红箭头不能指向手机来表示方位。", "作业": "搭配：“指的是”后接的是方向或标记，“作业”与地图箭头的指向不搭配。"}, "sentence_index": 6, "correct_answer": "北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着自行车一路往北，去南边的海边。", "explanation": "这里应该用〈往南〉。要去南边的海边应往南骑，“往北”与目的地方向相反。"}, {"text": "早上太阳从北边的山后升起，照亮了窗户。", "explanation": "这里应该用〈东〉。太阳从东边升起，“北”不能用于日出的方位。"}, {"text": "我们从东门出去，一直往北走，就到了南门。", "explanation": "这里应该用〈往南〉。南门在南边，一直往北走不会到达，“往北”与“南门”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆在操场的边北。", "corrected_sentence": "图书馆在操场的北边。", "error_description": "词序错误：方位词应说“北边”，不能说“边北”。“北边”是“北”加后缀“边”构成的方位词，顺序不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑着自行车一路在北，去看海。", "corrected_sentence": "他骑着自行车一路往北，去看海。", "error_description": "介词错误：表示行进方向要用“往”或“向”，“在北”表示位置，不能用于“骑”的方向。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
