INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "四个基本方位之一,与南相对。", "primary_collocate": null, "pronunciation": "běi", "ipa": "pei˨˩˦", "syllable_count": 1, "sentences": [{"text": "往北走五分钟就到车站了。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河从南向北流。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了,很多鸟往北飞。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的窗户朝北,夏天很凉快。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里往北走,你会看到一座桥。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指南针的一头指南,另一头指北。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从南到北走过很多城市。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风从北往南吹,特别冷。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上,上面是北,下面是南。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了门往北拐,就是我们学校。", "target_word": "北", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北边", "label": "复合词"}, {"form": "北方", "label": "复合词"}, {"form": "北面", "label": "复合词"}], "register": "中性", "sense_fingerprint": "北:四个基本方位之一,与南相对,单用时多跟往、向、朝、从等搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "北", "is_correct": true, "explanation": "北是四个基本方位之一，与南相对。"}, {"text": "背", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是用肩膀背东西，如背包。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是杯子。"}, {"text": "被", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是被子或被动。"}, {"text": "美", "is_correct": false, "explanation": "měi 与 běi 声母不同（m 与 b），意思是美丽。"}], "explanations": {"北": "北是四个基本方位之一，与南相对。", "背": "bēi（第一声）与 běi（第三声）声调不同，意思是用肩膀背东西，如背包。", "杯": "bēi（第一声）与 běi（第三声）声调不同，意思是杯子。", "被": "bèi（第四声）与 běi（第三声）声调不同，意思是被子或被动。", "美": "měi 与 běi 声母不同（m 与 b），意思是美丽。"}, "sentence_index": null, "correct_answer": "北"}, "level_3": {"options": [{"text": "北", "is_correct": true, "explanation": "“北”是方位词，“往北走”表示向北的方向，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不是方位，不能作“往……走”的方向。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“往”后接处所或方向，“老师”是人，不能作路线的目标。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不表示方向，句子不通。"}], "explanations": {"北": "“北”是方位词，“往北走”表示向北的方向，符合句意。", "书": "语义：“书”不是方位，不能作“往……走”的方向。", "老师": "配价：“往”后接处所或方向，“老师”是人，不能作路线的目标。", "椅子": "语义：“椅子”是家具，不表示方向，句子不通。"}, "sentence_index": 0, "correct_answer": "北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳从北边升起，早上特别暖和。", "explanation": "这里应该用〈东〉。太阳从东边升起，“北”指北方，不能用来表示日出的方位。"}, {"text": "我家在学校北边，每天往北骑车上学。", "explanation": "这里应该用〈往南〉。家在学校北边，上学要往南骑，“往北”与句意矛盾。"}, {"text": "冬天我们往北去，躲开寒冷。", "explanation": "这里应该用〈往南〉。冬天要往南去避寒，“北”方气候更冷，与句意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "北", "is_correct": true, "explanation": "北是四个基本方位之一，与南相对。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 běi（第三声）声调不同，意思是悲伤。"}, {"text": "倍", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是倍数。"}, {"text": "备", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是准备。"}, {"text": "辈", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）声调不同，意思是一辈、一代人。"}, {"text": "每", "is_correct": false, "explanation": "měi 与 běi 声母不同（m 与 b），意思是每个。"}], "explanations": {"北": "北是四个基本方位之一，与南相对。", "悲": "bēi（第一声）与 běi（第三声）声调不同，意思是悲伤。", "倍": "bèi（第四声）与 běi（第三声）声调不同，意思是倍数。", "备": "bèi（第四声）与 běi（第三声）声调不同，意思是准备。", "辈": "bèi（第四声）与 běi（第三声）声调不同，意思是一辈、一代人。", "每": "měi 与 běi 声母不同（m 与 b），意思是每个。"}, "sentence_index": null, "correct_answer": "北"}, "level_3": {"options": [{"text": "北", "is_correct": true, "explanation": "“北”是方位词，与前文“从南”相对，“从南到北”表示从南方到北方，符合句意。"}, {"text": "南", "is_correct": false, "explanation": "语义：前文已有“从南”，“从南到南”自相矛盾，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“到”后接处所，“窗户”不是可以走到的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是方位，不能与“从南到……”搭配。"}], "explanations": {"北": "“北”是方位词，与前文“从南”相对，“从南到北”表示从南方到北方，符合句意。", "南": "语义：前文已有“从南”，“从南到南”自相矛盾，句意不通。", "窗户": "配价：“到”后接处所，“窗户”不是可以走到的地方。", "桌子": "语义：“桌子”不是方位，不能与“从南到……”搭配。"}, "sentence_index": 6, "correct_answer": "北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从超市出发，往北走三分钟就到地铁站，地铁站在超市南边。", "explanation": "这里应该用〈往南〉。地铁站在超市南边，应往南走，“往北”与句意矛盾。"}, {"text": "夕阳从北边落下，天边一片金黄。", "explanation": "这里应该用〈西〉。太阳从西边落下，“北”不能用来表示日落的方位。"}, {"text": "燕子在秋天往北飞，去南方过冬。", "explanation": "这里应该用〈往南〉。秋天燕子往南飞去南方过冬，“往北”方向相反，与“去南方”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店在我家的边北。", "corrected_sentence": "书店在我家的北边。", "error_description": "词序错误：方位词应说“北边”，不能说“边北”。“北边”是“北”加后缀“边”构成的方位词，顺序不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出了门在北走两百米就是超市。", "corrected_sentence": "出了门往北走两百米就是超市。", "error_description": "介词错误：表示行进方向要用“往”，“在北”表示位置，不能用于“走”的方向。应说“往北走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
