INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可随身携带、在移动中使用的无线电话，即手机。", "primary_collocate": null, "pronunciation": "xíng dòng diàn huà", "ipa": "ɕiŋ˧˥ tʊŋ˥˩ tjɛn˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "现在大家都有行动电话。", "target_word": "行动电话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用行动电话上网看新闻。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动电话的声音太大了。", "target_word": "行动电话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把行动电话放进了口袋。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的行动电话响了。", "target_word": "行动电话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了一部新的行动电话。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在火车上也能用行动电话。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的行动电话掉进水里了。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不应该整天玩行动电话。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用行动电话拍了一张照片。", "target_word": "行动电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "行動電話", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无线、可在移动中使用的电话，即手机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动电话", "is_correct": true, "explanation": "正确。现在大家都有手机，“都有”的宾语是可以人手一个的物品。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，人们不会“都有”它。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，“大家都有”不能指大象。"}, {"text": "雷雨", "is_correct": false, "explanation": "搭配：“有”不搭配“雷雨”这类天气现象。"}], "explanations": {"行动电话": "正确。现在大家都有手机，“都有”的宾语是可以人手一个的物品。", "月亮": "语义：月亮是天体，人们不会“都有”它。", "大象": "语义：大象是动物，“大家都有”不能指大象。", "雷雨": "搭配：“有”不搭配“雷雨”这类天气现象。"}, "sentence_index": 0, "correct_answer": "行动电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把行动电话拧进灯座里，屋里就亮了。", "explanation": "这里应该用〈灯泡〉。行动电话是用来打电话的，能让屋子亮起来的应是灯泡。"}, {"text": "他累了，就坐在行动电话上休息。", "explanation": "这里应该用〈椅子〉。行动电话是随身携带的通讯工具，供人坐着休息的应是椅子。"}, {"text": "他把行动电话挂在墙上，每天看几点了。", "explanation": "这里应该用〈挂钟〉。行动电话是随身带的，挂在墙上看时间的应说挂钟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动电话", "is_correct": true, "explanation": "正确。行动电话可以随身带上火车，“也能用”的宾语是可携带的电器。"}, {"text": "煤炉", "is_correct": false, "explanation": "语义：煤炉是固定的炊具，火车上不能用，与“也能用”冲突。"}, {"text": "浴缸", "is_correct": false, "explanation": "配价：“用”的对象要能在火车上使用，浴缸是固定设施，不能随身带去用。"}, {"text": "大炕", "is_correct": false, "explanation": "语义：大炕是固定在房间里的床，与“在火车上”的语境不符。"}], "explanations": {"行动电话": "正确。行动电话可以随身带上火车，“也能用”的宾语是可携带的电器。", "煤炉": "语义：煤炉是固定的炊具，火车上不能用，与“也能用”冲突。", "浴缸": "配价：“用”的对象要能在火车上使用，浴缸是固定设施，不能随身带去用。", "大炕": "语义：大炕是固定在房间里的床，与“在火车上”的语境不符。"}, "sentence_index": 6, "correct_answer": "行动电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家刚装了一部行动电话，装在客厅墙上。", "explanation": "这里应该用〈固定电话〉。行动电话是买来随身带的，不用装在墙上。"}, {"text": "我家的行动电话每天要喂食。", "explanation": "这里应该用〈宠物〉。行动电话不需要喂食，每天要喂食的应是宠物。"}, {"text": "街上的行动电话可以投硬币打。", "explanation": "这里应该用〈公用电话〉。行动电话是个人随身带的，投硬币打的应是公用电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚买了一块新的行动电话。", "corrected_sentence": "他刚买了一部新的行动电话。", "error_description": "错误：“一块行动电话”；正确：“一部行动电话”。行动电话用量词“部”，“块”用于块状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的行动电话摔很坏，不能用了。", "corrected_sentence": "他的行动电话摔得很坏，不能用了。", "error_description": "错误：“摔很坏”；正确：“摔得很坏”。“V得”后接程度补语，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
