INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家里是我们住的房子里面。", "primary_collocate": null, "pronunciation": "jiā lǐ", "ipa": "tɕja˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "家里很干净。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家里有三个房间。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的桌子是新买的。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们在家里看电视。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里有一只小狗。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里太热，我打开了窗户。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的灯都亮着。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书放在家里的桌子上。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里没有水了，我去买一些。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的厨房很大。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "住的房子的里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能用“干净”来形容，“心情很干净”不通。"}, {"text": "家里", "is_correct": true, "explanation": "“家里”指住的房子里面，可以作主语被形容为“很干净”，符合句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间词，不能用“干净”形容。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”指空间或时间的间隔，不能用“干净”描述。"}], "explanations": {"心情": "搭配：“心情”不能用“干净”来形容，“心情很干净”不通。", "家里": "“家里”指住的房子里面，可以作主语被形容为“很干净”，符合句意。", "星期": "语义：“星期”是时间词，不能用“干净”形容。", "距离": "语义：“距离”指空间或时间的间隔，不能用“干净”描述。"}, "sentence_index": 0, "correct_answer": "家里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家里的售票员很热情。", "explanation": "这里应该用〈车站〉。家里指房子内部，家中不会有售票员这类工作人员；车站的售票员要用“车站”。"}, {"text": "家里是我最好的朋友。", "explanation": "这里应该用〈家人〉。家里表示房子内部或家中的状态，不能指具体的人。"}, {"text": "家里的收银员很热情。", "explanation": "这里应该用〈超市〉。家里是住的地方，家中不会有收银员这类职业人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”是抽象概念，不能拥有灯，“价格的灯”不通。"}, {"text": "家里", "is_correct": true, "explanation": "“家里”指住的房子里面，可以作定语，与“灯都亮着”相符。"}, {"text": "句子", "is_correct": false, "explanation": "语义：“句子”不能作“灯”的所属者，“句子的灯”不成立。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“历史”不能与“灯”搭配，“历史的灯”不通。"}], "explanations": {"价格": "语义：“价格”是抽象概念，不能拥有灯，“价格的灯”不通。", "家里": "“家里”指住的房子里面，可以作定语，与“灯都亮着”相符。", "句子": "语义：“句子”不能作“灯”的所属者，“句子的灯”不成立。", "历史": "搭配：“历史”不能与“灯”搭配，“历史的灯”不通。"}, "sentence_index": 6, "correct_answer": "家里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家里的操场很大。", "explanation": "这里应该用〈学校〉。操场是学校这类公共场所的设施，家里的房子内部不会有操场。"}, {"text": "家里的病房很干净。", "explanation": "这里应该用〈医院〉。病房是医院的设施，家里不会有病房。"}, {"text": "家里的取款机很方便。", "explanation": "这里应该用〈银行〉。取款机设在银行或商场，家里不会有取款机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在家里的吃晚饭。", "corrected_sentence": "我们在家里吃晚饭。", "error_description": "错误：“家里”后多加了“的”，“在家里”作处所时后面不加“的”。正确：“我们在家里吃晚饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在家里里学习钢琴。", "corrected_sentence": "她在家里学习钢琴。", "error_description": "错误：“家里”后多加了“里”，“家里”本身已含“里”，不能重复。正确：应说“她在家里学习钢琴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
