INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家的里面;家中。", "primary_collocate": null, "pronunciation": "jiā lǐ", "ipa": "tɕja˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "今天家里没有人。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家里有爸爸、妈妈和姐姐。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我喜欢待在家里。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天感冒，只好在家里休息。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，他一直在家里照顾。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从小在家里说四川话。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的事都是妈妈做主。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天家里来了客人。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家里很穷，但是大家很开心。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里叫我今天早点回去。", "target_word": "家里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在家中；家庭内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能说“今天春天没有人”这样表示人员的情况。"}, {"text": "家里", "is_correct": true, "explanation": "“家里”指家中，“今天家里没有人”表示家中此刻无人，符合句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间词，不能作“没有人”的处所。"}, {"text": "家人", "is_correct": false, "explanation": "搭配：“家人”指具体的人，不能作“没有人”的处所，“家人没有人”不通。"}], "explanations": {"春天": "语义：“春天”是季节，不能说“今天春天没有人”这样表示人员的情况。", "家里": "“家里”指家中，“今天家里没有人”表示家中此刻无人，符合句意。", "星期": "语义：“星期”是时间词，不能作“没有人”的处所。", "家人": "搭配：“家人”指具体的人，不能作“没有人”的处所，“家人没有人”不通。"}, "sentence_index": 0, "correct_answer": "家里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天感冒，只好在家里的病房休息。", "explanation": "这里应该用〈医院〉。家里指家中，家中没有病房这类医院设施；应当在医院的病房里休息。"}, {"text": "家里的乘客很多。", "explanation": "这里应该用〈车站〉。家中不会有乘客，乘客属于车站或车辆。"}, {"text": "家里的同事都很友好。", "explanation": "这里应该用〈公司〉。家中不会有同事，同事只属于公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不由人做主，“天气的事都是妈妈做主”句意不通。"}, {"text": "家里", "is_correct": true, "explanation": "“家里”指家中、家庭内部，“家里的事都是妈妈做主”表示家庭事务，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能作“事”的所属者，“天空的事”不成立。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”是自然现象，“雨的事都是妈妈做主”句意不通。"}], "explanations": {"天气": "语义：天气不由人做主，“天气的事都是妈妈做主”句意不通。", "家里": "“家里”指家中、家庭内部，“家里的事都是妈妈做主”表示家庭事务，符合句意。", "天空": "语义：“天空”不能作“事”的所属者，“天空的事”不成立。", "雨": "语义：“雨”是自然现象，“雨的事都是妈妈做主”句意不通。"}, "sentence_index": 6, "correct_answer": "家里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在家里的银行取了钱。", "explanation": "这里应该用〈附近〉。家里指家中，家中没有银行；应说在附近的银行取钱。"}, {"text": "家里的售货员很热情。", "explanation": "这里应该用〈商店〉。家中不会有售货员，售货员属于商店。"}, {"text": "家里的车站很大。", "explanation": "这里应该用〈城市〉。家中不会有车站，车站属于城市等公共空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们在家里里包饺子。", "corrected_sentence": "周末我们在家里包饺子。", "error_description": "错误：“家里”后多加了“里”，“家里”本身已含“里”，不能重复。正确：应说“周末我们在家里包饺子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家里的来了一位客人。", "corrected_sentence": "家里来了一位客人。", "error_description": "错误：“家里”后多加了“的”。“家里的”是修饰语，后面要接名词，不能直接接动词。正确：“家里来了一位客人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
