INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前的某一天。", "primary_collocate": null, "pronunciation": "nà tiān", "ipa": "na˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "那天下了很大的雨，我没出门。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天我们在公园玩了一下午。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还记得那天他穿的红衣服。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天你为什么没来开会？", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天的饭很好吃，我吃了三碗。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从那天起，他每天早上跑步。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天晚上我很早就睡了。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了那天老师说过什么。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天我在路上遇到了老同学。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天回家以后，我给妈妈打了电话。", "target_word": "那天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那一天", "label": "扩展形式"}], "register": "中性", "sense_fingerprint": "指过去已经发生的某一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那天", "is_correct": true, "explanation": "“那天”指以前的某一天，这里说那天下了大雨、我没出门，合适。"}, {"text": "明天", "is_correct": false, "explanation": "搭配：“明天”指将来，与“下了”（已经发生）和“没出门”的过去语境矛盾。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能下雨，“时间下了很大的雨”不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是一周的单位，不能下雨，“星期下了很大的雨”不通。"}], "explanations": {"那天": "“那天”指以前的某一天，这里说那天下了大雨、我没出门，合适。", "明天": "搭配：“明天”指将来，与“下了”（已经发生）和“没出门”的过去语境矛盾。", "时间": "语义：“时间”不能下雨，“时间下了很大的雨”不通。", "星期": "语义：“星期”是一周的单位，不能下雨，“星期下了很大的雨”不通。"}, "sentence_index": 0, "correct_answer": "那天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们还没定好，那天一起去爬山吧。", "explanation": "这里应该用〈哪天〉。还没定下来的日子要用“哪天”，“那天”指双方已经知道的某一天，不能和“还没定”一起用。"}, {"text": "那天我每天早上都去跑步。", "explanation": "这里应该用〈每天〉。“那天”只指一天，不能和表示反复的“每天”搭配；说经常做的事要用“每天”。"}, {"text": "他一直住在那天。", "explanation": "这里应该用〈那里〉。“住在”后面要说地点，“那天”是时间，不能指住的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那天", "is_correct": true, "explanation": "“那天”指以前的某一天，这里说那天晚上很早睡，合适。"}, {"text": "将来", "is_correct": false, "explanation": "搭配：“将来”指以后，与“就睡了”（已经发生）不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是时间，“冰箱晚上我很早就睡了”不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”不是时间，“闹钟晚上我很早就睡了”不通。"}], "explanations": {"那天": "“那天”指以前的某一天，这里说那天晚上很早睡，合适。", "将来": "搭配：“将来”指以后，与“就睡了”（已经发生）不搭配。", "冰箱": "语义：“冰箱”不是时间，“冰箱晚上我很早就睡了”不通。", "闹钟": "语义：“闹钟”不是时间，“闹钟晚上我很早就睡了”不通。"}, "sentence_index": 6, "correct_answer": "那天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那天是我的老师。", "explanation": "这里应该用〈那位〉。指人要用“那位”，“那天”只指日子，不能指人。"}, {"text": "那天是我的书。", "explanation": "这里应该用〈那个〉。指东西要用“那个”，“那天”只指日子，不能指书。"}, {"text": "我在那天学了三年汉语。", "explanation": "这里应该用〈那些年〉。“那天”只指一天，不能用来说持续三年的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们那天的去了海边。", "corrected_sentence": "我们那天去了海边。", "error_description": "错误：“那天”后面多了“的”，成了“那天的”，后面不能直接接动词“去”。正确：“那天”作时间状语，后面直接接动词，应说“我们那天去了海边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我忘不了那天事。", "corrected_sentence": "我忘不了那天的事。", "error_description": "“那天”修饰名词“事”时要加结构助词“的”，应说“那天的事”，不能说“那天事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
