INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责组织、筹划并监督影视、音乐等作品制作的人。", "primary_collocate": null, "pronunciation": "zhì zuò rén", "ipa": "ʈʂɨ˥˩ tswo˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "制作人要管钱，也要管人。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的制作人正在开会。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制作人负责找演员和工作人员。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为制作人，她要看着每个人的工作。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目的制作人请了很多歌手来参加。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演和制作人一起讨论了拍摄计划。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制作人说，这个计划需要更多时间。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从演员变成了一名制作人。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派了一位新制作人来管这个音乐节目。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制作人要保证作品按时做好。", "target_word": "制作人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "总制作人", "label": "复合"}, {"form": "执行制作人", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责组织、筹划、监督影视音乐作品制作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制作人", "is_correct": true, "explanation": "“制作人”负责管钱、管人，与“要管钱，也要管人”相符。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员负责表演，不负责管钱和管人。"}, {"text": "字幕", "is_correct": false, "explanation": "搭配：“字幕”是文字，不能作“管钱”和“管人”的主语。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众只能看节目，不负责管钱和管人。"}], "explanations": {"制作人": "“制作人”负责管钱、管人，与“要管钱，也要管人”相符。", "演员": "语义：演员负责表演，不负责管钱和管人。", "字幕": "搭配：“字幕”是文字，不能作“管钱”和“管人”的主语。", "观众": "语义：观众只能看节目，不负责管钱和管人。"}, "sentence_index": 0, "correct_answer": "制作人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作为制作人，她要写好每一场戏。", "explanation": "这里应该用〈编剧〉。写戏和写剧本的是编剧，制作人不写剧本。"}, {"text": "作为制作人，她要背好每一句台词。", "explanation": "这里应该用〈演员〉。背台词的是演员，制作人不需要背台词。"}, {"text": "作为制作人，她要扛着机器拍好每个镜头。", "explanation": "这里应该用〈摄影师〉。扛着机器拍镜头的是摄影师，制作人不负责拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制作人", "is_correct": true, "explanation": "“制作人”负责计划的推进，能说“这个计划需要更多时间”。"}, {"text": "片场", "is_correct": false, "explanation": "语义：片场是拍摄地点，不能说话或作出判断。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是设备，不能说“这个计划需要更多时间”。"}, {"text": "剧本", "is_correct": false, "explanation": "语义：剧本是写好的文字，不能说话，不能作“说”的主语。"}], "explanations": {"制作人": "“制作人”负责计划的推进，能说“这个计划需要更多时间”。", "片场": "语义：片场是拍摄地点，不能说话或作出判断。", "灯光": "语义：灯光是设备，不能说“这个计划需要更多时间”。", "剧本": "语义：剧本是写好的文字，不能说话，不能作“说”的主语。"}, "sentence_index": 6, "correct_answer": "制作人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "制作人要把菜一道道端上桌。", "explanation": "这里应该用〈服务员〉。把菜端上桌的是服务员，制作人不负责端菜。"}, {"text": "制作人要唱好每一首歌。", "explanation": "这里应该用〈歌手〉。唱好歌的是歌手，制作人不负责唱歌。"}, {"text": "制作人要保证病人平安。", "explanation": "这里应该用〈医生〉。保证病人平安的是医生，制作人不负责医疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹制作人，每天都很忙。", "corrected_sentence": "妹妹是制作人，每天都很忙。", "error_description": "“制作人”作谓语表示身份时，前面要加“是”。错误形式是“妹妹制作人”，正确形式是“妹妹是制作人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请了一本制作人，他很有经验。", "corrected_sentence": "我们请了一位制作人，他很有经验。", "error_description": "“制作人”指人，量词应用“位”，不能用“本”。错误形式是“一本制作人”，正确形式是“一位制作人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
