INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从事是去做一项工作。", "primary_collocate": null, "pronunciation": "cóng shì", "ipa": "tsʰʊŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我姐姐从事教育工作。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这家公司从事销售工作。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我父亲年轻时从事过农业工作。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在从事什么工作?", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学毕业后,一直从事医疗工作。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从事翻译工作已经十年了。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在银行从事财务工作。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人想从事互联网方面的工作。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有从事过这种工作,所以有点儿紧张。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在北京从事建筑设计。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "从事过", "label": "体标：过"}, {"form": "从事着", "label": "体标：着"}, {"form": "从事了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "做某一项工作或职业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从事", "is_correct": true, "explanation": "从事：做某种工作，与“教育工作”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说吃教育工作。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说唱教育工作。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取的意思，工作不能被偷走，与句子说的是姐姐做教育工作不符。"}], "explanations": {"从事": "从事：做某种工作，与“教育工作”搭配，句意通顺。", "吃": "搭配：“吃”的宾语应是食物，不能说吃教育工作。", "唱": "搭配：“唱”的宾语应是歌曲，不能说唱教育工作。", "偷": "语义：“偷”是窃取的意思，工作不能被偷走，与句子说的是姐姐做教育工作不符。"}, "sentence_index": 0, "correct_answer": "从事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年从事这次马拉松比赛。", "explanation": "这里应该用〈参加〉。从事指长期做某种工作或事业，参加一次比赛要说参加。"}, {"text": "周末他常常从事篮球。", "explanation": "这里应该用〈打〉。从事用于工作或事业，周末的运动要说打篮球。"}, {"text": "放学后我常从事游戏。", "explanation": "这里应该用〈玩〉。从事指长期的工作或事业，放学后的娱乐要说玩游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从事", "is_correct": true, "explanation": "从事：做某种工作，与“财务工作”搭配，句意通顺。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地，不能说打扫财务工作。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”的对象是食物、味道，不能说尝财务工作。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚烧的意思，工作不能被烧，句子说的是朋友在银行做财务工作。"}], "explanations": {"从事": "从事：做某种工作，与“财务工作”搭配，句意通顺。", "打扫": "搭配：“打扫”的对象是房间、场地，不能说打扫财务工作。", "尝": "搭配：“尝”的对象是食物、味道，不能说尝财务工作。", "烧": "语义：“烧”是焚烧的意思，工作不能被烧，句子说的是朋友在银行做财务工作。"}, "sentence_index": 6, "correct_answer": "从事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他积极从事这次讨论。", "explanation": "这里应该用〈参与〉。从事指长期做某种工作或事业，临时参加一次讨论要说参与。"}, {"text": "他小时候从事钢琴。", "explanation": "这里应该用〈学习〉。从事指做工作或事业，小时候学乐器要说学习钢琴。"}, {"text": "她从事班里的体育委员。", "explanation": "这里应该用〈担任〉。从事指做某种工作，班级的职务要说担任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥在一只公司从事会计工作。", "corrected_sentence": "我表哥在一家公司从事会计工作。", "error_description": "量词错误。“公司”的量词应是“家”，“只”多用于动物或成对的东西；正确说法是“在一家公司从事会计工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹明天在医院从事过护理工作。", "corrected_sentence": "我妹妹明天在医院从事护理工作。", "error_description": "错误在“过”。“过”表示已经发生的经历，不能与将来的时间词“明天”同用；去掉“过”，说“明天在医院从事护理工作”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
