INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "投身于某项事业或工作。", "primary_collocate": null, "pronunciation": "cóng shì", "ipa": "tsʰʊŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他一生从事教育事业。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学毕业后,决定从事公益事业。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷一辈子从事科学研究。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生从事医学研究四十年了。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了高薪工作,从事环保事业。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长期从事文化交流事业。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个人一起从事农业科技研究。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小喜欢画画,后来从事艺术创作。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多老师愿意到山区从事教育事业。", "target_word": "从事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直从事文学创作,写了很多书。", "target_word": "从事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "从事过", "label": "体标：过"}, {"form": "从事着", "label": "体标：着"}, {"form": "从事了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "投身于某项事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从事", "is_correct": true, "explanation": "从事：投身于某项事业，与“教育事业”搭配，句意通顺。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹住的意思，事业不能被咬，与“一生”投身事业的意思不合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能说喝教育事业。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、头发等，不能说洗教育事业。"}], "explanations": {"从事": "从事：投身于某项事业，与“教育事业”搭配，句意通顺。", "咬": "语义：“咬”是用牙齿夹住的意思，事业不能被咬，与“一生”投身事业的意思不合。", "喝": "搭配：“喝”的宾语应是饮品，不能说喝教育事业。", "洗": "搭配：“洗”的对象是衣物、头发等，不能说洗教育事业。"}, "sentence_index": 0, "correct_answer": "从事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年从事一场演讲比赛。", "explanation": "这里应该用〈参加〉。从事指长期投身于某项事业，参加一场比赛要说参加。"}, {"text": "平时他喜欢从事足球。", "explanation": "这里应该用〈踢〉。从事指投身于事业或工作，业余的足球活动要说踢足球。"}, {"text": "他从事公司的总经理。", "explanation": "这里应该用〈担任〉。从事指做某种工作，总经理是职务，要说担任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从事", "is_correct": true, "explanation": "从事：投身于某项事业或工作，与“农业科技研究”搭配，句意通顺。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸张、布料等，不能说撕农业科技研究。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等，不能说擦农业科技研究。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打的意思，研究不能被踢，与“一起……研究”的语境不合。"}], "explanations": {"从事": "从事：投身于某项事业或工作，与“农业科技研究”搭配，句意通顺。", "撕": "搭配：“撕”的对象是纸张、布料等，不能说撕农业科技研究。", "擦": "搭配：“擦”的对象是桌面、玻璃等，不能说擦农业科技研究。", "踢": "语义：“踢”是用脚击打的意思，研究不能被踢，与“一起……研究”的语境不合。"}, "sentence_index": 6, "correct_answer": "从事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都从事这次考试。", "explanation": "这里应该用〈参加〉。从事指长期投身于某项事业，临时参加一次考试要说参加。"}, {"text": "他放学后常从事作业。", "explanation": "这里应该用〈做〉。从事指投身于事业或工作，放学后的作业要说做作业。"}, {"text": "周末我们从事羽毛球。", "explanation": "这里应该用〈打〉。从事用于长期的工作或事业，周末的运动要说打羽毛球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在从事了环保事业。", "corrected_sentence": "他正在从事环保事业。", "error_description": "“了”与“正在”不能同用。“正在”表示动作正在进行，应说“正在从事环保事业”，不能说“正在从事了环保事业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长期从事一只生物研究。", "corrected_sentence": "他长期从事一项生物研究。", "error_description": "量词错误。“研究”作名词时应使用量词“项”，说“一项生物研究”，不能用量词“只”（“只”用于动物等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吟诵", "is_correct": false, "explanation": "无关：吟诵是有节奏地朗读，与点燃没有反义关系。"}, {"text": "熄灭", "is_correct": true, "explanation": "反义：点燃是让火烧起来，熄灭是让火停下来，两者意思相反。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：搬运是挪动东西的位置，与点燃没有反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "无关：赞美是称赞别人，与点燃没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"吟诵": "无关：吟诵是有节奏地朗读，与点燃没有反义关系。", "熄灭": "反义：点燃是让火烧起来，熄灭是让火停下来，两者意思相反。", "搬运": "无关：搬运是挪动东西的位置，与点燃没有反义关系。", "赞美": "无关：赞美是称赞别人，与点燃没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "追赶", "is_correct": false, "explanation": "无关：追赶是快跑赶上，与点燃没有反义关系。"}, {"text": "垂钓", "is_correct": false, "explanation": "无关：垂钓是用钓竿钓鱼，与点燃没有反义关系。"}, {"text": "熄灭", "is_correct": true, "explanation": "反义：点燃是让火烧起来，熄灭是让火停下来，两者意思相反。"}, {"text": "缝补", "is_correct": false, "explanation": "无关：缝补是用针线修补衣物，与点燃没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"追赶": "无关：追赶是快跑赶上，与点燃没有反义关系。", "垂钓": "无关：垂钓是用钓竿钓鱼，与点燃没有反义关系。", "熄灭": "反义：点燃是让火烧起来，熄灭是让火停下来，两者意思相反。", "缝补": "无关：缝补是用针线修补衣物，与点燃没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点燃是让火烧起来。", "primary_collocate": null, "pronunciation": "diǎn rán", "ipa": "tjɛn˨˩ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "天黑了，大家点燃了一堆火。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他划了根火柴，点燃了干草。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，火很难点燃。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在河边点燃了篝火。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用木头点燃了火炉。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的晚上，他点燃了壁炉。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶点燃灶火开始做饭。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点燃了火，房间慢慢暖和了。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试了三次才点燃火堆。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们点燃烽火，通知远方的人。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点燃了", "label": "体标"}, {"form": "点燃过", "label": "体标"}], "register": "中性", "sense_fingerprint": "点燃：让火烧起来，生起火堆、火炉等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数", "is_correct": false, "explanation": "语义：火堆不能一个个去数，句子里没有计数的意思。"}, {"text": "点燃", "is_correct": true, "explanation": "正确：“点燃”指让火烧起来，句中说“一堆火”，正好相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：火不能吃，“吃”不能和“火”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是衣物、器具，不能洗火。"}], "explanations": {"数": "语义：火堆不能一个个去数，句子里没有计数的意思。", "点燃": "正确：“点燃”指让火烧起来，句中说“一堆火”，正好相合。", "吃": "搭配：火不能吃，“吃”不能和“火”搭配。", "洗": "搭配：“洗”的对象通常是衣物、器具，不能洗火。"}, "sentence_index": 0, "correct_answer": "点燃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他点燃了客厅里的吊灯。", "explanation": "这里应该用〈点亮〉。点燃用于能烧起来的东西，吊灯靠通电发光，要说“点亮”。"}, {"text": "我们把汤点燃了。", "explanation": "这里应该用〈煮开〉。点燃是使物体着火，汤不能燃烧，把汤煮到沸腾要说“煮开”。"}, {"text": "奶奶把馒头点燃了。", "explanation": "这里应该用〈蒸熟〉。点燃是使物体着火，馒头要靠蒸笼加热，应说“蒸熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "搭配：擦的是台面、器具，灶火不能擦，“擦”不能和“灶火”搭配。"}, {"text": "搬", "is_correct": false, "explanation": "语义：灶火是燃烧着的火，不能搬动，“搬”说不通。"}, {"text": "点燃", "is_correct": true, "explanation": "正确：“点燃”指让灶火烧起来，好开始做饭，句意通顺。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘的是果实、叶子等，灶火不能摘，句子说不通。"}], "explanations": {"擦": "搭配：擦的是台面、器具，灶火不能擦，“擦”不能和“灶火”搭配。", "搬": "语义：灶火是燃烧着的火，不能搬动，“搬”说不通。", "点燃": "正确：“点燃”指让灶火烧起来，好开始做饭，句意通顺。", "摘": "搭配：摘的是果实、叶子等，灶火不能摘，句子说不通。"}, "sentence_index": 6, "correct_answer": "点燃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他点燃了一扇玻璃门。", "explanation": "这里误把“点燃”当成“打碎”的意思来用：玻璃门不能燃烧，弄破玻璃门应说“打碎”。"}, {"text": "他点燃了一阵风。", "explanation": "这里误把“点燃”当成“刮起”的意思来用：风不能燃烧，使风刮起应说“刮起”。"}, {"text": "他点燃了一个笑话。", "explanation": "这里误把“点燃”当成“讲出”的意思来用：笑话不是能烧的东西，讲笑话应说“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上风大，他点燃了一只火，围着它取暖。", "corrected_sentence": "山上风大，他点燃了一堆火，围着它取暖。", "error_description": "错在“点燃”的宾语“火”的量词：“火”应用量词“堆”，说“一堆火”，不说“一只火”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风太大，他还没点燃了火堆，只好等着。", "corrected_sentence": "风太大，他还没点燃火堆，只好等着。", "error_description": "错在否定与“了”：“还没”否定的动作不能再加“了”，应说“还没点燃火堆”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吟诵", "is_correct": false, "explanation": "无关：吟诵是有节奏地朗读，与点燃没有反义关系。"}, {"text": "熄灭", "is_correct": true, "explanation": "反义：点燃是使火烧起来，熄灭是使火停止燃烧，两者意思相反。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：搬运是挪动东西的位置，与点燃没有反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "无关：赞美是称赞别人，与点燃没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"吟诵": "无关：吟诵是有节奏地朗读，与点燃没有反义关系。", "熄灭": "反义：点燃是使火烧起来，熄灭是使火停止燃烧，两者意思相反。", "搬运": "无关：搬运是挪动东西的位置，与点燃没有反义关系。", "赞美": "无关：赞美是称赞别人，与点燃没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "追赶", "is_correct": false, "explanation": "无关：追赶是快跑赶上，与点燃没有反义关系。"}, {"text": "垂钓", "is_correct": false, "explanation": "无关：垂钓是用钓竿钓鱼，与点燃没有反义关系。"}, {"text": "熄灭", "is_correct": true, "explanation": "反义：点燃是使火烧起来，熄灭是使火停止燃烧，两者意思相反。"}, {"text": "缝补", "is_correct": false, "explanation": "无关：缝补是用针线修补衣物，与点燃没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"追赶": "无关：追赶是快跑赶上，与点燃没有反义关系。", "垂钓": "无关：垂钓是用钓竿钓鱼，与点燃没有反义关系。", "熄灭": "反义：点燃是使火烧起来，熄灭是使火停止燃烧，两者意思相反。", "缝补": "无关：缝补是用针线修补衣物，与点燃没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物体着火燃烧。", "primary_collocate": null, "pronunciation": "diǎn rán", "ipa": "tjɛn˨˩ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "他用打火机点燃了蜡烛。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们点燃了篝火，围着它唱歌。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷点燃一支烟，慢慢地抽。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点燃了桌上的香。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人点燃了炉子里的木柴。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们点燃了鞭炮。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在山上点燃树叶。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸点燃，扔进了火盆。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里他点燃煤油灯看书。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点燃火把，走进了山洞。", "target_word": "点燃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点燃了", "label": "体标"}, {"form": "点燃过", "label": "体标"}], "register": "中性", "sense_fingerprint": "点燃：用火使蜡烛、柴草等物体着火燃烧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吹灭", "is_correct": false, "explanation": "语义：吹灭是用气流把火弄熄，与用打火机使蜡烛着起来的意思相反。"}, {"text": "点燃", "is_correct": true, "explanation": "正确：“点燃”指用火使蜡烛着起来，和“打火机”的用途相合。"}, {"text": "切", "is_correct": false, "explanation": "语义：切要用刀具，打火机不能切蜡烛，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：蜡烛不能吃，“吃”不能和“蜡烛”搭配。"}], "explanations": {"吹灭": "语义：吹灭是用气流把火弄熄，与用打火机使蜡烛着起来的意思相反。", "点燃": "正确：“点燃”指用火使蜡烛着起来，和“打火机”的用途相合。", "切": "语义：切要用刀具，打火机不能切蜡烛，句子说不通。", "吃": "搭配：蜡烛不能吃，“吃”不能和“蜡烛”搭配。"}, "sentence_index": 0, "correct_answer": "点燃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他点燃了房间里的电灯。", "explanation": "这里应该用〈点亮〉。点燃用于能烧起来的东西，电灯靠通电发光，要说“点亮”。"}, {"text": "他把水点燃了。", "explanation": "这里应该用〈烧开〉。点燃是使物体着火，水不能燃烧，把水加热到沸腾要说“烧开”。"}, {"text": "妈妈把面包点燃了。", "explanation": "这里应该用〈烤熟〉。点燃是使物体着火，面包要靠烤箱加热，应说“烤熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "搭配：树叶不是修理的对象，“修”不能和“树叶”搭配。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是关闭或固定，树叶不能被锁上，句子说不通。"}, {"text": "点燃", "is_correct": true, "explanation": "正确：“点燃”指用火使树叶着起来，与“请不要在山上”的提醒相合。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”指关闭门窗或开关，用在树叶上没有意义。"}], "explanations": {"修": "搭配：树叶不是修理的对象，“修”不能和“树叶”搭配。", "锁": "语义：锁是关闭或固定，树叶不能被锁上，句子说不通。", "点燃": "正确：“点燃”指用火使树叶着起来，与“请不要在山上”的提醒相合。", "关": "语义：“关”指关闭门窗或开关，用在树叶上没有意义。"}, "sentence_index": 6, "correct_answer": "点燃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他点燃了窗边的玻璃。", "explanation": "这里误把“点燃”当成“打碎”的意思来用：玻璃不能燃烧，弄破玻璃应说“打碎”。"}, {"text": "他点燃了那块冰。", "explanation": "这里误把“点燃”当成“使……化开”的意思来用：冰不能燃烧，使冰化开应说“融化”。"}, {"text": "他点燃了一块石头。", "explanation": "这里误把“点燃”当成“打出火花”的意思来用：石头本身不能燃烧，用石头取火应说“打出火花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "停电后，我点燃了一只蜡烛，照着看书。", "corrected_sentence": "停电后，我点燃了一支蜡烛，照着看书。", "error_description": "错在“点燃”的宾语“蜡烛”的量词：“蜡烛”应用量词“支”，说“一支蜡烛”，不说“一只蜡烛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没点燃了灯笼，屋里一片漆黑。", "corrected_sentence": "他还没点燃灯笼，屋里一片漆黑。", "error_description": "错在否定与“了”：“还没”否定的动作不能再加“了”，应说“还没点燃灯笼”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谦虚", "is_correct": true, "explanation": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难或危险，与“骄傲”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人亲切主动，与“骄傲”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指反应快、有智慧，与“骄傲”没有反义关系。"}], "correct_answer": "谦虚", "explanations": {"谦虚": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。", "勇敢": "“勇敢”指不怕困难或危险，与“骄傲”没有反义关系。", "热情": "“热情”指待人亲切主动，与“骄傲”没有反义关系。", "聪明": "“聪明”指反应快、有智慧，与“骄傲”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谦虚", "is_correct": true, "explanation": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“骄傲”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”与“复杂”相对，与“骄傲”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好、待人友善，与“骄傲”没有反义关系。"}], "correct_answer": "谦虚", "explanations": {"谦虚": "“谦虚”是“骄傲”（看不起别人、自以为了不起）的反义词。", "安静": "“安静”与“吵闹”相对，与“骄傲”没有反义关系。", "简单": "“简单”与“复杂”相对，与“骄傲”没有反义关系。", "善良": "“善良”指心地好、待人友善，与“骄傲”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "觉得自己很好，别人都不如自己。", "primary_collocate": null, "pronunciation": "jiāo ào", "ipa": "tɕjɑʊ˥ ɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他觉得自己最好，太骄傲了。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很骄傲，从来不听别人的话。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骄傲的人看不起别人。", "target_word": "骄傲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别那么骄傲，你也有错的时候。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直很骄傲，所以朋友越来越少。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子骄傲得谁都不理。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理骄傲地说：“这里没有人比我强。”", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他赢了一次就骄傲了，不想再学习。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的骄傲让同事们很不舒服。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骄傲的小王觉得别人都不如他。", "target_word": "骄傲", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骄傲地", "label": "状语形式"}, {"form": "骄傲自满", "label": "复合"}, {"form": "驕傲", "label": "繁体"}], "register": "通用", "sense_fingerprint": "骄傲：自以为了不起、看不起别人的态度，含贬义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4935a66f-b0a5-4cd5-b0f8-380dba48c616') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骄傲", "is_correct": true, "explanation": "“骄傲”指自以为了不起、看不起别人，与“觉得自己最好”的语境一致。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”与“觉得自己最好”的自信态度相矛盾，句意不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”说身高，与自我评价无关，句意不通。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”与“觉得自己最好”相矛盾，句意不通。"}], "explanations": {"骄傲": "“骄傲”指自以为了不起、看不起别人，与“觉得自己最好”的语境一致。", "懦弱": "语义：“懦弱”与“觉得自己最好”的自信态度相矛盾，句意不通。", "矮": "体貌：“矮”说身高，与自我评价无关，句意不通。", "胆小": "语义：“胆小”与“觉得自己最好”相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "骄傲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被人误会了，心里很骄傲，气得直跺脚。", "explanation": "这里应该用〈生气〉。骄傲表示觉得自己比别人好，不能表示被误会后的恼怒。"}, {"text": "失败后，他骄傲地哭了起来。", "explanation": "这里应该用〈伤心〉。骄傲表示自满，不能用来形容伤心哭泣的样子。"}, {"text": "听到雷声，他骄傲地躲进了被子里。", "explanation": "这里应该用〈害怕〉。骄傲表示觉得自己比别人好，不能用来形容躲进被子、胆怯的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骄傲", "is_correct": true, "explanation": "“骄傲”表示看不起别人，与“这里没有人比我强”的自夸语气一致。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”与自夸的语气不符，句意不通。"}, {"text": "客气", "is_correct": false, "explanation": "语义：“客气”表示谦让有礼，与“这里没有人比我强”的自夸语气矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”说身高，不能用来修饰说话的样子。"}], "explanations": {"骄傲": "“骄傲”表示看不起别人，与“这里没有人比我强”的自夸语气一致。", "悲伤": "语义：“悲伤”与自夸的语气不符，句意不通。", "客气": "语义：“客气”表示谦让有礼，与“这里没有人比我强”的自夸语气矛盾。", "高": "体貌：“高”说身高，不能用来修饰说话的样子。"}, "sentence_index": 6, "correct_answer": "骄傲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向老师认错时，很骄傲地红了脸。", "explanation": "这里应该用〈不好意思〉。骄傲表示觉得自己比别人好，不能用来形容认错时脸红窘迫的样子。"}, {"text": "上台前，他骄傲地捂着嘴，小声地问：“我能不能不上去？”", "explanation": "这里应该用〈胆怯〉。骄傲表示觉得自己比别人好，与小声恳求不上去的样子相矛盾。"}, {"text": "他一进教室就很骄傲地低下了头。", "explanation": "这里应该用〈害羞〉。低头表示害羞，与骄傲的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骄傲的看了我们一眼，什么话也没说。", "corrected_sentence": "他骄傲地看了我们一眼，什么话也没说。", "error_description": "错误形式“骄傲的看”；正确形式“骄傲地看”。动词前的状语要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近突然骄傲下来了。", "corrected_sentence": "他最近突然骄傲起来了。", "error_description": "“骄傲”表示状态开始出现时要用趋向补语“起来”；“下来”多用于表示平静、减弱的状态（如“安静下来”），与“骄傲”搭配不自然。错误形式“骄傲下来”，正确形式为“骄傲起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
