INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89439, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解答是把别人问的问题说清楚。", "primary_collocate": null, "pronunciation": "jiě dá", "ipa": "tɕjɛ˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "老师耐心地解答了学生提出的问题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难，请你帮我解答一下。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服正在电话里解答顾客的疑问。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的问题一个一个地解答清楚了。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么不懂的，我可以给你解答。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生详细解答了病人关于饮食的问题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，专家现场解答大家的提问。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写信问他，他很快就解答了。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书解答了我对历史的很多疑问。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从不嫌烦，总是认真解答孩子的问题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解答了", "label": "完成体"}, {"form": "解答过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "回答别人提出的问题，把疑问说清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与“耐心地”态度相反，老师不会耐心地嘲笑学生。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示回避问题，与“耐心地”矛盾，句子不通。"}, {"text": "解答", "is_correct": true, "explanation": "正确：“解答”指把学生提出的问题说清楚，与“耐心地”相合。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“提出的问题”作宾语。"}], "explanations": {"嘲笑": "语义：“嘲笑”与“耐心地”态度相反，老师不会耐心地嘲笑学生。", "逃避": "语义：“逃避”表示回避问题，与“耐心地”矛盾，句子不通。", "解答": "正确：“解答”指把学生提出的问题说清楚，与“耐心地”相合。", "哭": "配价：“哭”是不及物动词，不能带“提出的问题”作宾语。"}, "sentence_index": 0, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就解答了这件事。", "explanation": "这里应该用〈解决〉。解答只用于问题、疑问，“这件事”这类事务要用解决。"}, {"text": "他花了很久才解答这个结。", "explanation": "这里应该用〈解开〉。解答用于问题、疑问，结和绳子等要用解开。"}, {"text": "我提出请求后，他解答了我的请求。", "explanation": "这里应该用〈答应〉。解答用于问题、疑问，“请求”要用答应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“大家的提问”作宾语。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”与“专家现场”“提问”不相容，专家不会去偷提问。"}, {"text": "解答", "is_correct": true, "explanation": "正确：“解答”指针对“大家的提问”给出解释，与“现场”相合。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”针对申请、计划，不能带“提问”作宾语。"}], "explanations": {"散步": "配价：“散步”是不及物动词，不能带“大家的提问”作宾语。", "偷": "语义：“偷”与“专家现场”“提问”不相容，专家不会去偷提问。", "解答": "正确：“解答”指针对“大家的提问”给出解释，与“现场”相合。", "批准": "搭配：“批准”针对申请、计划，不能带“提问”作宾语。"}, "sentence_index": 6, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈从不嫌烦，总是认真解答孩子的玩具。", "explanation": "这里应该用〈修〉。解答的对象只能是问题、疑问，坏了的玩具要用修，不能说解答。"}, {"text": "妈妈从不嫌烦，总是认真解答孩子的晚饭。", "explanation": "这里应该用〈准备〉。解答的对象只能是问题、疑问，做晚饭要用准备，不能说解答。"}, {"text": "妈妈从不嫌烦，总是认真解答孩子的房间。", "explanation": "这里应该用〈收拾〉。解答的对象只能是问题、疑问，整理房间要用收拾，不能说解答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师解答很清楚，学生都听懂了。", "corrected_sentence": "老师解答得很清楚，学生都听懂了。", "error_description": "错误形式：“解答很清楚”，缺少补语标记“得”；正确形式：“解答得很清楚”，“得”引出情态补语，描述解答的情况。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于解答了完所有问题。", "corrected_sentence": "他终于解答完了所有问题。", "error_description": "错误形式：“解答了完”，结果补语“完”应紧跟动词，“了”放在补语之后；正确形式：“解答完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
