INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对问题加以说明、解释并给出答案。", "primary_collocate": null, "pronunciation": "jiě dá", "ipa": "tɕjɛ˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "数学老师在黑板上解答这道难题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先解答第三题，再看第四题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有马上解答，而是让我们自己想。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家用简单的话解答了网友关心的问题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了一个小时才解答出这道题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位律师免费为大家解答法律问题。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生举手提问，老师当场解答。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时要先解答容易的题目。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有人专门解答新手的疑问。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解答完问题后，大家都点头了。", "target_word": "解答", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解答了", "label": "完成体"}, {"form": "解答过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对题目或问题加以解释并给出答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b41ffc-15e7-408c-b241-b02b4f737514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只能带歌曲等作宾语，不能说“唱这道难题”。"}, {"text": "解答", "is_correct": true, "explanation": "正确：“解答”指对难题加以解释并给出答案，与“数学老师”“黑板上”相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多用于花果等，不能跟“这道难题”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“这道难题”作宾语。"}], "explanations": {"唱": "搭配：“唱”只能带歌曲等作宾语，不能说“唱这道难题”。", "解答": "正确：“解答”指对难题加以解释并给出答案，与“数学老师”“黑板上”相合。", "摘": "搭配：“摘”多用于花果等，不能跟“这道难题”搭配。", "睡觉": "配价：“睡觉”是不及物动词，不能带“这道难题”作宾语。"}, "sentence_index": 0, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他解答了鞋带，就出门了。", "explanation": "这里应该用〈解开〉。解答用于问题、疑问，鞋带要用解开。"}, {"text": "这个困难我们一定要解答。", "explanation": "这里应该用〈解决〉。解答用于问题、疑问，“困难”要用解决。"}, {"text": "我提出请求后，他解答了我的请求。", "explanation": "这里应该用〈答应〉。解答用于问题、疑问，“请求”要用答应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与“学生举手提问”无关，老师不会“当场毕业”。"}, {"text": "解答", "is_correct": true, "explanation": "正确：“解答”指当场针对学生的提问给出答案，与“举手提问”相合。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物等实物，不能跟“提问”搭配。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”是及物动词，需要带具体的东西作宾语，句中无法成立。"}], "explanations": {"毕业": "语义：“毕业”指完成学业，与“学生举手提问”无关，老师不会“当场毕业”。", "解答": "正确：“解答”指当场针对学生的提问给出答案，与“举手提问”相合。", "搬运": "搭配：“搬运”的对象是货物等实物，不能跟“提问”搭配。", "拆": "配价：“拆”是及物动词，需要带具体的东西作宾语，句中无法成立。"}, "sentence_index": 6, "correct_answer": "解答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他解答完饭菜后，大家都点头了。", "explanation": "这里应该用〈做〉。解答只用于问题、疑问，做饭菜要用做。"}, {"text": "他解答完汽车后，大家都点头了。", "explanation": "这里应该用〈修〉。解答只用于问题、疑问，汽车要用修。"}, {"text": "他解答完这首歌后，大家都鼓掌了。", "explanation": "这里应该用〈唱〉。解答只用于问题、疑问，唱歌要用唱，不能说解答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从没解答了这么难的题。", "corrected_sentence": "我从没解答过这么难的题。", "error_description": "错误形式：“没解答了”，否定经历要用“没……过”，不能用“了”；正确形式：“没解答过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些难题他解答很快。", "corrected_sentence": "这些难题他解答得很快。", "error_description": "错误形式：“解答很快”，缺少补语标记“得”；正确形式：“解答得很快”，“得”引出情态补语，描述解答的速度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59befbf9-98b9-48cc-9fa0-d70e5fea4a5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "部分", "is_correct": true, "explanation": "正确。“部分”与“整体”构成反义，指整体之中的局部。"}, {"text": "成员", "is_correct": false, "explanation": "语义：“成员”指组织中的个人，与“整体”不构成反义关系。"}, {"text": "环境", "is_correct": false, "explanation": "语义：“环境”指周围的情况，与“整体”不构成反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：“节奏”指有规律的变化，与“整体”不构成反义关系。"}], "correct_answer": "部分", "explanations": {"部分": "正确。“部分”与“整体”构成反义，指整体之中的局部。", "成员": "语义：“成员”指组织中的个人，与“整体”不构成反义关系。", "环境": "语义：“环境”指周围的情况，与“整体”不构成反义关系。", "节奏": "语义：“节奏”指有规律的变化，与“整体”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
