INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体是所有的部分合在一起。", "primary_collocate": null, "pronunciation": "zhěng tǐ", "ipa": "ʈʂɤŋ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "手和脚都是身体的一部分,身体是一个整体。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都是班级这个整体的一部分。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个整体由三个部分组成。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师把机器看作一个统一的整体来设计。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子只是树的一部分,不是整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套家具是一个整体,不能分开卖。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河和大山合在一起,成了一个美丽的整体。", "target_word": "整体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个零件都重要,因为机器是一个整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个人配合得好,像一个整体。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一幅画是一个整体，不能只看一个小地方。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整体性", "label": "复合"}, {"form": "整体上", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体:各个部分合在一起形成的一个统一的东西,与部分相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。“整体”指身体是各部分合成的统一体，与“一部分”相对应。"}, {"text": "集体", "is_correct": false, "explanation": "语义：“集体”指由人组成的群体，身体不是人群，句意不合。"}, {"text": "全体", "is_correct": false, "explanation": "搭配：“全体”指人员的全部，不能说“身体是一个全体”。"}, {"text": "单位", "is_correct": false, "explanation": "语义：“单位”指机构或计量单位，身体不是这种组织，句意不合。"}], "explanations": {"整体": "正确。“整体”指身体是各部分合成的统一体，与“一部分”相对应。", "集体": "语义：“集体”指由人组成的群体，身体不是人群，句意不合。", "全体": "搭配：“全体”指人员的全部，不能说“身体是一个全体”。", "单位": "语义：“单位”指机构或计量单位，身体不是这种组织，句意不合。"}, "sentence_index": 0, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "整体同学都参加了比赛，场面很热闹。", "explanation": "这里应用“全体”。“整体”指各部分合成的统一体，指人群的全部要用“全体”。"}, {"text": "这套家具是一块整体，不能分开卖。", "explanation": "量词错误：“整体”作为统一体的名词，前面应用“个”或“套”，“块”不能用来计量“整体”。"}, {"text": "整体城市都很安静，夜里听不到声音。", "explanation": "这里应用“整个”。“整体”指统一体，不能直接修饰“城市”这类具体的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。河与山合在一起，成为一个统一的整体，与句意相合。"}, {"text": "总和", "is_correct": false, "explanation": "语义：“总和”指数量相加的结果，不能描述河与山合成的景象。"}, {"text": "单位", "is_correct": false, "explanation": "语义：“单位”指机构或计量单位，与自然景物的描写不合。"}, {"text": "同盟", "is_correct": false, "explanation": "搭配：“同盟”指政治或军事上的联合，不用于描写自然景物。"}], "explanations": {"整体": "正确。河与山合在一起，成为一个统一的整体，与句意相合。", "总和": "语义：“总和”指数量相加的结果，不能描述河与山合成的景象。", "单位": "语义：“单位”指机构或计量单位，与自然景物的描写不合。", "同盟": "搭配：“同盟”指政治或军事上的联合，不用于描写自然景物。"}, "sentence_index": 6, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "整体学生都已经到齐了，我们可以出发了。", "explanation": "这里应用“全体”。“整体”是统一的事物，不能直接修饰人群。"}, {"text": "这些菜的整体很多，我们吃不完。", "explanation": "这里误把统一体的“整体”当成计数的数量词来用，应说“很多”或“全部”。"}, {"text": "这幅画是一块整体。", "explanation": "量词错误：“整体”前应用“个”，“块”不能用来计量“整体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台设备是一个的整体，不能拆开用。", "corrected_sentence": "这台设备是一个整体，不能拆开用。", "error_description": "数量短语“一个”与名词“整体”之间不能加“的”，应直接说“一个整体”。“一个的整体”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这组画是一只整体，要挂在一起。", "corrected_sentence": "这组画是一个整体，要挂在一起。", "error_description": "“整体”前的量词应用“个”。“只”一般用于动物、鞋袜等，不能用来修饰“整体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
