INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的全部，总的情况，常用于从整体上评价。", "primary_collocate": null, "pronunciation": "zhěng tǐ", "ipa": "ʈʂɤŋ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个计划整体不错,只有一点小问题。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从整体来看,公司今年做得很好。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "整体上说,这次考试不太难。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次改革的整体效果比我们预想的好。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先了解事情的整体,再看细节。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的整体环境很好。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "整体来说,他的成绩比去年高了。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛,我们队的整体水平很高。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只看一个小地方,不能了解整体的情况。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的整体服务让客人很满意。", "target_word": "整体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整体性", "label": "复合"}, {"form": "整体上", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体:事物的全部、总的情况,常用于从整体上评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。“整体”在此表示总的情况，与“只有一点小问题”相呼应。"}, {"text": "部件", "is_correct": false, "explanation": "语义：“部件”指机器的零件，计划不是机器，句意不合。"}, {"text": "全体", "is_correct": false, "explanation": "搭配：“全体”指人员的全部，不能说“计划全体”。"}, {"text": "个体", "is_correct": false, "explanation": "语义：“个体”指单个的人或事物，不用于指计划的总体评价。"}], "explanations": {"整体": "正确。“整体”在此表示总的情况，与“只有一点小问题”相呼应。", "部件": "语义：“部件”指机器的零件，计划不是机器，句意不合。", "全体": "搭配：“全体”指人员的全部，不能说“计划全体”。", "个体": "语义：“个体”指单个的人或事物，不用于指计划的总体评价。"}, "sentence_index": 0, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "整体城市都停电了，大家只好点蜡烛。", "explanation": "这里应用“整个”。“整体”不能直接修饰“城市”这类具体事物。"}, {"text": "这套家具是一块整体，不能分开卖。", "explanation": "量词错误：“整体”前应用“个”或“套”，“块”不能用来计量作为统一体的“整体”。"}, {"text": "整体的老师都很认真，学生们都很喜欢。", "explanation": "这里应用“全体”。“整体”不能修饰“老师”这类人群，指人群要说“全体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整体", "is_correct": true, "explanation": "正确。“整体来说”表示总的看，与后半句的整体判断相呼应。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立刻，不能与“来说”组成表示总体判断的说法。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能放在“来说”的总括框架前。"}, {"text": "个别", "is_correct": false, "explanation": "搭配：“个别”指少数，不能用于“来说”引出的总体判断。"}], "explanations": {"整体": "正确。“整体来说”表示总的看，与后半句的整体判断相呼应。", "马上": "搭配：“马上”表示立刻，不能与“来说”组成表示总体判断的说法。", "非常": "搭配：“非常”是程度副词，不能放在“来说”的总括框架前。", "个别": "搭配：“个别”指少数，不能用于“来说”引出的总体判断。"}, "sentence_index": 6, "correct_answer": "整体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "整体的同事都很努力，工作效率很高。", "explanation": "这里应用“全体”。“整体”不能修饰“同事”这类人群。"}, {"text": "这台机器是一块整体，不能拆开修。", "explanation": "量词错误：“整体”前应用“个”，“块”不能用来计量“整体”。"}, {"text": "这些书的整体都是他的，别人不能拿走。", "explanation": "这里应用“全部”。“整体”表示统一的全体，不能用来指一批彼此独立的书，应说“全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动整体的很成功。", "corrected_sentence": "这次活动整体很成功。", "error_description": "错误：「整体」后误加结构助词「的」，「的」需接名词中心语，此处「很成功」没有中心语。正确：删去「的」，即「这次活动整体很成功」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "整体看上，今年的业绩很好。", "corrected_sentence": "整体上看，今年的业绩很好。", "error_description": "“整体上看”中“上”紧跟“整体”，构成“整体上”。“整体看上”语序错误，“看上”另有“喜欢”的意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
