INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上路是开始走，出发去远的地方。", "primary_collocate": null, "pronunciation": "shàng lù", "ipa": "ʂɑŋ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "天刚亮，他们就上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完早饭，我们准备上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送我到车站，我就上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天不早了，你该上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着包上路，去很远的城市。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李收拾好了，我们马上上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，旅行者已经上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告别家人，独自上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家休息够了，继续上路吧。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着地图上路，要去西藏。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上路了", "label": "体标"}, {"form": "上了路", "label": "离合"}], "register": "中性", "sense_fingerprint": "上路：开始赶路，出发去远处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打烊", "is_correct": false, "explanation": "语义：打烊是晚上关门歇业，天刚亮时说“打烊”不合。"}, {"text": "上路", "is_correct": true, "explanation": "正确：“上路”指开始赶路、出发，天刚亮正是出发的时候。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：午睡是中午小睡，天刚亮时说“午睡”不合。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜指夜里不睡觉，天刚亮时说“熬夜”不合。"}], "explanations": {"打烊": "语义：打烊是晚上关门歇业，天刚亮时说“打烊”不合。", "上路": "正确：“上路”指开始赶路、出发，天刚亮正是出发的时候。", "午睡": "语义：午睡是中午小睡，天刚亮时说“午睡”不合。", "熬夜": "语义：熬夜指夜里不睡觉，天刚亮时说“熬夜”不合。"}, "sentence_index": 0, "correct_answer": "上路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他七点上路，去厨房给全家做早饭。", "explanation": "“上路”指出发去远方，走进厨房做饭只是几步路，应说“进厨房”。"}, {"text": "她晚上七点上路，在家写完作业就睡。", "explanation": "“上路”指出发去远方，在家写作业不是出行，应说“开始写”。"}, {"text": "他下午上路，在院子里晒太阳。", "explanation": "“上路”指出发去远方，在院子里晒太阳不是远行，应说“坐下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停工", "is_correct": false, "explanation": "搭配：停工说的是工人或工厂停止劳动，旅行者不能停工。"}, {"text": "下岗", "is_correct": false, "explanation": "搭配：下岗指职工离开工作岗位，旅行者没有岗位，不能下岗。"}, {"text": "上路", "is_correct": true, "explanation": "正确：“上路”指出发赶路，下雨前旅行者出发，句意通顺。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：罢工是集体停止工作，旅行者不会罢工，句子说不通。"}], "explanations": {"停工": "搭配：停工说的是工人或工厂停止劳动，旅行者不能停工。", "下岗": "搭配：下岗指职工离开工作岗位，旅行者没有岗位，不能下岗。", "上路": "正确：“上路”指出发赶路，下雨前旅行者出发，句意通顺。", "罢工": "语义：罢工是集体停止工作，旅行者不会罢工，句子说不通。"}, "sentence_index": 6, "correct_answer": "上路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子已经上路了。", "explanation": "这里误把“上路”当成“被搬走”的意思来用：桌子不会自己出发，表示被搬走应说“搬走”。"}, {"text": "这间房子明天就要上路。", "explanation": "这里误把“上路”当成“搬迁”的意思来用：房子不能自己出发，表示搬迁应说“搬走”。"}, {"text": "这块石头已经上路了。", "explanation": "这里误把“上路”当成“被挪走”的意思来用：石头不会自己出发，表示被挪走应说“挪走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们天亮前就上路了这条路，一直走到中午。", "corrected_sentence": "他们天亮前就上了这条路，一直走到中午。", "error_description": "错在离合词“上路”：它是离合词，不能直接带宾语“这条路”，应说“上了这条路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车队刚出城，就上路过。", "corrected_sentence": "车队刚出城，就上路了。", "error_description": "错在“上路”的体标：“过”表示曾经有过的经历，与“刚出城就……”这一刚发生的动作不符，应说“就上路了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
