INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出发；起程。", "primary_collocate": null, "pronunciation": "shàng lù", "ipa": "ʂɑŋ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "车已经备好，请您上路吧。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿起行李，高兴地上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来时，车队上路了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们要上路了，妈妈很担心。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天一早就上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们唱着歌上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前检查一下，再上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们上路以后，天气变好了。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了春节，农民工纷纷上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们挥手告别，看着他上路。", "target_word": "上路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上路了", "label": "体标"}, {"form": "上了路", "label": "离合"}], "register": "中性", "sense_fingerprint": "上路：出发，起程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报废", "is_correct": false, "explanation": "语义：报废是车不能再用，与“车已经备好”的意思矛盾。"}, {"text": "歇业", "is_correct": false, "explanation": "搭配：歇业说的是商店、企业停业，车不能歇业。"}, {"text": "上路", "is_correct": true, "explanation": "正确：“上路”指出发、起程，与“车已经备好，请您……”相合。"}, {"text": "停车", "is_correct": false, "explanation": "语义：停车是停下来，与“车已经备好、请您出发”的意思相反。"}], "explanations": {"报废": "语义：报废是车不能再用，与“车已经备好”的意思矛盾。", "歇业": "搭配：歇业说的是商店、企业停业，车不能歇业。", "上路": "正确：“上路”指出发、起程，与“车已经备好，请您……”相合。", "停车": "语义：停车是停下来，与“车已经备好、请您出发”的意思相反。"}, "sentence_index": 0, "correct_answer": "上路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到铃声就上路，回到座位上写作业。", "explanation": "“上路”指出发去远方，回到座位只是几步路，应说“回座位”。"}, {"text": "我们每天晚上上路，在家看电视打发时间。", "explanation": "“上路”指出发去远方，在家看电视不是出行，应说“坐下”。"}, {"text": "他读完这本书就上路，开始写读后感。", "explanation": "“上路”指出发去远方，写读后感是动笔写作，应说“动笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进门", "is_correct": false, "explanation": "语义：进门是走进屋里，与“出门”的方向相反。"}, {"text": "落户", "is_correct": false, "explanation": "语义：落户是在某地安家定居，与“出门前检查一下，再……”的出发情境不合。"}, {"text": "入睡", "is_correct": false, "explanation": "语义：入睡是睡着，与“出门前检查一下”的情境矛盾。"}, {"text": "上路", "is_correct": true, "explanation": "正确：“上路”指出发赶路，与“出门前检查一下，再……”的顺序相合。"}], "explanations": {"进门": "语义：进门是走进屋里，与“出门”的方向相反。", "落户": "语义：落户是在某地安家定居，与“出门前检查一下，再……”的出发情境不合。", "入睡": "语义：入睡是睡着，与“出门前检查一下”的情境矛盾。", "上路": "正确：“上路”指出发赶路，与“出门前检查一下，再……”的顺序相合。"}, "sentence_index": 6, "correct_answer": "上路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条小河已经上路了。", "explanation": "这里误把“上路”当成“流走”的意思来用：河水不会出发去远方，形容河流远去应说“流去”。"}, {"text": "这栋大楼明天要上路。", "explanation": "这里误把“上路”当成“搬迁”的意思来用：大楼不会自己出发，表示整体搬迁应说“迁移”。"}, {"text": "那棵大树已经上路了。", "explanation": "这里误把“上路”当成“被移走”的意思来用：大树不会自己出发，表示被移走应说“移栽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们正在上了路，要去外婆家。", "corrected_sentence": "孩子们正在上路，要去外婆家。", "error_description": "错在“正在”与“了”：表示进行中的动作不能同时用“了”，应说“正在上路”，不说“正在上了路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车队很早就上路这条路，走得很快。", "corrected_sentence": "车队很早就上了这条路，走得很快。", "error_description": "错在离合词“上路”：它是离合词，不能直接带宾语“这条路”，应说“上了这条路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话传说中害人的鬼怪；比喻邪恶的力量。", "primary_collocate": null, "pronunciation": "mó", "ipa": "mwo˧˥", "syllable_count": 1, "sentences": [{"text": "他一直在和心中的魔斗争，很辛苦。", "target_word": "魔", "complexity_tier": "T3", "furigana": "mó", "sentence_source": "generated"}, {"text": "他心里有魔，为了钱什么都敢做。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要小心，贪心就是魔。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毒品是害人的魔，千万不能碰。", "target_word": "魔", "complexity_tier": "T3", "furigana": "mó", "sentence_source": "generated"}, {"text": "她终于战胜了心里的魔，不再害怕了。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争是人间的魔，让很多家庭失去亲人。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪婪是人心里的魔，会让人失去理智。", "target_word": "魔", "complexity_tier": "T3", "furigana": "mó", "sentence_source": "generated"}, {"text": "愤怒像魔一样，让他失去了理智。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懒惰是人生路上的魔，要早点克服。", "target_word": "魔", "complexity_tier": "T3", "furigana": "mó", "sentence_source": "generated"}, {"text": "他输掉了房子，是赌博这个魔害了他。", "target_word": "魔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "魔鬼", "label": "复合"}, {"form": "魔王", "label": "复合"}], "register": "中性", "sense_fingerprint": "魔：传说中害人的鬼怪，也比喻让人变坏的邪恶力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "魔", "is_correct": true, "explanation": "魔：神话传说中害人的鬼怪，比喻邪恶的力量，是本词的意思。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手接触。"}, {"text": "墨", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。"}, {"text": "婆", "is_correct": false, "explanation": "p 与 m 声母不同，pó 意思是老年妇女。"}, {"text": "佛", "is_correct": false, "explanation": "f 与 m 声母不同，fó 意思是佛教中觉悟的人。"}], "explanations": {"魔": "魔：神话传说中害人的鬼怪，比喻邪恶的力量，是本词的意思。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手接触。", "墨": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。", "婆": "p 与 m 声母不同，pó 意思是老年妇女。", "佛": "f 与 m 声母不同，fó 意思是佛教中觉悟的人。"}, "sentence_index": null, "correct_answer": "魔"}, "level_3": {"options": [{"text": "魔", "is_correct": true, "explanation": "魔：比喻心中的邪恶力量，与“和……斗争”搭配。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会与人斗争，与“心中”的内心冲突不符。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵无法与人对抗，不能与“斗争”搭配。"}, {"text": "河流", "is_correct": false, "explanation": "配价：“斗争”的对象应是人或抽象的力量，河流不能作为斗争对象。"}], "explanations": {"魔": "魔：比喻心中的邪恶力量，与“和……斗争”搭配。", "花朵": "语义：花朵不会与人斗争，与“心中”的内心冲突不符。", "云朵": "语义：云朵无法与人对抗，不能与“斗争”搭配。", "河流": "配价：“斗争”的对象应是人或抽象的力量，河流不能作为斗争对象。"}, "sentence_index": 0, "correct_answer": "魔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "读书是人生的魔，我们应该尽量远离它。", "explanation": "这里应该用〈良药〉。魔指害人的邪恶力量，不能用来形容对人有益的读书。"}, {"text": "他是村里的魔，大家都很敬佩他。", "explanation": "这里应该用〈英雄〉。魔指害人的邪恶力量，不能用来赞美人的品德。"}, {"text": "魔是希望的象征，让人看到未来。", "explanation": "这里应该用〈光明〉。魔指邪恶的力量，不能象征希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "魔", "is_correct": true, "explanation": "魔：比喻让人变坏的邪恶力量，是本词的意思。"}, {"text": "抹", "is_correct": false, "explanation": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦拭。"}, {"text": "末", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是最后、末尾。"}, {"text": "伯", "is_correct": false, "explanation": "b 与 m 声母不同，bó 意思是父亲的哥哥。"}], "explanations": {"魔": "魔：比喻让人变坏的邪恶力量，是本词的意思。", "抹": "mǒ（第三声）与 mó（第二声）声调不同，意思是擦拭。", "末": "mò（第四声）与 mó（第二声）声调不同，意思是最后、末尾。", "伯": "b 与 m 声母不同，bó 意思是父亲的哥哥。"}, "sentence_index": null, "correct_answer": "魔"}, "level_3": {"options": [{"text": "魔", "is_correct": true, "explanation": "魔：比喻让人变坏的邪恶力量，与“会让人失去理智”相符。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不会让人失去理智，与“贪婪”的意义不符。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“笑声”不能与“会让人失去理智”搭配。"}, {"text": "石桥", "is_correct": false, "explanation": "语义：石桥是建筑，不能用来比喻心里的恶念。"}], "explanations": {"魔": "魔：比喻让人变坏的邪恶力量，与“会让人失去理智”相符。", "书本": "语义：书本不会让人失去理智，与“贪婪”的意义不符。", "笑声": "搭配：“笑声”不能与“会让人失去理智”搭配。", "石桥": "语义：石桥是建筑，不能用来比喻心里的恶念。"}, "sentence_index": 6, "correct_answer": "魔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这股魔温暖了大地，人们都很高兴。", "explanation": "这里应该用〈春风〉。魔指邪恶的力量，不能用来形容温暖大地的东西。"}, {"text": "魔照亮了黑夜，让大家找到了回家的路。", "explanation": "这里应该用〈太阳〉。魔指邪恶的力量，不能照亮黑夜、指引方向。"}, {"text": "魔救活了生病的孩子，大家都很感激。", "explanation": "这里应该用〈医生〉。魔指害人的力量，不能用来救人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很努力，终于克服了心里的一颗魔。", "corrected_sentence": "他很努力，终于克服了心里的一个魔。", "error_description": "错误：“魔”的量词用了“颗”。“颗”用于圆形的小东西，抽象的“魔”应该用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她心里魔，总想着不劳而获。", "corrected_sentence": "她心里有魔，总想着不劳而获。", "error_description": "错误：“她心里魔”缺少动词“有”，应说“她心里有魔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
