INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很短很短的一段时间。", "primary_collocate": null, "pronunciation": "yí huì", "ipa": "i˧˥ xweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "请你等一会。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想坐一会。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想休息一会。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只看了一会电视，就去睡觉了。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈累了，想躺一会。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面太热，我们在树下站了一会。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先安静一会，再开始写字。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累的话，就在沙发上睡一会吧。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只在这里待了一会，接了个电话就走了。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了一会，又笑了起来。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一会儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "名词：动作持续的很短的一段时间，常放在动词后面，如“等一会”“坐一会”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一会", "is_correct": true, "explanation": "“等一会”表示等待一段很短的时间，符合“请你”的礼貌请求。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“一张”是量词短语，修饰平面的东西，不能作“等”的时段，与“请你等”的语境不符。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“一本”是量词短语，修饰书籍，不能作“等”的时段，与“请你等”的语境不符。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“等”后要接一段时长，“今天”是时间点，不能直接作“等”的时段。"}], "explanations": {"一会": "“等一会”表示等待一段很短的时间，符合“请你”的礼貌请求。", "一张": "搭配：“一张”是量词短语，修饰平面的东西，不能作“等”的时段，与“请你等”的语境不符。", "一本": "搭配：“一本”是量词短语，修饰书籍，不能作“等”的时段，与“请你等”的语境不符。", "今天": "搭配：“等”后要接一段时长，“今天”是时间点，不能直接作“等”的时段。"}, "sentence_index": 0, "correct_answer": "一会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他睡了一会，一觉醒来已经是第二天中午。", "explanation": "这里是“一会”误用为长时段。“一会”只表示很短的一段时间，与“一觉醒来已是第二天”矛盾，应用〈很久〉。"}, {"text": "他坐在门口等了一会，直到第二天才起身。", "explanation": "这里是“一会”误用为长时段。“一会”只表示很短的一段时间，与“直到第二天才起身”矛盾，应用〈很久〉。"}, {"text": "闪电在夜空中一会划过。", "explanation": "这里应该用〈一瞬间〉。“一会”表示持续的一段时间，闪电的划过只是瞬间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一会", "is_correct": true, "explanation": "“安静一会”表示安静很短的一段时间，符合“先……再……”的语境。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“一本”是量词短语，修饰书籍，不能作“安静”后的时段。"}, {"text": "一个会", "is_correct": false, "explanation": "搭配：“安静”后接的是时段，“一个会”是指一场会议的名词短语，不能这样搭配。"}, {"text": "一生", "is_correct": false, "explanation": "语义：时间过长，与“先……再……”的短期安排不符。"}], "explanations": {"一会": "“安静一会”表示安静很短的一段时间，符合“先……再……”的语境。", "一本": "搭配：“一本”是量词短语，修饰书籍，不能作“安静”后的时段。", "一个会": "搭配：“安静”后接的是时段，“一个会”是指一场会议的名词短语，不能这样搭配。", "一生": "语义：时间过长，与“先……再……”的短期安排不符。"}, "sentence_index": 6, "correct_answer": "一会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在门口站了一会，一整天都没挪动。", "explanation": "这里是“一会”误用为长时段。“一会”只表示很短的一段时间，与“一整天都没挪动”矛盾，应用〈很久〉。"}, {"text": "他昨天一会就抄完了一本字典。", "explanation": "这里是“一会”误用为长时段。“一会”只表示很短的一段时间，与“抄完一本字典”矛盾，应用〈很久〉。"}, {"text": "他在国外住了一会，十年后才回国。", "explanation": "这里应该用〈很久〉。“一会”只表示很短的一段时间，与“十年后才回国”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在门口一会，再进去吧。", "corrected_sentence": "我们在门口等一会，再进去吧。", "error_description": "错误：漏掉动词“等”。“一会”作时量补语，必须紧跟在动词之后，应说“等一会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你先在这里坐的一会，我去拿点水。", "corrected_sentence": "你先在这里坐一会，我去拿点水。", "error_description": "错误在于在动词“坐”与时量词语“一会”之间误加了“的”。“一会”作时量补语，直接置于动词之后，不能加“的”，正确为“坐一会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
