INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "短时间；片刻。", "primary_collocate": null, "pronunciation": "yí huì", "ipa": "i˧˥ xweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "你过一会再来。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一会就到。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我一会给你打电话。", "target_word": "一会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨太大了，过一会再走吧。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，饭一会就好了。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先写作业，一会我们去公园。", "target_word": "一会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在太忙，过一会我再回你的信息。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影一会就要开始了，我们快进去吧。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚出去，一会就会回来，请你坐着等。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤还很烫，过一会再喝吧。", "target_word": "一会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一会儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "名词：说话之后不久的片刻，放在动词前，如“过一会再来”“一会就到”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一会", "is_correct": true, "explanation": "“过一会再来”表示过了不久再来，符合说话的语境。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“过”后接的是将来的时间，“昨天”已经过去，不能这样搭配。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”指整个人生，与“过……再来”的短暂安排不符。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”是过去的时间，与“再来”所指的将来不相符。"}], "explanations": {"一会": "“过一会再来”表示过了不久再来，符合说话的语境。", "昨天": "搭配：“过”后接的是将来的时间，“昨天”已经过去，不能这样搭配。", "一辈子": "语义：“一辈子”指整个人生，与“过……再来”的短暂安排不符。", "去年": "语义：“去年”是过去的时间，与“再来”所指的将来不相符。"}, "sentence_index": 0, "correct_answer": "一会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天一会就读完了整部百科全书。", "explanation": "这里应该用〈很久〉。“一会”表示说话之后不久，读完整部百科全书需要很长时间，二者矛盾。"}, {"text": "他明年一会就毕业。", "explanation": "这里应该用〈以后〉。“一会”指很短时间之后，不能用于相隔一年的时间。"}, {"text": "他去年一会就来过我家。", "explanation": "这里应该用〈以前〉。“一会”指说话之后不久的将来，不能指已经过去的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一会", "is_correct": true, "explanation": "“过一会”表示过了不久，符合“现在太忙”的语境。"}, {"text": "一碗", "is_correct": false, "explanation": "搭配：“一碗”是量词短语，修饰饭食，不能作“过”后的时段，与“过……再回”的语境不符。"}, {"text": "上周", "is_correct": false, "explanation": "搭配：“过”后接的应是将来的时间，“上周”已经过去，不能这样搭配。"}, {"text": "上个月", "is_correct": false, "explanation": "语义：“上个月”是过去的时间，与“再回信息”所指的将来不相符。"}], "explanations": {"一会": "“过一会”表示过了不久，符合“现在太忙”的语境。", "一碗": "搭配：“一碗”是量词短语，修饰饭食，不能作“过”后的时段，与“过……再回”的语境不符。", "上周": "搭配：“过”后接的应是将来的时间，“上周”已经过去，不能这样搭配。", "上个月": "语义：“上个月”是过去的时间，与“再回信息”所指的将来不相符。"}, "sentence_index": 6, "correct_answer": "一会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一会就盖好了一座摩天大楼。", "explanation": "这里应该用〈很久〉。“一会就”表示不久之后就完成，盖摩天大楼需要很长时间，二者矛盾。"}, {"text": "他昨天一会就完成了三十年的研究。", "explanation": "这里应该用〈很久〉。“一会就”表示不久之后，与“三十年”这样的长时段矛盾。"}, {"text": "上个月一会他就搬走了。", "explanation": "这里应该用〈不久〉。“一会”指说话之后很短的时间，不能用于“上个月”这样的过去时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你先休息，我的一会叫你。", "corrected_sentence": "你先休息，我一会叫你。", "error_description": "错误在于在主语“我”与状语“一会”之间误加了“的”。“一会”修饰动词时直接置于动词前，不能加“的”，正确为“我一会叫你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我现在在开会，在一会我再找你。", "corrected_sentence": "我现在在开会，过一会我再找你。", "error_description": "错误在于把“过一会”（表示过了不久）误写成了“在一会”。“一会”前应用“过”，“在”不能引出这一时段。正确为“过一会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
