INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中将是军队里很大的官，比将军里最大的小一级。", "primary_collocate": null, "pronunciation": "zhōng jiàng", "ipa": "tʂʊŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那位中将今天来学校看我们。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中将在军队工作了三十年。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将穿着军装走进房间。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷是一名中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将对年轻的士兵说了几句话。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上见过那位中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将坐在最前面，大家都很安静。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们给中将送了一束花。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中将很和气，常和士兵聊天。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将站起来，向大家敬了个礼。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "中將", "label": "繁体"}], "register": "正式", "sense_fingerprint": "军队中军衔为中将的高级军官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中将", "is_correct": true, "explanation": "正确。“那位”指人，“来学校看我们”的主语是军官，中将符合句意。"}, {"text": "花", "is_correct": false, "explanation": "搭配：量词「位」只用于人，不能说「那位花」。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户的量词是「扇」，不能说「那位窗户」。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不会“来学校看我们”，句意不合理。"}], "explanations": {"中将": "正确。“那位”指人，“来学校看我们”的主语是军官，中将符合句意。", "花": "搭配：量词「位」只用于人，不能说「那位花」。", "窗户": "搭配：窗户的量词是「扇」，不能说「那位窗户」。", "老虎": "语义：老虎不会“来学校看我们”，句意不合理。"}, "sentence_index": 0, "correct_answer": "中将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爷爷在比赛中赢得了中将。", "explanation": "中将是军衔，不能当作比赛的奖项来赢得。"}, {"text": "他爷爷叫中将。", "explanation": "中将是军衔，不是人名，不能用作名字。"}, {"text": "他爷爷住在中将。", "explanation": "中将是军衔名词，不是地方名词，不能说“住在中将”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中将", "is_correct": true, "explanation": "正确。“坐在最前面”的主语是有生命的人，中将符合句意。"}, {"text": "座位", "is_correct": false, "explanation": "配价：“坐”要求有生命的施事，座位不能作“坐”的主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会“坐在最前面”，句意荒谬。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯不能坐，“坐在最前面”的说法不成立。"}], "explanations": {"中将": "正确。“坐在最前面”的主语是有生命的人，中将符合句意。", "座位": "配价：“坐”要求有生命的施事，座位不能作“坐”的主语。", "窗户": "语义：窗户不会“坐在最前面”，句意荒谬。", "水杯": "语义：水杯不能坐，“坐在最前面”的说法不成立。"}, "sentence_index": 6, "correct_answer": "中将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天吃了中将。", "explanation": "中将是军衔，指军人，不能当作食物来吃。"}, {"text": "这张桌子是用中将做的。", "explanation": "中将是军衔，指人，不能当作制作桌子的材料。"}, {"text": "我昨天在超市买了一个中将。", "explanation": "中将指军人，是人，不是可以买的物品，不能说“买了一个中将”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只中将是我的邻居。", "corrected_sentence": "那位中将是我的邻居。", "error_description": "量词错误：应说「那位中将」。「只」用于动物，指人的中将要用量词「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爷爷去年才当上一中将。", "corrected_sentence": "他爷爷去年才当上中将。", "error_description": "数量词错误：「中将」前多出数词「一」且缺少量词，应删去「一」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
