INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军衔名，在上将之下、少将之上。", "primary_collocate": null, "pronunciation": "zhōng jiàng", "ipa": "tʂʊŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "中将比少将高一级。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将在上将下面，在少将上面。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的军衔是中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将是军队里的一种军衔。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将再升一级就是中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上将的军衔比中将高。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他五十岁时升为中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他的最高军衔是中将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军衔从低到高，少将、中将、上将。", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中将和少将，哪个军衔更高？", "target_word": "中将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中將", "label": "繁体"}, {"form": "海军中将", "label": "复合"}, {"form": "空军中将", "label": "复合"}], "register": "正式", "sense_fingerprint": "军衔等级名称，高于少将，低于上将", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中将", "is_correct": true, "explanation": "正确。中将是军衔，比少将高一级，句中的“比少将高一级”与之相符。"}, {"text": "中士", "is_correct": false, "explanation": "语义：中士是较低的军衔，低于少将，不能说“比少将高一级”。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“高一级”只用于军衔、等级，不能用于职业名称。"}, {"text": "上校", "is_correct": false, "explanation": "语义：上校的军衔低于少将，与句中“高一级”的说法矛盾。"}], "explanations": {"中将": "正确。中将是军衔，比少将高一级，句中的“比少将高一级”与之相符。", "中士": "语义：中士是较低的军衔，低于少将，不能说“比少将高一级”。", "老师": "搭配：“高一级”只用于军衔、等级，不能用于职业名称。", "上校": "语义：上校的军衔低于少将，与句中“高一级”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "中将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛里拿了中将。", "explanation": "中将是军衔，指人的级别，不能当作比赛的奖项来拿。"}, {"text": "他在公司里当中将，负责财务工作。", "explanation": "中将是军队的军衔，只用于军人，不能用来指公司里的职务。"}, {"text": "他爷爷住在中将。", "explanation": "中将是军衔名词，不是地方名词，不能说“住在中将”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中将", "is_correct": true, "explanation": "正确。“升为”后面接职务或军衔，中将符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不是职务或军衔，不能说“升为学生”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“升为”后接的是职位名称，窗户不是职位，不能搭配。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不是职务，“五十岁时升为老虎”句意荒谬。"}], "explanations": {"中将": "正确。“升为”后面接职务或军衔，中将符合句意。", "学生": "语义：学生不是职务或军衔，不能说“升为学生”。", "窗户": "搭配：“升为”后接的是职位名称，窗户不是职位，不能搭配。", "老虎": "语义：老虎不是职务，“五十岁时升为老虎”句意荒谬。"}, "sentence_index": 6, "correct_answer": "中将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给儿子取名叫中将。", "explanation": "中将是军衔，不是人名，不能用来给孩子取名。"}, {"text": "这件衣服的颜色是中将。", "explanation": "中将是军衔名称，不是颜色，不能用来说衣服的颜色。"}, {"text": "妈妈今天做了中将。", "explanation": "中将是军衔，指军人，不能当作食物来做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔的军衔是中将的。", "corrected_sentence": "我叔叔的军衔是中将。", "error_description": "多余成分：「是中将」后面多了「的」。军衔名「中将」直接作宾语，应删去「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才当上一中将。", "corrected_sentence": "他去年才当上中将。", "error_description": "数量词错误：「中将」前多出数词「一」且缺少量词，应删去「一」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
