INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89453, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "某是说一个人或东西,不说出名字。", "primary_collocate": null, "pronunciation": "mǒu", "ipa": "mou˨˩˦", "syllable_count": 1, "sentences": [{"text": "某公司的经理昨天来了。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，某明星结婚了。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在某个地方见过那个人。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一天，某人给我送来一封信。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某同学没写作业，老师很生气。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在某本书里看过这个故事。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说某医院要搬到新地方去。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某学校的学生拿了第一名。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从某个朋友那里借了钱。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某人偷偷把门关上了。", "target_word": "某", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "某人", "label": "复合"}, {"form": "某些", "label": "复合"}, {"form": "某某", "label": "重叠"}], "register": "书面", "sense_fingerprint": "指某个不点名的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某", "is_correct": true, "explanation": "某表示不说出名字的某个，这句指一家没有点名的公司，只有“某”符合。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能修饰“公司”，“大家公司”不成立。"}, {"text": "哪", "is_correct": false, "explanation": "语义：“哪”用来提问，这句是陈述，不能指不确定的公司。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”也用于提问，与这句“不点名”的意思不符。"}], "explanations": {"某": "某表示不说出名字的某个，这句指一家没有点名的公司，只有“某”符合。", "大家": "搭配：“大家”指人群，不能修饰“公司”，“大家公司”不成立。", "哪": "语义：“哪”用来提问，这句是陈述，不能指不确定的公司。", "什么": "语义：“什么”也用于提问，与这句“不点名”的意思不符。"}, "sentence_index": 0, "correct_answer": "某"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "某人都可以来参加这个活动。", "explanation": "这里应该用〈任何〉。某指不确定的某个人，不能表示“任何人”或“所有人”。"}, {"text": "某个学生都要交作业。", "explanation": "这里应该用〈每〉。某表示不确定的某一个，不能表示每一个。"}, {"text": "老师让那个某同学回答问题。", "explanation": "这里应该用〈那位〉。“某”不能与指示词“那个”同时修饰同一名词；应说“那位同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某", "is_correct": true, "explanation": "某表示不说出名字的某一家，这句指一家没有点名的医院，只有“某”符合。"}, {"text": "它", "is_correct": false, "explanation": "搭配：“它”指事物或动物，不能修饰“医院”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”用来提问，这句是陈述，不能指不确定的医院。"}, {"text": "每", "is_correct": false, "explanation": "语义：“每”指每一家，与这句中“某一家医院”的意思不符。"}], "explanations": {"某": "某表示不说出名字的某一家，这句指一家没有点名的医院，只有“某”符合。", "它": "搭配：“它”指事物或动物，不能修饰“医院”。", "谁": "语义：“谁”用来提问，这句是陈述，不能指不确定的医院。", "每": "语义：“每”指每一家，与这句中“某一家医院”的意思不符。"}, "sentence_index": 6, "correct_answer": "某"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某同学都来了。", "explanation": "这里应该用〈所有〉。某表示不确定的某一个，不能表示全部同学。"}, {"text": "这个问题某个人都没回答出来。", "explanation": "这里应该用〈谁〉。某指不确定的某个人，不能用于“谁都”这种没有例外的说法。"}, {"text": "某个同事都同意了这个计划。", "explanation": "这里应该用〈大家〉。某指不确定的某一个人，不能表示全体成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "某只人昨天给我打了电话。", "corrected_sentence": "某个人昨天给我打了电话。", "error_description": "“某”后面的量词应为“个”，应说“某个人”，不能说“某只人”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "某们同学昨天没来上课。", "corrected_sentence": "某个同学昨天没来上课。", "error_description": "“某”后面不能加“们”，应说“某个同学”，不能说“某们同学”。“某”指不确定的某个人，后面应接量词“个”，而不是复数词尾“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上次", "is_correct": true, "explanation": "上次：指这次之前的那一次，与“下次”构成反义。"}, {"text": "前天", "is_correct": false, "explanation": "前天：指两天前，与“下次”不构成反义关系。"}, {"text": "平时", "is_correct": false, "explanation": "平时：指平常的时候，与“下次”不构成反义关系。"}, {"text": "当年", "is_correct": false, "explanation": "当年：指某个过去的年份，与“下次”不构成反义关系。"}], "correct_answer": "上次", "explanations": {"上次": "上次：指这次之前的那一次，与“下次”构成反义。", "前天": "前天：指两天前，与“下次”不构成反义关系。", "平时": "平时：指平常的时候，与“下次”不构成反义关系。", "当年": "当年：指某个过去的年份，与“下次”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上次", "is_correct": true, "explanation": "上次：指这次之前的那一次，与“下次”构成反义。"}, {"text": "去年", "is_correct": false, "explanation": "去年：指上一年，与“下次”不构成反义关系。"}, {"text": "早上", "is_correct": false, "explanation": "早上：指一天的早晨，与“下次”不构成反义关系。"}, {"text": "夜里", "is_correct": false, "explanation": "夜里：指夜间，与“下次”不构成反义关系。"}], "correct_answer": "上次", "explanations": {"上次": "上次：指这次之前的那一次，与“下次”构成反义。", "去年": "去年：指上一年，与“下次”不构成反义关系。", "早上": "早上：指一天的早晨，与“下次”不构成反义关系。", "夜里": "夜里：指夜间，与“下次”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不是这一次，是后面的那一次。", "primary_collocate": null, "pronunciation": "xià cì", "ipa": "ɕja˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "今天先学到这里，下次继续讲第五课。", "target_word": "下次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛我输了，下次我要赢你。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，我今天有事，下次再去看你。", "target_word": "下次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下次见面的时候，我把照片带给你。", "target_word": "下次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难了，我们下次再讨论。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次你来北京，一定要告诉我。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这次先不买，下次再说。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次我付钱，下次换你付。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这次迟到了，下次不能再迟到。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次出门，别忘了带手机和钥匙。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不是这次而是以后的那一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是过去，与“今天先学到这里”后接着讲的安排矛盾。"}, {"text": "下次", "is_correct": true, "explanation": "下次：指今天之后的那一次，与“继续讲第五课”相接。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指很久以前，与“继续讲”的接续不合。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“继续讲”的对象是内容，“名字”不能作这里的时间状语。"}], "explanations": {"昨天": "语义：“昨天”是过去，与“今天先学到这里”后接着讲的安排矛盾。", "下次": "下次：指今天之后的那一次，与“继续讲第五课”相接。", "从前": "语义：“从前”指很久以前，与“继续讲”的接续不合。", "名字": "搭配：“继续讲”的对象是内容，“名字”不能作这里的时间状语。"}, "sentence_index": 0, "correct_answer": "下次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下次我昨天去了公园。", "explanation": "这里应该用〈昨天〉。下次指之后的那一次，不能用来说已经发生的事情。"}, {"text": "我下次是这所学校的学生。", "explanation": "这里应该用〈现在〉。下次指之后的那一次，不能用来说人目前的身份。"}, {"text": "下次我每天晚上看书。", "explanation": "这里应该用〈经常〉。下次只指下一次，不能用来表示经常性的重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当初", "is_correct": false, "explanation": "语义：“当初”指最初，与“这次先不买”的安排矛盾。"}, {"text": "下次", "is_correct": true, "explanation": "下次：指这次之后的那一次，与“这次先不买”相对应。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不表示时间，无法与“再说”的接续对应。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“再说”后接时间或事情，“餐厅”不能作这里的时间状语。"}], "explanations": {"当初": "语义：“当初”指最初，与“这次先不买”的安排矛盾。", "下次": "下次：指这次之后的那一次，与“这次先不买”相对应。", "水果": "语义：“水果”不表示时间，无法与“再说”的接续对应。", "餐厅": "搭配：“再说”后接时间或事情，“餐厅”不能作这里的时间状语。"}, "sentence_index": 6, "correct_answer": "下次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下次我当时还是个学生。", "explanation": "这里应该用〈当时〉。下次指之后的那一次，不能用来说过去的身份。"}, {"text": "下次这里过去是一片森林。", "explanation": "这里应该用〈过去〉。下次指以后的那一次，不能用来描述过去的情况。"}, {"text": "这座桥下次原来是木头做的。", "explanation": "这里应该用〈原来〉。下次指之后的那一次，不能用来说事物原本的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很下次再见吧。", "corrected_sentence": "我们下次再见吧。", "error_description": "副词错误：程度副词“很”不能修饰时间词“下次”，“很下次”不成立，应去掉“很”，写作“我们下次再见吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下次了我们换个地方吃饭吧。", "corrected_sentence": "下次我们换个地方吃饭吧。", "error_description": "“了”错误：时间词“下次”后不能直接加“了”，“下次了”不成立，应去掉“了”，写作“下次我们换个地方吃饭吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
