INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下一次；紧接着的另一次。", "primary_collocate": null, "pronunciation": "xià cì", "ipa": "ɕja˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这次我先走，下次你先走。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太晚了，我们下次再聊吧。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次考试我一定会认真复习。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次没赶上火车，下次要早点出门。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下次开会的时间还没有定下来。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我这次忘了带伞，下次一定会带。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你上次请客，下次轮到我请你。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说下次来的时候会带着孩子。", "target_word": "下次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很好吃，下次我还想来。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次只买了一本书，下次多买几本。", "target_word": "下次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "紧接当前这一次之后的另一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前年", "is_correct": false, "explanation": "语义：“前年”指两年前，与句中“这次”所指的轮流安排矛盾。"}, {"text": "下次", "is_correct": true, "explanation": "下次：指这次之后的另一次，与句中的“这次”相对应。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不表示时间或次序，无法与“这次”对应。"}, {"text": "时期", "is_correct": false, "explanation": "语义：“时期”指一段时间，不能表示轮流中的下一次。"}], "explanations": {"前年": "语义：“前年”指两年前，与句中“这次”所指的轮流安排矛盾。", "下次": "下次：指这次之后的另一次，与句中的“这次”相对应。", "名字": "语义：“名字”不表示时间或次序，无法与“这次”对应。", "时期": "语义：“时期”指一段时间，不能表示轮流中的下一次。"}, "sentence_index": 0, "correct_answer": "下次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下次我前天看了一场电影。", "explanation": "这里应该用〈前天〉。下次指之后的那一次，不能用来说已经发生的事情。"}, {"text": "我下次在这家公司上班。", "explanation": "这里应该用〈现在〉。下次指之后的那一次，不能用来说目前一段时期的状态。"}, {"text": "下次我每天七点起床。", "explanation": "这里应该用〈经常〉。下次只指下一次，不能用来表示经常性的重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早先", "is_correct": false, "explanation": "语义：“早先”指过去，不能表示“上次请客”之后轮到我的那一次。"}, {"text": "下次", "is_correct": true, "explanation": "下次：指之后的那一次，与“上次请客”形成先后轮换。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不表示时间或次序，无法与“轮到”对应。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“轮到”后接时间或次序，“餐厅”不能作这里的时间状语。"}], "explanations": {"早先": "语义：“早先”指过去，不能表示“上次请客”之后轮到我的那一次。", "下次": "下次：指之后的那一次，与“上次请客”形成先后轮换。", "水果": "语义：“水果”不表示时间或次序，无法与“轮到”对应。", "餐厅": "搭配：“轮到”后接时间或次序，“餐厅”不能作这里的时间状语。"}, "sentence_index": 6, "correct_answer": "下次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下次我当时还是个小学生。", "explanation": "这里应该用〈当时〉。下次指之后的那一次，不能用来说过去的身份。"}, {"text": "这里下次从前是一片森林。", "explanation": "这里应该用〈从前〉。下次指以后的那一次，不能用来描述过去的情况。"}, {"text": "他下次是一名老师。", "explanation": "这里应该用〈以后〉。下次指再次发生的那一次，不能单独用来说人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下次了去爬山吧。", "corrected_sentence": "我们下次去爬山吧。", "error_description": "“了”错误：时间词“下次”后不能直接加“了”，“下次了”不成立，应去掉“了”，写作“我们下次去爬山吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很下次我们去看海吧。", "corrected_sentence": "下次我们去看海吧。", "error_description": "副词错误：程度副词“很”不能修饰时间词“下次”，应去掉“很”，写作“下次我们去看海吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
