INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事迹是一个人做过的、让人记住的好事。", "primary_collocate": null, "pronunciation": "shì jì", "ipa": "ʂʅ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老师的感人事迹让大家很感动。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写了这位医生的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救人的事迹传遍了小城。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都听过这位英雄的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人帮助穷孩子的事迹感动了很多人。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上讲了他的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把爷爷的事迹写下来。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在报道她的先进事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位警察的事迹值得我们学习。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课文里讲了一位老工人的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "先进事迹", "label": "复合"}], "register": "书面", "sense_fingerprint": "某人做过的、让人记住的好事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89457, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。事迹 shìjì（第四声、第四声），指个人或集体做过的、值得称道的事。"}, {"text": "实际", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实际、实在。"}, {"text": "时机", "is_correct": false, "explanation": "shí 与 shì 声调不同，jī 与 jì 声调也不同，意思是合适的机会。"}, {"text": "市集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是集市。"}, {"text": "四季", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是一年的四个季节。"}], "explanations": {"事迹": "正确。事迹 shìjì（第四声、第四声），指个人或集体做过的、值得称道的事。", "实际": "shí（第二声）与 shì（第四声）声调不同，意思是实际、实在。", "时机": "shí 与 shì 声调不同，jī 与 jì 声调也不同，意思是合适的机会。", "市集": "jí（第二声）与 jì（第四声）声调不同，意思是集市。", "四季": "sì 与 shì 声母不同（s 与 sh），意思是一年的四个季节。"}, "sentence_index": null, "correct_answer": "事迹"}, "level_3": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。“老师的感人事迹”指值得称道的事，与“感动”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能“感人”，与“让大家很感动”的语境不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“感人”，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用“感人”修饰。"}], "explanations": {"事迹": "正确。“老师的感人事迹”指值得称道的事，与“感动”相符。", "价格": "语义：价格不能“感人”，与“让大家很感动”的语境不合。", "天气": "语义：天气不能“感人”，句子不通。", "颜色": "搭配：“颜色”不用“感人”修饰。"}, "sentence_index": 0, "correct_answer": "事迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天忙于处理日常事迹。", "explanation": "这里应该用〈事务〉。事迹指个人或集体做过的、值得称道的事，不用来说需要处理的日常事务。"}, {"text": "他一生都在为教育事迹奋斗。", "explanation": "这里应该用〈事业〉。事迹是做过的具体事情，不用于说长期奋斗的事业。"}, {"text": "这起事迹造成了三人受伤。", "explanation": "这里应该用〈事故〉。事迹是值得称道的事，不能用来说造成伤害的事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89457, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。事迹 shìjì，指个人或集体做过的、值得称道的事。"}, {"text": "十级", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jí（第二声）与 jì（第四声）声调也不同，意思是十个等级。"}, {"text": "诗集", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，jí 与 jì 声调也不同，意思是诗歌的集子。"}, {"text": "十几", "is_correct": false, "explanation": "shí 与 shì 声调不同，jǐ（第三声）与 jì（第四声）声调不同，意思是十来个。"}], "explanations": {"事迹": "正确。事迹 shìjì，指个人或集体做过的、值得称道的事。", "十级": "shí（第二声）与 shì（第四声）声调不同，jí（第二声）与 jì（第四声）声调也不同，意思是十个等级。", "诗集": "shī（第一声）与 shì（第四声）声调不同，jí 与 jì 声调也不同，意思是诗歌的集子。", "十几": "shí 与 shì 声调不同，jǐ（第三声）与 jì（第四声）声调不同，意思是十来个。"}, "sentence_index": null, "correct_answer": "事迹"}, "level_3": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。“我想把爷爷的事迹写下来”指值得记录的经历，与句意相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是人的经历，写不成值得记录的内容。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”不用来指人的经历，不与“写下来”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能作为人的经历写下来，句子不通。"}], "explanations": {"事迹": "正确。“我想把爷爷的事迹写下来”指值得记录的经历，与句意相符。", "温度": "语义：温度不是人的经历，写不成值得记录的内容。", "亮度": "搭配：“亮度”不用来指人的经历，不与“写下来”搭配。", "味道": "语义：味道不能作为人的经历写下来，句子不通。"}, "sentence_index": 6, "correct_answer": "事迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天有一件小事迹要去银行办。", "explanation": "这里应该用〈事情〉。事迹指做过的、让人记住的好事，不用来说要去办的日常小事。"}, {"text": "天上有乌云，是要下雨的事迹。", "explanation": "这里应该用〈迹象〉。事迹是人做过的好事，不能表示事情将要发生的征兆。"}, {"text": "地上还留着轮胎的事迹。", "explanation": "这里应该用〈痕迹〉。事迹指人做过的好事，不能指物体留下的印子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影讲了一位老兵的感人地事迹。", "corrected_sentence": "这部电影讲了一位老兵的感人事迹。", "error_description": "“感人”修饰名词“事迹”时后面不加“地”，“地”用于修饰动词或形容词作状语。这里应直接说“感人事迹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想把父亲的一本事迹拍成电影。", "corrected_sentence": "他想把父亲的一段事迹拍成电影。", "error_description": "“事迹”前的数量词应用“段”，“本”用于书籍、簿册，不能用来数事迹。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
