INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人或集体做过的重要的、值得称道的事情。", "primary_collocate": null, "pronunciation": "shì jì", "ipa": "ʂʅ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这个消防队的英勇事迹上了新闻。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里办了展览，介绍老书记的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队的奋斗事迹鼓舞了年轻人。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里展出着许多战士的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会表扬了先进集体的事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的感人事迹我们都听说过。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家的重要事迹写进了书里。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把优秀毕业生的事迹贴在墙上。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者团队的事迹感动了全城人。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的历史上有不少英雄事迹。", "target_word": "事迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "英雄事迹", "label": "复合"}], "register": "书面", "sense_fingerprint": "个人或集体做过的重要的、值得称道的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。事迹 shìjì，指个人或集体做过的、重要的、值得称道的事。"}, {"text": "实际", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实际、实在。"}, {"text": "诗集", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，jí 与 jì 声调也不同，意思是诗歌的集子。"}, {"text": "四季", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是一年的四个季节。"}], "explanations": {"事迹": "正确。事迹 shìjì，指个人或集体做过的、重要的、值得称道的事。", "实际": "shí（第二声）与 shì（第四声）声调不同，意思是实际、实在。", "诗集": "shī（第一声）与 shì（第四声）声调不同，jí 与 jì 声调也不同，意思是诗歌的集子。", "四季": "sì 与 shì 声母不同（s 与 sh），意思是一年的四个季节。"}, "sentence_index": null, "correct_answer": "事迹"}, "level_3": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。“英勇事迹”指做过的值得称道的事，能够上新闻。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“英勇脚步”不成词，脚步不能上新闻，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用“英勇”修饰。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温不能“英勇”，也不能作为新闻内容，句子不通。"}], "explanations": {"事迹": "正确。“英勇事迹”指做过的值得称道的事，能够上新闻。", "脚步": "语义：“英勇脚步”不成词，脚步不能上新闻，句子不通。", "颜色": "搭配：“颜色”不用“英勇”修饰。", "气温": "语义：气温不能“英勇”，也不能作为新闻内容，句子不通。"}, "sentence_index": 0, "correct_answer": "事迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次体检的事迹让他很担心。", "explanation": "这里应该用〈结果〉。事迹指做过的、值得称道的事，不能用来说体检的结果。"}, {"text": "他忙着打理家里的琐碎事迹。", "explanation": "这里应该用〈事务〉。事迹指做过的、值得称道的事，不用来说家里的琐碎事务。"}, {"text": "那场事迹让大家很难过。", "explanation": "这里应该用〈事故〉。事迹用来称赞做过的好事，不能用来说让人难过的事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89458, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。事迹 shìjì，指个人或集体做过的、重要的、值得称道的事。"}, {"text": "时机", "is_correct": false, "explanation": "shí 与 shì 声调不同，jī 与 jì 声调也不同，意思是合适的机会。"}, {"text": "十级", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jí（第二声）与 jì（第四声）声调也不同，意思是十个等级。"}, {"text": "市集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是集市。"}], "explanations": {"事迹": "正确。事迹 shìjì，指个人或集体做过的、重要的、值得称道的事。", "时机": "shí 与 shì 声调不同，jī 与 jì 声调也不同，意思是合适的机会。", "十级": "shí（第二声）与 shì（第四声）声调不同，jí（第二声）与 jì（第四声）声调也不同，意思是十个等级。", "市集": "jí（第二声）与 jì（第四声）声调不同，意思是集市。"}, "sentence_index": null, "correct_answer": "事迹"}, "level_3": {"options": [{"text": "事迹", "is_correct": true, "explanation": "正确。“这位科学家的重要事迹”指做过的重要之事，能写进书里。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是科学家的重要事迹，写进书里句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不用“重要”修饰，也不是能写进书里的内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于科学家的事迹，句子不通。"}], "explanations": {"事迹": "正确。“这位科学家的重要事迹”指做过的重要之事，能写进书里。", "价格": "语义：价格不是科学家的重要事迹，写进书里句意不通。", "体重": "搭配：“体重”不用“重要”修饰，也不是能写进书里的内容。", "天气": "语义：天气不属于科学家的事迹，句子不通。"}, "sentence_index": 6, "correct_answer": "事迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的历史上留下了不少古老的事迹，比如城墙和老桥。", "explanation": "这里应该用〈古迹〉。城墙、老桥是留下来的建筑，事迹指人做过的值得称道的事。"}, {"text": "警察在现场发现了小偷的事迹。", "explanation": "这里应该用〈踪迹〉。事迹指值得称道的事，不能指坏人留下的线索。"}, {"text": "他偷东西的事迹被大家知道了。", "explanation": "这里应该用〈事情〉。事迹只用于值得称道的事，不能说做坏事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章介绍得他的先进事迹。", "corrected_sentence": "这篇文章介绍了他的先进事迹。", "error_description": "“介绍”后表示动作完成的助词应用“了”，应说“介绍了”。写成“得”，补语标记不能直接接在动词后带宾语，结构不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老师的事迹了值得大家学习。", "corrected_sentence": "那位老师的事迹值得大家学习。", "error_description": "“了”不能插在定语“的事迹”与谓语“值得”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
