INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特点是一个东西跟别的不一样的地方。", "primary_collocate": null, "pronunciation": "tè diǎn", "ipa": "tʰɤ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种手机的最大特点是电池耐用。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的特点是夏天很热。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国菜有什么特点?", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的特点是图片特别多。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种茶有自己的特点,味道很香。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方房子的特点是窗户很大。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你说说这辆车的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的特点是菜便宜,量也大。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山的特点是树多,水也多。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几种水果各有各的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物与别的不同的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特点", "is_correct": true, "explanation": "特点：与别的不同之处，“最大特点”指最突出的不同之处，句意通顺。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”多用于食物、气味，不能说手机的最大味道。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：“价钱”指价格，与后半句“电池耐用”说的性能不是同一类事物。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”属于外观，与后半句“电池耐用”讲的性能不属于同一类。"}], "explanations": {"特点": "特点：与别的不同之处，“最大特点”指最突出的不同之处，句意通顺。", "味道": "搭配：“味道”多用于食物、气味，不能说手机的最大味道。", "价钱": "语义：“价钱”指价格，与后半句“电池耐用”说的性能不是同一类事物。", "颜色": "语义：“颜色”属于外观，与后半句“电池耐用”讲的性能不属于同一类。"}, "sentence_index": 0, "correct_answer": "特点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的特点菜是烤鸭，很有名。", "explanation": "这里应该用〈特色〉。“特点”指人或事物特别的地方，“特色菜”才是固定说法，不能说“特点菜”。"}, {"text": "这座城市的特点小吃很多，大家都爱吃。", "explanation": "这里应该用〈特色〉。“特色小吃”是固定说法，“特点小吃”不能这样说。"}, {"text": "这个景区的特点产品卖得很好。", "explanation": "这里应该用〈特色〉。“特色产品”是固定说法，不能说“特点产品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特点", "is_correct": true, "explanation": "特点：车与众不同的地方，句意通顺。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指一个人受教育的经历，车不能有学历，句子问的是车的特点。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于饮食，不能说车的口味。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：“籍贯”指人的祖籍，车不能有籍贯，与句子的语境不合。"}], "explanations": {"特点": "特点：车与众不同的地方，句意通顺。", "学历": "语义：“学历”指一个人受教育的经历，车不能有学历，句子问的是车的特点。", "口味": "搭配：“口味”用于饮食，不能说车的口味。", "籍贯": "语义：“籍贯”指人的祖籍，车不能有籍贯，与句子的语境不合。"}, "sentence_index": 6, "correct_answer": "特点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服上有一个很大的特点，是一块红色的污渍。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，衣服上的脏点要说污点。"}, {"text": "白纸的中间有一个明显的特点，是墨水滴的。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，纸上的墨点要说污点。"}, {"text": "镜子上有一个小特点，是手印，擦一擦就没了。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，镜子上的手印要说污点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园有一只特点，就是树很多。", "corrected_sentence": "这座公园有一个特点，就是树很多。", "error_description": "量词错误。“特点”应用量词“个”，说“一个特点”；不能用“只”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市有自己得特点。", "corrected_sentence": "这座城市有自己的特点。", "error_description": "助词错误。修饰名词“特点”要用“的”，不能用“得”。“得”用于动词或形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
