INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或事物特有的地方。", "primary_collocate": null, "pronunciation": "tè diǎn", "ipa": "tʰɤ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的特点是说话很慢,但是很认真。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟有一个特点,就是爱笑。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她最大的特点是做事特别细心。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师很了解每个学生的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子有爱玩儿的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人有爱学新东西的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位演员的特点是声音很特别。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要找到自己的特点,再选工作。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他个子高,爱运动,这是他的特点。", "target_word": "特点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或事物特有的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特点", "is_correct": true, "explanation": "特点：人或事物特有的地方，与“每个人都有自己的”搭配，句意通顺。"}, {"text": "事故", "is_correct": false, "explanation": "语义：“事故”指意外的伤害或损失，不是人人都有的个人特征，与“自己的”搭配不通。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：“车祸”是交通意外，说不上是每个人自己特有的地方。"}, {"text": "油量", "is_correct": false, "explanation": "搭配：“油量”指车辆或容器中的油，不能说人的油量。"}], "explanations": {"特点": "特点：人或事物特有的地方，与“每个人都有自己的”搭配，句意通顺。", "事故": "语义：“事故”指意外的伤害或损失，不是人人都有的个人特征，与“自己的”搭配不通。", "车祸": "语义：“车祸”是交通意外，说不上是每个人自己特有的地方。", "油量": "搭配：“油量”指车辆或容器中的油，不能说人的油量。"}, "sentence_index": 0, "correct_answer": "特点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座古镇的特点建筑很有名。", "explanation": "这里应该用〈特色〉。“特色建筑”是固定说法，“特点建筑”不能这样说。"}, {"text": "这家酒店的特点服务很周到。", "explanation": "这里应该用〈特色〉。“特色服务”是固定说法，不能说“特点服务”。"}, {"text": "这个民族的特点服饰很漂亮。", "explanation": "这里应该用〈特色〉。“特色服饰”是固定说法，不能说“特点服饰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特点", "is_correct": true, "explanation": "特点：人特有的地方，与“爱学新东西的”搭配，句意通顺。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指居住或所在的位置，不是人的性格或爱好，与句子语境不合。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能作为“爱学新东西”这类特点。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”只说吃饭的多少，不能与“爱学新东西”这类性格、爱好搭配。"}], "explanations": {"特点": "特点：人特有的地方，与“爱学新东西的”搭配，句意通顺。", "地址": "语义：“地址”指居住或所在的位置，不是人的性格或爱好，与句子语境不合。", "体温": "语义：“体温”指身体的温度，不能作为“爱学新东西”这类特点。", "饭量": "搭配：“饭量”只说吃饭的多少，不能与“爱学新东西”这类性格、爱好搭配。"}, "sentence_index": 6, "correct_answer": "特点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的衬衫上有一个很大的特点，是一块油渍。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，衬衫上的油渍要说污点。"}, {"text": "墙上有一个明显的特点，是蚊子留下的血点。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，墙上的血点要说污点。"}, {"text": "桌布上有一个小特点，是一滴红酒。", "explanation": "这里应该用〈污点〉。“特点”指人或事物特别的地方，桌布上的酒渍要说污点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只明显的特点，就是爱笑。", "corrected_sentence": "他有一个明显的特点，就是爱笑。", "error_description": "量词错误。“特点”应用量词“个”，说“一个特点”；不能用“只”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有爱帮助别人得特点。", "corrected_sentence": "她有爱帮助别人的特点。", "error_description": "助词错误。修饰名词“特点”要用“的”，不能用“得”。“得”用于动词或形容词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
