INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89463, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "住院是生病了，住在医院里治病。", "primary_collocate": null, "pronunciation": "zhù yuàn", "ipa": "ʈʂu˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶生病了，要去医院住院。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候因为发烧住院一个星期。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病不太重，不用住院。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸胃不舒服，下个星期要住院检查。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈住院的时候，我每天都去医院看她。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿摔断了，医生让他马上住院。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住院的那几天，朋友们常常去医院看他。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院没有空床，病人现在还不能住院。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友吃坏了肚子，昨天晚上住院了。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住院以后，每天都有护士来量体温。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "住了院", "label": "体标：了（离合）"}, {"form": "住过院", "label": "体标：过（离合）"}, {"form": "住了三天院", "label": "离合形式"}, {"form": "住院费", "label": "复合词"}, {"form": "住院部", "label": "复合词"}], "register": "口语", "sense_fingerprint": "住院：生病后住在医院里治病（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住院", "is_correct": true, "explanation": "正确。住院指病人住在医院里接受治疗，与“奶奶生病了，要去医院”相符。"}, {"text": "出院", "is_correct": false, "explanation": "语义：出院是病人离开医院回家，与“要去医院”的方向相反，句子不通。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：“上班”指去单位工作，不用来表示生病后去医院就医。"}, {"text": "散步", "is_correct": false, "explanation": "语义：生病的奶奶去医院不是为了散步，与“生病了”的语境矛盾。"}], "explanations": {"住院": "正确。住院指病人住在医院里接受治疗，与“奶奶生病了，要去医院”相符。", "出院": "语义：出院是病人离开医院回家，与“要去医院”的方向相反，句子不通。", "上班": "搭配：“上班”指去单位工作，不用来表示生病后去医院就医。", "散步": "语义：生病的奶奶去医院不是为了散步，与“生病了”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "住院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在酒店住院了三天，玩得很开心。", "explanation": "这里应该用〈住宿〉。住院指病人住在医院接受治疗，在酒店过夜要说住宿。"}, {"text": "他在学校住院，每个周末才回家。", "explanation": "这里应该用〈寄宿〉。住院只指在医院治疗，住在学校宿舍要说寄宿。"}, {"text": "我出差的时候，在朋友家住院了一晚。", "explanation": "这里应该用〈借宿〉。住院指在医院接受治疗，暂住在朋友家过夜要说借宿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住院", "is_correct": true, "explanation": "正确。住院指病人住在医院里，句子说的是他住院期间的那几天。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”是及物动词，“送的那几天”缺少宾语，不成句。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：逛街是外出购物，与“朋友们常常去医院看他”所描述的住院语境相矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：“忘记”是及物动词，“忘记的那几天”缺少宾语，不成句。"}], "explanations": {"住院": "正确。住院指病人住在医院里，句子说的是他住院期间的那几天。", "送": "配价：“送”是及物动词，“送的那几天”缺少宾语，不成句。", "逛街": "语义：逛街是外出购物，与“朋友们常常去医院看他”所描述的住院语境相矛盾。", "忘记": "配价：“忘记”是及物动词，“忘记的那几天”缺少宾语，不成句。"}, "sentence_index": 6, "correct_answer": "住院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在医院住院陪奶奶，晚上才回家。", "explanation": "这里不能用〈住院〉。住院指病人本人在医院接受治疗，家人在医院陪护照顾不能说住院。"}, {"text": "我们全家去海边玩，在民宿住院了两晚。", "explanation": "这里应该用〈住宿〉。住院指病人在医院接受治疗，在民宿过夜要说住宿。"}, {"text": "这次出差，我在同学家住院了一个星期。", "explanation": "这里应该用〈借住〉。住院指病人在医院接受治疗，暂住在同学家要说借住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下个月要住院医院做手术。", "corrected_sentence": "他下个月要住院做手术。", "error_description": "错误在于「住院」后面又接了宾语「医院」。「住院」是离合词，不能直接带宾语。正确说法是「他下个月要住院做手术」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他住院过，知道那里的护士很负责。", "corrected_sentence": "他住过院，知道那里的护士很负责。", "error_description": "错误在于「过」放在了「住院」后面。「住院」是离合词，「过」应插在「住」和「院」之间，写作「住过院」。正确说法是「他住过院」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
