INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "病人入医院接受治疗并住下。", "primary_collocate": null, "pronunciation": "zhù yuàn", "ipa": "ʈʂu˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "病人住院后，医生马上开始治疗。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人住院后，护士带他去了病房。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位病人需要住院，接受一个月的治疗。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为心脏病住院，医生每天给他检查。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人住院期间，家属可以在规定时间探望。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议他住院观察几天，再决定是否手术。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病情严重的人必须马上住院治疗。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住院后，医院给他安排了一个单人病房。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没有床位，这位病人不能当天住院。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹昨天做了手术，要住院一个星期。", "target_word": "住院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "住了院", "label": "体标：了（离合）"}, {"form": "住过院", "label": "体标：过（离合）"}, {"form": "住了三天院", "label": "离合形式"}, {"form": "住院费", "label": "复合词"}, {"form": "住院部", "label": "复合词"}], "register": "书面", "sense_fingerprint": "住院：病人入院接受治疗并住下（正式说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住院", "is_correct": true, "explanation": "正确。住院指病人入医院接受治疗并住下，与“病人住院后，医生马上开始治疗”相符。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：病人逃跑后，医生就不可能马上为他治疗，与句子的语境矛盾。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：“上班”指去单位工作，不用来描述病人的就医。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业指完成学业，与病人接受治疗的语境无关。"}], "explanations": {"住院": "正确。住院指病人入医院接受治疗并住下，与“病人住院后，医生马上开始治疗”相符。", "逃跑": "语义：病人逃跑后，医生就不可能马上为他治疗，与句子的语境矛盾。", "上班": "搭配：“上班”指去单位工作，不用来描述病人的就医。", "毕业": "语义：毕业指完成学业，与病人接受治疗的语境无关。"}, "sentence_index": 0, "correct_answer": "住院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站附近住院了一晚，第二天才出发。", "explanation": "这里应该用〈落脚〉。住院指病人在医院接受治疗，临时歇脚过夜要说落脚。"}, {"text": "我们在山上住院了一晚，第二天才下山。", "explanation": "这里应该用〈住宿〉。住院指在医院接受治疗，在山上过夜要说住宿。"}, {"text": "女儿在外地住院读书，寒假才回家。", "explanation": "这里应该用〈寄宿〉。住院指病人在医院治疗，在外地上学住在学校要说寄宿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住院", "is_correct": true, "explanation": "正确。住院指病人入医院治疗并住下，与“病情严重，必须马上治疗”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：病情严重的人不能靠游泳来治疗，与句子的语境矛盾。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：病情严重的人不能靠跳舞治疗，与“必须马上……治疗”的语境矛盾。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：逛街不是治疗的方式，与“病情严重”的语境矛盾。"}], "explanations": {"住院": "正确。住院指病人入医院治疗并住下，与“病情严重，必须马上治疗”相符。", "游泳": "语义：病情严重的人不能靠游泳来治疗，与句子的语境矛盾。", "跳舞": "语义：病情严重的人不能靠跳舞治疗，与“必须马上……治疗”的语境矛盾。", "逛街": "语义：逛街不是治疗的方式，与“病情严重”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "住院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这次回老家，在亲戚家住院了几天。", "explanation": "这里应该用〈住宿〉。住院指病人在医院接受治疗，在亲戚家过夜要说住宿。"}, {"text": "学生们在学校宿舍住院，每天晚上都要查寝。", "explanation": "这里应该用〈寄宿〉。住院指病人在医院接受治疗，住在学校宿舍要说寄宿。"}, {"text": "我在火车上住院了一整夜，腰特别疼。", "explanation": "这里应该用〈睡〉。住院指病人在医院接受治疗，在火车上睡觉不能用住院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她住院过，知道医生的工作很辛苦。", "corrected_sentence": "她住过院，知道医生的工作很辛苦。", "error_description": "错误在于「过」放在了「住院」后面。「住院」是离合词，「过」应插在「住」和「院」之间，写作「住过院」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下周要这家医院住院。", "corrected_sentence": "他下周要在这家医院住院。", "error_description": "错误在于漏掉了介词「在」。「住院」是不及物的离合词，表示地点要用「在＋地点＋住院」，应写作「在这家医院住院」，不能省略「在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
