INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科是分出来的一类,比如学校里的一门课。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "学校里，你最喜欢哪一科？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学是我学得最好的一科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一科的老师很严，作业也很多。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每一科的成绩都不错。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试有四科，我只通过了三科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语是我最怕的一科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考两科，我今晚得复习。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一科要考的内容很多，你要早点儿开始复习。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语文这一科，我每天都花一个小时学。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一科的作业最多？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科目", "label": "复合"}, {"form": "各科", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校里分出来的一门学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e68a7552-e561-4b72-8b96-81b1448aa4e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89465, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指学校里分出的一门学科。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是可以。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}], "explanations": {"科": "正确：本词，指学校里分出的一门学科。", "渴": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。", "可": "kě（第三声）与 kē（第一声）声调不同，意思是可以。", "咳": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。", "客": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指学校里的一门学科，与“最喜欢”搭配。"}, {"text": "声", "is_correct": false, "explanation": "语义：“哪一声”指一次声音，与学校里的学科不符。"}, {"text": "口", "is_correct": false, "explanation": "语义：“哪一口”指吃或咬的一次量，与问学科的意思不符。"}, {"text": "滴", "is_correct": false, "explanation": "语义：“哪一滴”指一滴液体，无法用来说喜欢的学科类别。"}], "explanations": {"科": "正确：指学校里的一门学科，与“最喜欢”搭配。", "声": "语义：“哪一声”指一次声音，与学校里的学科不符。", "口": "语义：“哪一口”指吃或咬的一次量，与问学科的意思不符。", "滴": "语义：“哪一滴”指一滴液体，无法用来说喜欢的学科类别。"}, "sentence_index": 0, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都上两节科，很辛苦。", "explanation": "这里应该用〈课〉。“科”指学科类别，不指一节一节的课，“上两节”要说“课”。"}, {"text": "他每天晚上都在做科，很辛苦。", "explanation": "这里应该用〈功课〉。“做功课”指做作业，“科”指学科类别，不能说“做科”。"}, {"text": "他每天都花很多时间背科，考试时没有背下来。", "explanation": "这里应该用〈书〉。“背书”指背诵课文，“科”指学科类别，不能用来背。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89465, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指学校里分出的一门学科。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。"}, {"text": "壳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是壳。"}, {"text": "刻", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是刻。"}, {"text": "克", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}], "explanations": {"科": "正确：本词，指学校里分出的一门学科。", "渴": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。", "壳": "ké（第二声）与 kē（第一声）声调不同，意思是壳。", "刻": "kè（第四声）与 kē（第一声）声调不同，意思是刻。", "克": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指学科，“考两科”说的是两门学科的考试。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不能直接用数词计数，“考两书”不通；考试按科目算，应说“考两科”。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是餐具，与考试无关，句子讲不通。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是容器，与考试无关，句子讲不通。"}], "explanations": {"科": "正确：指学科，“考两科”说的是两门学科的考试。", "书": "语义：“书”不能直接用数词计数，“考两书”不通；考试按科目算，应说“考两科”。", "碗": "语义：“碗”是餐具，与考试无关，句子讲不通。", "瓶": "语义：“瓶”是容器，与考试无关，句子讲不通。"}, "sentence_index": 6, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午还要上一节科，老师讲得很快。", "explanation": "这里应该用〈课〉。“上一节”指上课，“科”不指一节课。"}, {"text": "我把科放在书包里，忘记带到学校来了。", "explanation": "这里应该用〈课本〉。“科”指学科类别，是抽象的分类，不能放进书包，应说课本。"}, {"text": "他每天在写科，写到半夜才睡。", "explanation": "这里应该用〈作业〉。“写作业”指完成书面作业，“科”指学科类别，不能说“写科”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每一本科的作业都写完了。", "corrected_sentence": "她每一科的作业都写完了。", "error_description": "量词错误：“科”本身可直接计数，“每一科”中间不能加“本”（“本”用于书）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下学期要考三只科，我得早点儿准备。", "corrected_sentence": "下学期要考三科，我得早点儿准备。", "error_description": "量词错误：“科”计数时不用“只”（“只”用于动物或单个物品），应说“三科”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
