INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医院、机关等单位按业务性质划分出的科室。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "孩子发烧了，应该挂哪个科的号？", "target_word": "科", "complexity_tier": "T3", "furigana": "hái zi fā shāo le, yīng gāi guà nǎ ge kē de hào?", "sentence_source": "generated"}, {"text": "这家医院有十几个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院的哪个科工作？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你的病要去另一个科看。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所医院分很多科，看病前要先弄清楚该看哪个科。", "target_word": "科", "complexity_tier": "T3", "furigana": "zhè suǒ yī yuàn fēn hěn duō kē, kàn bìng qián yào xiān nòng qīng chu gāi kàn nǎ ge kē.", "sentence_source": "generated"}, {"text": "护士问我要看哪个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院分了很多科，每一科都有自己的护士。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的哪一科最有名？", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个科都有一位负责人。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚从那个科调到这个科。", "target_word": "科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科室", "label": "复合"}], "register": "中性", "sense_fingerprint": "医院、单位等按业务分出的科室类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e68a7552-e561-4b72-8b96-81b1448aa4e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指医院、单位等按业务分出的科室。"}, {"text": "渴", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。"}, {"text": "壳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是壳。"}, {"text": "刻", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是刻。"}, {"text": "克", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}], "explanations": {"科": "正确：本词，指医院、单位等按业务分出的科室。", "渴": "kě（第三声）与 kē（第一声）声调不同，意思是口渴。", "壳": "ké（第二声）与 kē（第一声）声调不同，意思是壳。", "刻": "kè（第四声）与 kē（第一声）声调不同，意思是刻。", "克": "kè（第四声）与 kē（第一声）声调不同，意思是克（重量单位）。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指医院里按业务分出的科室，“挂……的号”说的就是挂哪个科。"}, {"text": "班", "is_correct": false, "explanation": "语义：“班”指学生的班级，与医院挂号的科室不符。"}, {"text": "系", "is_correct": false, "explanation": "语义：“系”是大学里的院系，医院挂号不用“系”。"}, {"text": "部", "is_correct": false, "explanation": "搭配：医院挂号一般说“挂哪个科的号”，不说“挂哪个部的号”。"}], "explanations": {"科": "正确：指医院里按业务分出的科室，“挂……的号”说的就是挂哪个科。", "班": "语义：“班”指学生的班级，与医院挂号的科室不符。", "系": "语义：“系”是大学里的院系，医院挂号不用“系”。", "部": "搭配：医院挂号一般说“挂哪个科的号”，不说“挂哪个部的号”。"}, "sentence_index": 0, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋科很高，有十几层。", "explanation": "这里应该用〈楼〉。“科”指科室，是机构，不是建筑物，应说“楼”。"}, {"text": "我把这个科装进书包，带回了家。", "explanation": "这里应该用〈课本〉。“科”指科室，是机构，不能装进书包，应说“课本”。"}, {"text": "他在医院里当了十年的科，每天给病人看病。", "explanation": "这里应该用〈医生〉。“科”指科室，是机构，不能说“当科”，当医生才是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：本词，指医院、单位等按业务分出的科室。"}, {"text": "课", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是课程。"}, {"text": "可", "is_correct": false, "explanation": "kě（第三声）与 kē（第一声）声调不同，意思是可以。"}, {"text": "咳", "is_correct": false, "explanation": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}], "explanations": {"科": "正确：本词，指医院、单位等按业务分出的科室。", "课": "kè（第四声）与 kē（第一声）声调不同，意思是课程。", "可": "kě（第三声）与 kē（第一声）声调不同，意思是可以。", "咳": "ké（第二声）与 kē（第一声）声调不同，意思是咳嗽。", "客": "kè（第四声）与 kē（第一声）声调不同，意思是客人。"}, "sentence_index": null, "correct_answer": "科"}, "level_3": {"options": [{"text": "科", "is_correct": true, "explanation": "正确：指医院按业务分出的科室，“分了很多科”就是分出许多科室。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“碗”是餐具，医院不能“分了很多碗”，也不会有自己的护士。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是容器，与医院分出的部门无关。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”用于细长的东西，不能指医院的部门。"}], "explanations": {"科": "正确：指医院按业务分出的科室，“分了很多科”就是分出许多科室。", "碗": "语义：“碗”是餐具，医院不能“分了很多碗”，也不会有自己的护士。", "瓶": "语义：“瓶”是容器，与医院分出的部门无关。", "条": "语义：“条”用于细长的东西，不能指医院的部门。"}, "sentence_index": 6, "correct_answer": "科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午还要上一节科，老师讲得很快。", "explanation": "这里应该用〈课〉。“上一节”指上课，科室不能用来说上课。"}, {"text": "他每天早上都去超市买科，回家做饭。", "explanation": "这里应该用〈菜〉。“科”指科室或学科类别，不能去超市买，应说“买菜”。"}, {"text": "这家医院新开了一科，专门给病人卖冰淇淋。", "explanation": "这里应该用〈小卖部〉。“科”指科室，是医疗或行政部门，卖东西的地方应说小卖部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院有三只科。", "corrected_sentence": "这家医院有三个科。", "error_description": "量词错误：“科”是科室，应用量词“个”，不能用“只”（“只”不用于科室）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司各科们都有一位负责人。", "corrected_sentence": "公司各科都有一位负责人。", "error_description": "多加“们”：“各科”本身已表示全部，后面不能再加“们”，应说“各科都有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60deaa04-5064-40ea-859c-ee8049642a94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确。“劣质”与“优质”是反义词，指质量低劣。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指场面喧闹，与质量无关，不是“优质”的反义词。"}, {"text": "凉快", "is_correct": false, "explanation": "“凉快”指温度适宜，与质量无关，不是“优质”的反义词。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”指范围广大，与质量无关，不是“优质”的反义词。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确。“劣质”与“优质”是反义词，指质量低劣。", "热闹": "“热闹”指场面喧闹，与质量无关，不是“优质”的反义词。", "凉快": "“凉快”指温度适宜，与质量无关，不是“优质”的反义词。", "辽阔": "“辽阔”指范围广大，与质量无关，不是“优质”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确。“劣质”与“优质”是反义词，指质量低劣。"}, {"text": "忙碌", "is_correct": false, "explanation": "“忙碌”指事情多、不停地工作，与质量无关，不是“优质”的反义词。"}, {"text": "清淡", "is_correct": false, "explanation": "“清淡”指味道不浓或颜色素雅，与质量好坏无关，不是“优质”的反义词。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”指距离很远，与质量无关，不是“优质”的反义词。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确。“劣质”与“优质”是反义词，指质量低劣。", "忙碌": "“忙碌”指事情多、不停地工作，与质量无关，不是“优质”的反义词。", "清淡": "“清淡”指味道不浓或颜色素雅，与质量好坏无关，不是“优质”的反义词。", "遥远": "“遥远”指距离很远，与质量无关，不是“优质”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常好，质量很高。", "primary_collocate": null, "pronunciation": "yōu zhì", "ipa": "joʊ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家酒店的服务非常优质，客人都很满意。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们提供优质的教育，学生进步很快。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想为客户提供优质服务。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校有优质的老师和先进的教室。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在这里能得到优质的教育资源。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好医院的优质医疗让病人放心。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的食材优质，菜做得也好吃。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站每天发优质内容，读者越来越多。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用优质服务留住了老客户。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院提供优质护理，病人住得很放心。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优质服务", "label": "复合"}, {"form": "优质教育", "label": "复合"}], "register": "中性", "sense_fingerprint": "优质：服务、教育等水平很高，非常好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：非常好，质量很高。"}, {"text": "优势", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是有利的条件、长处。"}, {"text": "有志", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，意思是有志向、有抱负。"}, {"text": "油纸", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，zhǐ（第三声）与 zhì（第四声）声调也不同，意思是涂了油的纸。"}], "explanations": {"优质": "正确答案。优质：非常好，质量很高。", "优势": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是有利的条件、长处。", "有志": "yǒu（第三声）与 yōu（第一声）声调不同，意思是有志向、有抱负。", "油纸": "yóu（第二声）与 yōu（第一声）声调不同，zhǐ（第三声）与 zhì（第四声）声调也不同，意思是涂了油的纸。"}, "sentence_index": null, "correct_answer": "优质"}, "level_3": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：非常好，与“客人都很满意”相符。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”指质量低，与“客人都很满意”矛盾。"}, {"text": "慢", "is_correct": false, "explanation": "语义：服务太慢会让客人不满意，与“客人都很满意”矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”多指温度或态度冷淡，不用来形容服务的水平，“服务非常冷”不自然。"}], "explanations": {"优质": "正确答案。优质：非常好，与“客人都很满意”相符。", "差": "语义：“差”指质量低，与“客人都很满意”矛盾。", "慢": "语义：服务太慢会让客人不满意，与“客人都很满意”矛盾。", "冷": "搭配：“冷”多指温度或态度冷淡，不用来形容服务的水平，“服务非常冷”不自然。"}, "sentence_index": 0, "correct_answer": "优质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个家庭的地位很优质，大家都很尊敬他们。", "explanation": "这里应该用〈优越〉。优质说质量好，地位、条件比别人好要用优越。"}, {"text": "今天的天气很优质，适合出门散步。", "explanation": "这里应该用〈晴朗〉。优质用于产品、服务的质量，描写天气的好坏要用晴朗。"}, {"text": "这所学校的校风很优质，家长都很放心。", "explanation": "这里应该用〈优良〉。优质用于服务、产品的质量，校风、作风等品行要用优良。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：质量优良，修饰食材，与“菜做得也好吃”相符。"}, {"text": "臭", "is_correct": false, "explanation": "语义：“臭”指难闻，食材臭与“菜做得也好吃”矛盾。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“坏”指变质，食材坏了做不出好吃的菜，与句意矛盾。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”指杂乱，不用来形容食材的品质，“食材乱”不通顺。"}], "explanations": {"优质": "正确答案。优质：质量优良，修饰食材，与“菜做得也好吃”相符。", "臭": "语义：“臭”指难闻，食材臭与“菜做得也好吃”矛盾。", "坏": "语义：“坏”指变质，食材坏了做不出好吃的菜，与句意矛盾。", "乱": "搭配：“乱”指杂乱，不用来形容食材的品质，“食材乱”不通顺。"}, "sentence_index": 6, "correct_answer": "优质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的举止很优质，大家都很喜欢她。", "explanation": "这里应该用〈优雅〉。优质说质量，举止、姿态的美要用优雅。"}, {"text": "他这次考试的分数很优质，全班都很惊讶。", "explanation": "这里应该用〈优异〉。分数、成绩好要用优异，优质用于产品、服务的质量。"}, {"text": "这座城市的夜景很优质，很多人晚上来这里散步。", "explanation": "这里应该用〈优美〉。夜景的美要用优美，优质说的是产品、服务的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店为顾客提供优质地服务，所以大家都喜欢来。", "corrected_sentence": "这家书店为顾客提供优质服务，所以大家都喜欢来。", "error_description": "错误形式：“优质地服务”；正确形式：“优质服务”。“优质”修饰名词时不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家旅馆有很优质床单，客人都很满意。", "corrected_sentence": "这家旅馆有优质床单，客人都很满意。", "error_description": "错误形式：“很优质床单”；正确形式：“优质床单”。“很”不能直接放在名词前作定语，应去掉“很”，或说“很优质的床单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确。“劣质”与“优质”是反义词，指质量低劣。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”指形状，与质量好坏无关，不是“优质”的反义词。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度，与质量无关，不是“优质”的反义词。"}, {"text": "透明", "is_correct": false, "explanation": "“透明”指能透过光线，与质量无关，不是“优质”的反义词。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确。“劣质”与“优质”是反义词，指质量低劣。", "圆": "“圆”指形状，与质量好坏无关，不是“优质”的反义词。", "慢": "“慢”指速度，与质量无关，不是“优质”的反义词。", "透明": "“透明”指能透过光线，与质量无关，不是“优质”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣质", "is_correct": true, "explanation": "正确。“劣质”与“优质”是反义词，指质量低劣。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势，与质量无关，不是“优质”的反义词。"}, {"text": "尖", "is_correct": false, "explanation": "“尖”指末端细而锐利，与质量无关，不是“优质”的反义词。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”指从表面到底部的距离小，与质量无关，不是“优质”的反义词。"}], "correct_answer": "劣质", "explanations": {"劣质": "正确。“劣质”与“优质”是反义词，指质量低劣。", "陡峭": "“陡峭”形容地势，与质量无关，不是“优质”的反义词。", "尖": "“尖”指末端细而锐利，与质量无关，不是“优质”的反义词。", "浅": "“浅”指从表面到底部的距离小，与质量无关，不是“优质”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "质量优良的。", "primary_collocate": null, "pronunciation": "yōu zhì", "ipa": "joʊ˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家店卖的都是优质水果，又新鲜又甜。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们厂只用优质木材做家具。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种优质大米煮出来很香。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一张优质的床垫，睡得很好。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "优质牛奶的价格比普通牛奶贵一些。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场用优质种子，所以粮食长得好。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂生产优质钢材，质量很稳定。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选择优质产品，别买便宜的假货。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的优质茶叶都是从山上采来的。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈只给孩子买优质的奶粉。", "target_word": "优质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "优质产品", "label": "复合"}, {"form": "优质原料", "label": "复合"}], "register": "中性", "sense_fingerprint": "优质：东西质量优良（修饰产品、材料）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：质量优良的。"}, {"text": "优势", "is_correct": false, "explanation": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是有利的条件、长处。"}, {"text": "油脂", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，zhī（第一声）与 zhì（第四声）声调也不同，意思是油类和脂肪。"}, {"text": "有志", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，意思是有志向、有抱负。"}, {"text": "油纸", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，zhǐ（第三声）与 zhì（第四声）声调也不同，意思是涂了油的纸。"}], "explanations": {"优质": "正确答案。优质：质量优良的。", "优势": "shì（第四声）与 zhì（第四声）声母不同（sh 与 zh），意思是有利的条件、长处。", "油脂": "yóu（第二声）与 yōu（第一声）声调不同，zhī（第一声）与 zhì（第四声）声调也不同，意思是油类和脂肪。", "有志": "yǒu（第三声）与 yōu（第一声）声调不同，意思是有志向、有抱负。", "油纸": "yóu（第二声）与 yōu（第一声）声调不同，zhǐ（第三声）与 zhì（第四声）声调也不同，意思是涂了油的纸。"}, "sentence_index": null, "correct_answer": "优质"}, "level_3": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：质量优良，修饰水果，与句意相符。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指腐坏，与后句“又新鲜又甜”矛盾，不能用来形容好水果。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，与后句“又甜”矛盾。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道咸，与后句“又甜”矛盾。"}], "explanations": {"优质": "正确答案。优质：质量优良，修饰水果，与句意相符。", "烂": "语义：“烂”指腐坏，与后句“又新鲜又甜”矛盾，不能用来形容好水果。", "苦": "语义：“苦”指味道，与后句“又甜”矛盾。", "咸": "语义：“咸”指味道咸，与后句“又甜”矛盾。"}, "sentence_index": 0, "correct_answer": "优质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位优质的学生，每次考试都名列前茅。", "explanation": "这里应该用〈优秀〉。优质说产品、服务的质量好，形容人的能力和品行要用优秀。"}, {"text": "他在比赛中取得了优质的成绩。", "explanation": "这里应该用〈优异〉。优质用于产品、服务的质量，成绩好要用优异。"}, {"text": "湖边的风景很优质，很多游客在这里拍照。", "explanation": "这里应该用〈优美〉。优质说质量，风景的美要用优美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优质", "is_correct": true, "explanation": "正确答案。优质：质量优良，修饰钢材，与“质量很稳定”相符。"}, {"text": "假", "is_correct": false, "explanation": "语义：“假”指假货，与“质量很稳定”矛盾。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”指速度，不用来形容钢材，“慢钢材”不通顺。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”指含水，不用来形容钢材，“湿钢材”不通顺。"}], "explanations": {"优质": "正确答案。优质：质量优良，修饰钢材，与“质量很稳定”相符。", "假": "语义：“假”指假货，与“质量很稳定”矛盾。", "慢": "搭配：“慢”指速度，不用来形容钢材，“慢钢材”不通顺。", "湿": "搭配：“湿”指含水，不用来形容钢材，“湿钢材”不通顺。"}, "sentence_index": 6, "correct_answer": "优质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很优质，所以大家都愿意来买。", "explanation": "这里应该用〈优惠〉。优惠说价格便宜、给人好处，优质说的是东西的质量。"}, {"text": "他们的作风很优质，大家都很敬佩。", "explanation": "这里应该用〈优良〉。优质用于产品、服务的质量，作风、品行要用优良。"}, {"text": "她走路的姿态很优质，大家都看得出神。", "explanation": "这里应该用〈优雅〉。优质说质量，姿态、举止的美要用优雅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司只用优质地原料做家具，所以家具很结实。", "corrected_sentence": "这家公司只用优质原料做家具，所以家具很结实。", "error_description": "错误形式：“优质地原料”；正确形式：“优质原料”。“优质”修饰名词时不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂生产很优质钢材，所以价格比较高。", "corrected_sentence": "这家工厂生产优质钢材，所以价格比较高。", "error_description": "错误形式：“很优质钢材”；正确形式：“优质钢材”。“很”修饰形容词作谓语，不能直接放在名词前作定语，应说“优质钢材”或“很优质的钢材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
