INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "等等是说后面还有,这里不再说了。", "primary_collocate": null, "pronunciation": "děng děng", "ipa": "tɤŋ˨˩ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "桌上有苹果、香蕉、西瓜等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会说中文、英文、日文等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖米、面、肉、鱼等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爱运动，比如跑步、游泳、打球等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有花、树、小鸟等等。", "target_word": "等等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的包里有书、手机、钥匙等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教了我们问路、买东西、点菜等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京、上海、广州等等都是大城市。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天可以去爬山、放风筝、看花等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天要做饭、洗衣服、打扫房间等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "列举末尾，表示同类的还有，不再一一说出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示同类的还有，不再一一说出，与“苹果、香蕉、西瓜”的列举相合。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示持续，不能放在“有”字句的列举末尾，句子不成立。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与现代汉语日常陈述的语域不合。"}, {"text": "地", "is_correct": false, "explanation": "语法：“地”是状语标记，要接动词，不能放在句末。"}], "explanations": {"等等": "“等等”放在列举末尾，表示同类的还有，不再一一说出，与“苹果、香蕉、西瓜”的列举相合。", "着": "语法：“着”表示持续，不能放在“有”字句的列举末尾，句子不成立。", "矣": "语域：“矣”是文言语气词，与现代汉语日常陈述的语域不合。", "地": "语法：“地”是状语标记，要接动词，不能放在句末。"}, "sentence_index": 0, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一共只有三个人：小明、小红、小刚等等。", "explanation": "“一共只有三个人”已经说明列全，却又用〈等等〉表示后面还有同类，把封闭的一组说成未完；应去掉〈等等〉。"}, {"text": "我爸爸只有一个哥哥，叫王伟等等。", "explanation": "〈等等〉接在“只有一个哥哥”后面，表示还有同类，但这里只有一个人，没有可以并列的几项；这是把〈等等〉当成随口说“还有别的”。"}, {"text": "我今天只买了一个苹果等等。", "explanation": "〈等等〉表示列举后还有同类，前面至少需要两项并列；只有一个苹果时不能用〈等等〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等等", "is_correct": true, "explanation": "“等等”放在列举末尾，表示“问路、买东西、点菜”之外还有同类的内容，不再一一说出。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示持续，不能接在名词性列举之后，句子不成立。"}, {"text": "得", "is_correct": false, "explanation": "语法：“得”后要接补语，不能放在句末。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”多用于追问或延续话题，这里是陈述，不合。"}], "explanations": {"等等": "“等等”放在列举末尾，表示“问路、买东西、点菜”之外还有同类的内容，不再一一说出。", "着": "语法：“着”表示持续，不能接在名词性列举之后，句子不成立。", "得": "语法：“得”后要接补语，不能放在句末。", "呢": "语义：“呢”多用于追问或延续话题，这里是陈述，不合。"}, "sentence_index": 6, "correct_answer": "等等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年有春、夏、秋、冬等等。", "explanation": "季节只有四个，已经列全，是封闭的一组，不能再用〈等等〉表示还有别的。"}, {"text": "东、南、西、北等等都是方向。", "explanation": "方向只有四个，是封闭的一组，已经列全，这里不应使用〈等等〉。"}, {"text": "一只手有五根手指等等。", "explanation": "手指数量固定，列举已经完整，〈等等〉在这里表示还有别的是不成立的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去超市买了苹果、香蕉、牛奶、等等。", "corrected_sentence": "我们去超市买了苹果、香蕉、牛奶等等。", "error_description": "错误在于〈等等〉前多加了顿号，写成“牛奶、等等”，把它当成了一个并列项。正确的写法是〈等等〉直接接在最后一项后面：“牛奶等等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有图书馆、食堂、操场等等等等。", "corrected_sentence": "我们学校有图书馆、食堂、操场等等。", "error_description": "错误在于〈等等〉重复成“等等等等”。正确的写法是只用一次〈等等〉：“操场等等”，表示列举后还有同类。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
