INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词,表示列举未完。", "primary_collocate": null, "pronunciation": "děng děng", "ipa": "tɤŋ˨˩ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "这家店卖鞋、帽子、衣服等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国菜有饺子、面条、米饭等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里有冰箱、电视、洗衣机等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会打篮球、踢足球、打乒乓球等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天买了牛奶、鸡蛋、面包等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物园里有老虎、大象、熊猫等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里有小说、词典、杂志等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的活动有唱歌、跳舞、比赛等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过法国、德国、意大利等等。", "target_word": "等等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我想看电影、逛街、睡觉等等。", "target_word": "等等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在几个并列项目之后，表示列举没有结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
