INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市卖牛奶、鸡蛋、面包、等等。", "corrected_sentence": "这家超市卖牛奶、鸡蛋、面包等等。", "error_description": "错误在于〈等等〉前多了顿号，写成“面包、等等”。正确的写法是〈等等〉直接接在最后一项“面包”后面，中间不加标点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢看书、听歌、画画等等等等。", "corrected_sentence": "我喜欢看书、听歌、画画等等。", "error_description": "错误在于〈等等〉重复成“等等等等”。正确的写法是只用一次〈等等〉，表示后面还有同类的爱好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
