INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89473, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一个国家里的人分成两边打仗。", "primary_collocate": null, "pronunciation": "nèi zhàn", "ipa": "neɪ˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家发生了内战，很多人离开了家。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战结束后，国家慢慢安静下来。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场内战打了五年，人民过得很苦。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战让这个国家的城市变成了废墟。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家人在内战中去了国外。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为内战，学校都关门了。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战期间，粮食很少，大家吃不饱。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的内战终于停了。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候经历过内战。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边的人在内战里都失去了朋友。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内戰", "label": "繁体"}, {"form": "一场内战", "label": "量词"}, {"form": "爆发内战", "label": "复合"}], "register": "中性", "sense_fingerprint": "内战：一个国家里的人分成两边打仗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内战", "is_correct": true, "explanation": "正确答案。内战：同一国家里的人分成两边打仗，符合句意。"}, {"text": "庆典", "is_correct": false, "explanation": "搭配：“发生”多用于事故、事件，庆典要说“举行”，不说“发生”。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：比赛要说“举行”或“进行”，“发生”与比赛不搭配。"}, {"text": "团圆", "is_correct": false, "explanation": "语义：“团圆”指家人相聚，与“很多人离开了家”矛盾。"}], "explanations": {"内战": "正确答案。内战：同一国家里的人分成两边打仗，符合句意。", "庆典": "搭配：“发生”多用于事故、事件，庆典要说“举行”，不说“发生”。", "比赛": "搭配：比赛要说“举行”或“进行”，“发生”与比赛不搭配。", "团圆": "语义：“团圆”指家人相聚，与“很多人离开了家”矛盾。"}, "sentence_index": 0, "correct_answer": "内战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们和邻国打了一场内战，最后签订了和约。", "explanation": "这里应该用〈战争〉。内战指同一国家内部分成两方的战争，两个国家之间的战争不能说内战。"}, {"text": "他和朋友的内战很快就解决了。", "explanation": "这里应该用〈冲突〉。内战是一国之内的武装对抗，个人之间的矛盾要说冲突。"}, {"text": "工人们因为工资太低，发动了一场内战，要求涨薪。", "explanation": "这里应该用〈罢工〉。内战是两方有组织的武装战争，工人停工要求涨薪要说罢工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内战", "is_correct": true, "explanation": "正确答案。内战：同一国家里的人分成两边打仗，与“粮食很少，大家吃不饱”相符。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：宴会期间食物充足，与“粮食很少，大家吃不饱”矛盾。"}, {"text": "丰收", "is_correct": false, "explanation": "语义：“丰收”指粮食多，与“粮食很少”矛盾。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼通常食物充足，与“粮食很少，大家吃不饱”矛盾。"}], "explanations": {"内战": "正确答案。内战：同一国家里的人分成两边打仗，与“粮食很少，大家吃不饱”相符。", "宴会": "语义：宴会期间食物充足，与“粮食很少，大家吃不饱”矛盾。", "丰收": "语义：“丰收”指粮食多，与“粮食很少”矛盾。", "婚礼": "语义：婚礼通常食物充足，与“粮食很少，大家吃不饱”矛盾。"}, "sentence_index": 6, "correct_answer": "内战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上的内战很快就被警察平息了。", "explanation": "这里应该用〈暴动〉。内战是两方有组织的武装战争，街上的小规模骚乱要说暴动。"}, {"text": "这两家公司之间的内战越来越激烈，都在降价抢顾客。", "explanation": "这里应该用〈竞争〉。内战是一国之内的武装战争，公司之间争抢顾客要说竞争。"}, {"text": "食堂里的内战持续了三天，最后才平息。", "explanation": "这里应该用〈争执〉。内战指两方有组织的武装交战，食堂里的口角要说争执。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家爆发了一个内战，很多人逃到了邻国。", "corrected_sentence": "那个国家爆发了一场内战，很多人逃到了邻国。", "error_description": "错误形式：“一个内战”；正确形式：“一场内战”。“内战”是一场战争，量词要用“场”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷年轻时经历过一个内战，所以特别珍惜和平。", "corrected_sentence": "爷爷年轻时经历过一场内战，所以特别珍惜和平。", "error_description": "错误形式：“一个内战”；正确形式：“一场内战”。“内战”是一场战争，量词要用“场”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
