INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一国之内不同政治势力之间的战争。", "primary_collocate": null, "pronunciation": "nèi zhàn", "ipa": "neɪ˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "历史书里写了那个国家的内战。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个政党的矛盾最后发展成了内战。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了美国内战的原因。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战不同于国家之间的战争。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写过一本关于内战的小说。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战双方的政府都想统一全国。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国呼吁内战双方马上停火。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内不同势力争权，可能引起内战。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内战爆发后，外国公司离开了这里。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家研究了这场内战的政治原因。", "target_word": "内战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内戰", "label": "繁体"}, {"form": "一场内战", "label": "量词"}, {"form": "爆发内战", "label": "复合"}], "register": "中性", "sense_fingerprint": "内战：一国之内不同政治势力之间的战争（历史、政治话题）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内战", "is_correct": true, "explanation": "正确答案。内战：一国之内不同政治势力之间的战争，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是人的身体指标，国家没有体重，“国家的体重”不通顺。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的课后练习，历史书不会写“国家的作业”，句意不通。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“国家的地址”搭配不通，国家没有地址，“地址”一般说人或建筑。"}], "explanations": {"内战": "正确答案。内战：一国之内不同政治势力之间的战争，符合句意。", "体重": "搭配：“体重”是人的身体指标，国家没有体重，“国家的体重”不通顺。", "作业": "语义：作业是学生的课后练习，历史书不会写“国家的作业”，句意不通。", "地址": "搭配：“国家的地址”搭配不通，国家没有地址，“地址”一般说人或建筑。"}, "sentence_index": 0, "correct_answer": "内战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间的内战持续了很多年，双方都很疲惫。", "explanation": "这里应该用〈战争〉。内战发生在同一国家内部，两个国家之间打仗要说战争。"}, {"text": "工厂门口发生了内战，警察很快赶来了。", "explanation": "这里应该用〈暴动〉。内战是两方有组织的武装战争，工厂门口的骚动要说暴动。"}, {"text": "学生们为了反对涨学费，发起了一场内战。", "explanation": "这里应该用〈抗议〉。内战是一国之内政治势力之间的武装战争，学生和平地表达反对要说抗议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内战", "is_correct": true, "explanation": "正确答案。内战：交战双方之间的战争，与“联合国呼吁双方停火”相符。"}, {"text": "球赛", "is_correct": false, "explanation": "搭配：“停火”用于交战双方，球赛不说“停火”。"}, {"text": "客户", "is_correct": false, "explanation": "语义：客户不会交战，“联合国呼吁客户停火”不合逻辑。"}, {"text": "乐队", "is_correct": false, "explanation": "语义：乐队不是交战方，与“停火”矛盾。"}], "explanations": {"内战": "正确答案。内战：交战双方之间的战争，与“联合国呼吁双方停火”相符。", "球赛": "搭配：“停火”用于交战双方，球赛不说“停火”。", "客户": "语义：客户不会交战，“联合国呼吁客户停火”不合逻辑。", "乐队": "语义：乐队不是交战方，与“停火”矛盾。"}, "sentence_index": 6, "correct_answer": "内战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩之间的内战越来越深了。", "explanation": "这里应该用〈矛盾〉。内战是武装战争，两个人之间的分歧要说矛盾。"}, {"text": "这个问题一直有内战。", "explanation": "这里应该用〈争议〉。内战是武装战争，观点不同引起的讨论要说争议。"}, {"text": "两个邻居因为院子发生了内战。", "explanation": "这里应该用〈纠纷〉。内战指一国之内的武装战争，邻里之间的争执要说纠纷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时参加过一个内战，所以很少谈论过去。", "corrected_sentence": "他年轻时参加过一场内战，所以很少谈论过去。", "error_description": "错误形式：“一个内战”；正确形式：“一场内战”。“内战”是一场战争，量词要用“场”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "历史学家研究了一个内战，写成了好几本书。", "corrected_sentence": "历史学家研究了一场内战，写成了好几本书。", "error_description": "错误形式：“一个内战”；正确形式：“一场内战”。“内战”是一场战争，量词要用“场”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
