INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "信徒是相信一种宗教的人。", "primary_collocate": null, "pronunciation": "xìn tú", "ipa": "ɕin⁵¹ tʰu³⁵", "syllable_count": 2, "sentences": [{"text": "他是一个很虔诚的信徒，每周都去教堂。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日上午，教堂里坐满了信徒。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居是信徒，他每天早上都祈祷。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是信徒，所以不吃肉。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信徒们在庙里一起唱歌，很热闹。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是信徒，一直相信神。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座教堂有一千多名信徒。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为信徒，她每天都读一会儿经书。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信徒们带着花去庙里，给神像鞠躬。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前不是信徒，后来才开始信教。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "信徒们", "label": "复数"}, {"form": "佛教信徒", "label": "复合"}], "register": "中性", "sense_fingerprint": "相信某种宗教的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89475, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信徒", "is_correct": true, "explanation": "正确：信徒是相信宗教的人，虔诚地每周去教堂。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能虔诚地去教堂，与句意冲突。"}, {"text": "啤酒", "is_correct": false, "explanation": "搭配：「虔诚」形容人的信仰态度，不与「啤酒」搭配。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车不能去教堂做礼拜，句子无法成立。"}], "explanations": {"信徒": "正确：信徒是相信宗教的人，虔诚地每周去教堂。", "石头": "语义：石头不能虔诚地去教堂，与句意冲突。", "啤酒": "搭配：「虔诚」形容人的信仰态度，不与「啤酒」搭配。", "公交车": "语义：公交车不能去教堂做礼拜，句子无法成立。"}, "sentence_index": 0, "correct_answer": "信徒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在木匠店当信徒，每天学做家具。", "explanation": "这里应该用〈学徒〉。信徒指信奉宗教的人，跟着师傅学手艺的人要说「学徒」。"}, {"text": "他是村里的信徒，每天负责送信。", "explanation": "这里应该用〈信使〉。信徒指信奉宗教的人，负责送信的人要说「信使」。"}, {"text": "她是这所中学的信徒，每天早上背单词。", "explanation": "这里应该用〈学生〉。信徒指信奉宗教的人，在中学读书的人要说「学生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信徒", "is_correct": true, "explanation": "正确：教堂里一千多人都是信奉宗教、来做礼拜的人。"}, {"text": "警察", "is_correct": false, "explanation": "语义：教堂里不会有一千多名警察，与「教堂」的语境不合。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：一千多名士兵不会聚在教堂里，与语境不符。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：「教堂」一般不与「病人」搭配，病人应在医院。"}], "explanations": {"信徒": "正确：教堂里一千多人都是信奉宗教、来做礼拜的人。", "警察": "语义：教堂里不会有一千多名警察，与「教堂」的语境不合。", "士兵": "语义：一千多名士兵不会聚在教堂里，与语境不符。", "病人": "搭配：「教堂」一般不与「病人」搭配，病人应在医院。"}, "sentence_index": 6, "correct_answer": "信徒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是俱乐部的信徒，每周都去游泳。", "explanation": "这里应该用〈会员〉。信徒指信奉宗教的人，俱乐部的成员要说「会员」。"}, {"text": "他是这家工厂的信徒，每天上八小时班。", "explanation": "这里应该用〈员工〉。信徒指信奉宗教的人，在工厂工作的人要说「员工」。"}, {"text": "他是这家医院的信徒，每周都来打针。", "explanation": "这里应该用〈病人〉。信徒指信奉宗教的人，在医院看病的人要说「病人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教堂里来了两个信徒们。", "corrected_sentence": "教堂里来了两个信徒。", "error_description": "错误：「两个信徒们」。「们」不能与数量词一起使用，正确为「两个信徒」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当过十年信徒们，后来不信了。", "corrected_sentence": "她当过十年信徒，后来不信了。", "error_description": "错误：「信徒们」。主语「她」只是一个人，不能用表示复数的「们」，去掉「们」即可，正确为「当过十年信徒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
