INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "信奉某种宗教的人。", "primary_collocate": null, "pronunciation": "xìn tú", "ipa": "ɕin⁵¹ tʰu³⁵", "syllable_count": 2, "sentences": [{"text": "很多信徒在节日那天去寺庙烧香。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成为信徒已经十年了。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个宗教有几百万信徒，住在很多国家。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友是一位信徒，从来不喝酒。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个信徒都要遵守教里的规矩。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做礼拜的时候，信徒们都很安静。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信徒送给神父一束花。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的信徒一起修了一座小教堂。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是信徒，所以过年也不拜祖先。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看信徒怎么做礼拜。", "target_word": "信徒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "信徒们", "label": "复数"}, {"form": "基督教信徒", "label": "复合"}], "register": "中性", "sense_fingerprint": "信奉某种宗教的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信徒", "is_correct": true, "explanation": "正确：信奉宗教的人会在节日去寺庙烧香。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人不会烧香拜佛，句子无法成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能去寺庙烧香，与句意不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：「烧香」的主体须是人，「汽车」不与「烧香」搭配。"}], "explanations": {"信徒": "正确：信奉宗教的人会在节日去寺庙烧香。", "机器人": "语义：机器人不会烧香拜佛，句子无法成立。", "石头": "语义：石头不能去寺庙烧香，与句意不符。", "汽车": "搭配：「烧香」的主体须是人，「汽车」不与「烧香」搭配。"}, "sentence_index": 0, "correct_answer": "信徒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这所大学的信徒，每天都去图书馆。", "explanation": "这里应该用〈学生〉。信徒指信奉宗教的人，在大学读书的人要说「学生」。"}, {"text": "她在这家餐厅当信徒，负责端菜。", "explanation": "这里应该用〈员工〉。信徒指信奉宗教的人，在餐厅工作的人要说「员工」。"}, {"text": "他是我们班的信徒，每天一起做作业。", "explanation": "这里应该用〈同学〉。信徒指信奉宗教的人，同班读书的人要说「同学」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信徒", "is_correct": true, "explanation": "正确：信奉宗教的人会给神父送花。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能送花，与「送给神父」的施事不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无法把花送给神父，句意不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：「送给」的施事须是能送礼的人，「汽车」不能作施事。"}], "explanations": {"信徒": "正确：信奉宗教的人会给神父送花。", "电脑": "语义：电脑不能送花，与「送给神父」的施事不符。", "桌子": "语义：桌子无法把花送给神父，句意不成立。", "汽车": "配价：「送给」的施事须是能送礼的人，「汽车」不能作施事。"}, "sentence_index": 6, "correct_answer": "信徒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在木匠店当信徒，学了三年手艺。", "explanation": "这里应该用〈学徒〉。信徒指信奉宗教的人，跟着师傅学手艺的人要说「学徒」。"}, {"text": "他是图书馆的信徒，每周都借书。", "explanation": "这里应该用〈会员〉。信徒指信奉宗教的人，图书馆的注册成员要说「会员」。"}, {"text": "他是这趟列车的信徒，每天都坐它上班。", "explanation": "这里应该用〈乘客〉。信徒指信奉宗教的人，坐火车、列车的人要说「乘客」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口来了一信徒。", "corrected_sentence": "村口来了一位信徒。", "error_description": "错误：「一信徒」。「一」与名词之间缺少量词，正确为「一位信徒」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经做过十年信徒们。", "corrected_sentence": "他曾经做过十年信徒。", "error_description": "错误：「信徒们」。主语「他」只是一个人，不能用表示复数的「们」，去掉「们」即可，正确为「做过十年信徒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
