INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妻子(口语)。", "primary_collocate": null, "pronunciation": "lǎo pó", "ipa": "lɑʊ˨˩˦ pʰwo˧˥", "syllable_count": 2, "sentences": [{"text": "他的老婆是医生。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生带着老婆去旅行了。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友娶了一个好老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱他的老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的老婆在银行工作。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天送老婆上班。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥的老婆是我同学。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工资都给了老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想早点找个老婆。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的老婆比他小两岁。", "target_word": "老婆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "口语中指妻子，如“他的老婆是医生”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老婆", "is_correct": true, "explanation": "“老婆”指妻子，放在“他的___是医生”中，说的是他的妻子职业。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”是动物，不能是医生，句子语境不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”是物品，不能与“是医生”构成人的身份说明。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不能是医生，与“是医生”搭配不成立。"}], "explanations": {"老婆": "“老婆”指妻子，放在“他的___是医生”中，说的是他的妻子职业。", "小狗": "语义：“小狗”是动物，不能是医生，句子语境不通。", "椅子": "搭配：“椅子”是物品，不能与“是医生”构成人的身份说明。", "汽车": "语义：“汽车”不能是医生，与“是医生”搭配不成立。"}, "sentence_index": 0, "correct_answer": "老婆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子对母亲说：“老婆，我饿了。”", "explanation": "这里应该用〈妈妈〉。“老婆”是丈夫称妻子的话，孩子不能用它称呼母亲。"}, {"text": "他对陌生人说：“老婆，请问厕所在哪儿？”", "explanation": "这里应该用〈先生〉。“老婆”只指妻子，不能用来称呼不认识的人。"}, {"text": "同事对我说：“老婆，你的文件呢？”", "explanation": "这里应该用〈小王〉。“老婆”只指妻子，不能用来称呼同事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老婆", "is_correct": true, "explanation": "“老婆”指妻子，放在“我哥哥的___是我同学”中，说的是哥哥的妻子。"}, {"text": "女士", "is_correct": false, "explanation": "语域：“女士”是礼貌称呼，不能用来指哥哥的妻子这种家庭关系。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”是搭乘交通工具的人，与“我哥哥的……是我同学”的语境不符。"}, {"text": "售货员", "is_correct": false, "explanation": "语义：“售货员”是职业身份，不能是哥哥的家人，也不能与“同学”的身份对应。"}], "explanations": {"老婆": "“老婆”指妻子，放在“我哥哥的___是我同学”中，说的是哥哥的妻子。", "女士": "语域：“女士”是礼貌称呼，不能用来指哥哥的妻子这种家庭关系。", "乘客": "语义：“乘客”是搭乘交通工具的人，与“我哥哥的……是我同学”的语境不符。", "售货员": "语义：“售货员”是职业身份，不能是哥哥的家人，也不能与“同学”的身份对应。"}, "sentence_index": 6, "correct_answer": "老婆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈对儿子说：“老婆，你今天回家吃饭吗？”", "explanation": "这里应该用〈宝贝〉。“老婆”是丈夫称妻子的话，母亲不能拿它称呼儿子。"}, {"text": "服务员对客人说：“老婆，您的饭好了。”", "explanation": "这里应该用〈女士〉。“老婆”只指丈夫的妻子，不能用来称呼客人。"}, {"text": "教练对队员说：“老婆，再跑一圈。”", "explanation": "这里应该用〈小伙子〉。“老婆”只指妻子，不能用来称呼男队员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的老婆的在银行工作。", "corrected_sentence": "他的老婆在银行工作。", "error_description": "错误：“他的老婆的在银行工作”，“老婆”后面多加了一个“的”。正确：“他的老婆在银行工作”，“的”只用在领属词“他”后面，“老婆”后不再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一只好老婆。", "corrected_sentence": "他找到了一个好老婆。", "error_description": "错误：“一只好老婆”；正确：“一个好老婆”。“只”用于动物，指人应当用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：「怀疑」与「信赖」（相信对方可靠）意思相反，是它的反义词。"}, {"text": "鼓励", "is_correct": false, "explanation": "「鼓励」指给人力量或信心，与「信赖」的相信可靠无反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "「观察」指仔细看、留意，与「信赖」无反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "「参加」指加入某项活动，与「信赖」无反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：「怀疑」与「信赖」（相信对方可靠）意思相反，是它的反义词。", "鼓励": "「鼓励」指给人力量或信心，与「信赖」的相信可靠无反义关系。", "观察": "「观察」指仔细看、留意，与「信赖」无反义关系。", "参加": "「参加」指加入某项活动，与「信赖」无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：「怀疑」与「信赖」（相信对方可靠）意思相反，是它的反义词。"}, {"text": "询问", "is_correct": false, "explanation": "「询问」指提出问题请人回答，与「信赖」无反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "「讨论」指大家交换意见，与「信赖」无反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "「等待」指等候某人或某事，与「信赖」无反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：「怀疑」与「信赖」（相信对方可靠）意思相反，是它的反义词。", "询问": "「询问」指提出问题请人回答，与「信赖」无反义关系。", "讨论": "「讨论」指大家交换意见，与「信赖」无反义关系。", "等待": "「等待」指等候某人或某事，与「信赖」无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "信赖是相信他，觉得他可靠。", "primary_collocate": null, "pronunciation": "xìn lài", "ipa": "ɕin˥˩ laɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我很信赖我的老朋友。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子信赖妈妈，什么都告诉她。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都信赖这位老师。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个可靠的人，所以我信赖他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们互相信赖，从不说谎。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们信赖她，有问题就找她。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就信赖哥哥，有事都找他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人信赖这位医生。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以信赖我，我不会说出去。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他信赖过一个朋友，可是那个人骗了他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信赖着", "label": "体标"}, {"form": "信赖过", "label": "体标"}], "register": "中性", "sense_fingerprint": "信赖：相信某人，觉得他可靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信赖", "is_correct": true, "explanation": "正确：「很信赖」表示相信对方可靠，与「老朋友」的亲近关系相合。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：「毕业」是不及物动词，不能带「我的老朋友」作宾语，也不受「很」修饰。"}, {"text": "出发", "is_correct": false, "explanation": "语法：「出发」不带人作宾语，「很出发我的老朋友」不成话。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」的对象是地方或物品，不能是人，也不受「很」修饰。"}], "explanations": {"信赖": "正确：「很信赖」表示相信对方可靠，与「老朋友」的亲近关系相合。", "毕业": "语法：「毕业」是不及物动词，不能带「我的老朋友」作宾语，也不受「很」修饰。", "出发": "语法：「出发」不带人作宾语，「很出发我的老朋友」不成话。", "打扫": "语义：「打扫」的对象是地方或物品，不能是人，也不受「很」修饰。"}, "sentence_index": 0, "correct_answer": "信赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我信赖这盘菜很香。", "explanation": "这里应该用〈觉得〉。「信赖」指相信对方可靠，不用于评价菜肴的味道；说“很香”要用〈觉得〉。"}, {"text": "老人信赖拐杖走路。", "explanation": "这里应该用〈依赖〉。「信赖」指相信对方可靠，拐杖是靠它支撑的物件，靠物件支持要用〈依赖〉。"}, {"text": "我信赖这个城市的天气。", "explanation": "这里应该用〈关注〉。「信赖」指相信对方可靠，不用于天气这类自然现象；对天气只能说关注或留意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信赖", "is_correct": true, "explanation": "正确：「从小就信赖哥哥」表示长期的依靠和相信，与「从小就」相合。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：「冷落」指怠慢、不理会，与句中长期亲近的关系相反。"}, {"text": "怀念", "is_correct": false, "explanation": "搭配：「怀念」多用于对已离开或分别之人的思念，与「从小就」一直在身边的情况不搭。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「从小就忘记哥哥」说不通，忘记的人无法长期依靠和相信。"}], "explanations": {"信赖": "正确：「从小就信赖哥哥」表示长期的依靠和相信，与「从小就」相合。", "冷落": "语义：「冷落」指怠慢、不理会，与句中长期亲近的关系相反。", "怀念": "搭配：「怀念」多用于对已离开或分别之人的思念，与「从小就」一直在身边的情况不搭。", "忘记": "语义：「从小就忘记哥哥」说不通，忘记的人无法长期依靠和相信。"}, "sentence_index": 6, "correct_answer": "信赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我信赖这份试卷的题目。", "explanation": "这里是在说对试题是否正确的判断，「信赖」表示相信人或可靠组织的可靠，不用于对题目的判断。"}, {"text": "我信赖今年的天气。", "explanation": "这里是在说对天气的关注或预测，「信赖」用于可靠的人或组织，不用于自然现象。"}, {"text": "我信赖这把椅子的颜色。", "explanation": "这里是在说对颜色的喜欢或满意，「信赖」不用于外观属性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子很信赖了他的爷爷，有事都跟爷爷说。", "corrected_sentence": "这个孩子很信赖他的爷爷，有事都跟爷爷说。", "error_description": "错在“信赖”后的“了”：“信赖”表示持续的态度，不表示完成，不能加“了”；应说“很信赖他的爷爷”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生值得患者信赖了，她耐心又细心。", "corrected_sentence": "这位医生值得患者信赖，她耐心又细心。", "error_description": "错在“值得……信赖”结构中的“了”：“值得”后的“信赖”是固定的评价结构，不能加“了”，应说“值得患者信赖”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：「怀疑」与「信赖」（相信并依靠）意思相反，是它的反义词。"}, {"text": "批评", "is_correct": false, "explanation": "「批评」指指出缺点或错误，与「信赖」无反义关系。"}, {"text": "拜访", "is_correct": false, "explanation": "「拜访」指去探望别人，与「信赖」无反义关系。"}, {"text": "邀请", "is_correct": false, "explanation": "「邀请」指请对方来做某事，与「信赖」无反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：「怀疑」与「信赖」（相信并依靠）意思相反，是它的反义词。", "批评": "「批评」指指出缺点或错误，与「信赖」无反义关系。", "拜访": "「拜访」指去探望别人，与「信赖」无反义关系。", "邀请": "「邀请」指请对方来做某事，与「信赖」无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怀疑", "is_correct": true, "explanation": "正确：「怀疑」与「信赖」（相信并依靠）意思相反，是它的反义词。"}, {"text": "观察", "is_correct": false, "explanation": "「观察」指仔细看、留意，与「信赖」无反义关系。"}, {"text": "安慰", "is_correct": false, "explanation": "「安慰」指使人心里舒服，与「信赖」无反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "「等待」指等候某人或某事，与「信赖」无反义关系。"}], "correct_answer": "怀疑", "explanations": {"怀疑": "正确：「怀疑」与「信赖」（相信并依靠）意思相反，是它的反义词。", "观察": "「观察」指仔细看、留意，与「信赖」无反义关系。", "安慰": "「安慰」指使人心里舒服，与「信赖」无反义关系。", "等待": "「等待」指等候某人或某事，与「信赖」无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "信任并依靠。", "primary_collocate": null, "pronunciation": "xìn lài", "ipa": "ɕin˥˩ laɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老人信赖儿子，生活上依靠他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在困难时，我只能信赖你。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟很信赖姐姐，遇事总找她。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，我们一直信赖这家公司。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们信赖着父母，觉得很安全。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队员值得大家信赖。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人把希望都放在医生身上，十分信赖他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人在外，最信赖的就是这位朋友。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你信赖谁，谁就是你的依靠。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗信赖主人，总跟着他。", "target_word": "信赖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信赖着", "label": "体标"}, {"form": "信赖过", "label": "体标"}], "register": "中性", "sense_fingerprint": "信赖：信任并依靠某人或某事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信赖", "is_correct": true, "explanation": "正确：「老人信赖儿子，生活上依靠他」前后呼应，表示相信并依靠。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘了儿子就不可能在生活上依靠他，与后半句冲突。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝儿子与生活上依靠他互相矛盾，句子说不通。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：「嫌弃」多用于对不满意的人或物的厌烦，与「依靠他」所体现的信任语气不协调。"}], "explanations": {"信赖": "正确：「老人信赖儿子，生活上依靠他」前后呼应，表示相信并依靠。", "忘记": "语义：忘了儿子就不可能在生活上依靠他，与后半句冲突。", "拒绝": "语义：拒绝儿子与生活上依靠他互相矛盾，句子说不通。", "嫌弃": "搭配：「嫌弃」多用于对不满意的人或物的厌烦，与「依靠他」所体现的信任语气不协调。"}, "sentence_index": 0, "correct_answer": "信赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直信赖小时候住过的老房子。", "explanation": "这里应该用〈怀念〉。句子表达的是对往事的思念，并非依靠或托付，「信赖」在此不通。"}, {"text": "我信赖明天会转晴。", "explanation": "这里应该用〈相信〉。「信赖」用于可托付的人或组织，后面接整句陈述时要用〈相信〉。"}, {"text": "我信赖这幅画的色彩。", "explanation": "这里应该用〈欣赏〉。色彩不是可以依靠的对象，「信赖」在此不通；对画面色彩的赞赏要说〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信赖", "is_correct": true, "explanation": "正确：「把希望都放在医生身上，十分信赖他」前后一致，表示充分相信。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：「把希望都放在医生身上」与「怀疑他」互相矛盾。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：把希望寄托在医生身上的人不会厌烦他，「十分厌烦他」与前半句矛盾。"}, {"text": "叱责", "is_correct": false, "explanation": "语域：「叱责」书面色彩较重，与句子的口语叙述不协调，且与依托希望的语气矛盾。"}], "explanations": {"信赖": "正确：「把希望都放在医生身上，十分信赖他」前后一致，表示充分相信。", "怀疑": "语义：「把希望都放在医生身上」与「怀疑他」互相矛盾。", "厌烦": "语义：把希望寄托在医生身上的人不会厌烦他，「十分厌烦他」与前半句矛盾。", "叱责": "语域：「叱责」书面色彩较重，与句子的口语叙述不协调，且与依托希望的语气矛盾。"}, "sentence_index": 6, "correct_answer": "信赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她信赖这首歌很好听，每天都听。", "explanation": "这里不能用〈信赖〉接整句陈述「这首歌很好听」，应说〈觉得〉或〈喜欢〉。"}, {"text": "我信赖这把椅子的颜色。", "explanation": "这里不能用〈信赖〉。颜色是外观属性，不是可以托付的对象，这里应该用〈满意〉。"}, {"text": "他信赖这张桌子的重量。", "explanation": "这里不能用〈信赖〉。重量是客观属性，不是值得托付的对象，说对重量的关注不用「信赖」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家银行值得客户信赖了，服务很周到。", "corrected_sentence": "这家银行值得客户信赖，服务很周到。", "error_description": "「值得……信赖」表示值得托付的评价，「信赖」后面不加「了」，应说「值得客户信赖」；「信赖了」中多出的「了」是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很信赖了自己的朋友，有事都找他帮忙。", "corrected_sentence": "他很信赖自己的朋友，有事都找他帮忙。", "error_description": "「很信赖」表示一种持续的心理状态，受「很」修饰时后面不加「了」，应说「很信赖自己的朋友」；多出的「了」是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
