INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89481, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "访问是去看一个人,或问他一些事。", "primary_collocate": null, "pronunciation": "fǎng wèn", "ipa": "fɑŋ˨˩˦ wən˥˩", "syllable_count": 2, "sentences": [{"text": "周末我想去访问一位在农村种茶的老人，了解他的经历。", "target_word": "访问", "complexity_tier": "T3", "furigana": "zhōu mò wǒ xiǎng qù fǎng wèn yí wèi zài nóng cūn zhǒng chá de lǎo rén, liǎo jiě tā de jīng lì.", "sentence_source": "generated"}, {"text": "记者访问了那位年轻的医生。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们去访问住在附近的老人。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想访问几位老师,问问学习的方法。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天要访问一位老作家。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他访问过很多有名的音乐家。", "target_word": "访问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李正在访问一位老工人。", "target_word": "访问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想访问爷爷,了解他年轻时的生活。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视台来访问我们的校长。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者把问题写好,然后去访问那位歌手。", "target_word": "访问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "访问了", "label": "体标"}, {"form": "访问过", "label": "体标"}, {"form": "访问者", "label": "复合"}], "register": "中性", "sense_fingerprint": "访问:去见某个人,向他了解情况或提问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "访问", "is_correct": true, "explanation": "正确。访问指去见老人并向他了解情况，与句中的目的相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象通常是场所或展览，不能用于一位老人。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：「照顾」指照料生活，与「了解他的经历」的目的不符。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：「辅导」指指导学习，不能表示为了了解他的经历而去见人。"}], "explanations": {"访问": "正确。访问指去见老人并向他了解情况，与句中的目的相符。", "参观": "搭配：「参观」的对象通常是场所或展览，不能用于一位老人。", "照顾": "语义：「照顾」指照料生活，与「了解他的经历」的目的不符。", "辅导": "语义：「辅导」指指导学习，不能表示为了了解他的经历而去见人。"}, "sentence_index": 0, "correct_answer": "访问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去那家书店访问，买了几本旧书。", "explanation": "这里应该用〈光顾〉。访问强调有目的地去见人或了解情况，去商店买东西要说光顾。"}, {"text": "我想访问那本书。", "explanation": "这里应该用〈研究〉。访问的对象是人，要了解书的内容应该用研究或阅读。"}, {"text": "他明天要访问那辆汽车，准备好了钥匙。", "explanation": "这里应该用〈开〉。访问的对象是人，驾驶汽车应说开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "访问", "is_correct": true, "explanation": "正确。访问可以带人作宾语，表示去见老工人并与他交谈。"}, {"text": "逛", "is_correct": false, "explanation": "搭配：「逛」的对象是街道、商场等场所，不能带人作宾语。"}, {"text": "摔", "is_correct": false, "explanation": "语义：「摔」指使物体落下，用于人显得粗暴，与拜访的意思不符。"}, {"text": "轰", "is_correct": false, "explanation": "语义：「轰」指赶走，与去见老工人的意思相反。"}], "explanations": {"访问": "正确。访问可以带人作宾语，表示去见老工人并与他交谈。", "逛": "搭配：「逛」的对象是街道、商场等场所，不能带人作宾语。", "摔": "语义：「摔」指使物体落下，用于人显得粗暴，与拜访的意思不符。", "轰": "语义：「轰」指赶走，与去见老工人的意思相反。"}, "sentence_index": 6, "correct_answer": "访问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我去公园访问，拍了很多照片。", "explanation": "这里应该用〈逛〉。访问的对象是人，去公园随便转转应说逛。"}, {"text": "他访问了那棵大树，给它浇了水。", "explanation": "这里应该用〈照顾〉。访问的对象是人，照料树木应说照顾。"}, {"text": "记者访问了那场比赛的结果。", "explanation": "这里应该用〈调查〉。访问的对象是人，比赛结果不是人，不能作访问的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年我不访问过那位作家。", "corrected_sentence": "去年我访问过那位作家。", "error_description": "「不」不能否定已经发生的经历（经历的否定用「没」），应去掉「不」，说「访问过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她明天会访问着那位老教授。", "corrected_sentence": "她明天会访问那位老教授。", "error_description": "「着」表示动作进行或持续，与表示将来的「明天会」矛盾，应去掉「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
