INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有目的地去看望或会见某人;了解情况。", "primary_collocate": null, "pronunciation": "fǎng wèn", "ipa": "fɑŋ˨˩˦ wən˥˩", "syllable_count": 2, "sentences": [{"text": "校长明天要去北京访问。", "target_word": "访问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总统下周将访问中国。", "target_word": "访问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "代表团访问了三个国家。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师到学生家里访问,了解孩子的情况。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们去山区访问,想看看农民过得怎么样。", "target_word": "访问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理访问过几家公司,了解了市场情况。", "target_word": "访问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者来我们学校访问了两个星期。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长访问了那个小村子,听大家说话。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师常常去学生家访问。", "target_word": "访问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国客人来中国访问,参观了很多地方。", "target_word": "访问", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "访问了", "label": "体标"}, {"form": "访问过", "label": "体标"}, {"form": "访问者", "label": "复合"}], "register": "中性", "sense_fingerprint": "访问:带着目的去某地或某人处,进行看望、会见或了解情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "访问", "is_correct": true, "explanation": "正确。访问表示有目的地去某地，符合校长出差的语境。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：去北京洗澡与公务出行的目的不符。"}, {"text": "种植", "is_correct": false, "explanation": "配价：「种植」需要带植物作宾语，不能只说去某地。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：去北京睡觉与明天正式的出行安排不符。"}], "explanations": {"访问": "正确。访问表示有目的地去某地，符合校长出差的语境。", "洗澡": "语义：去北京洗澡与公务出行的目的不符。", "种植": "配价：「种植」需要带植物作宾语，不能只说去某地。", "睡觉": "语义：去北京睡觉与明天正式的出行安排不符。"}, "sentence_index": 0, "correct_answer": "访问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去邻居那里访问了一下消息。", "explanation": "这里应该用〈打听〉。访问的对象是人、地方或机构，不能带“消息”这类信息作宾语，了解消息应说打听。"}, {"text": "警察访问了那起案件。", "explanation": "这里应该用〈调查〉。访问的对象是人、地方或机构，案件不能作访问的对象。"}, {"text": "我下班后去同事家访问，聊聊天。", "explanation": "这里应该用〈串门〉。访问偏重有目的、比较正式的拜访，去同事家随便聊天应说串门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "访问", "is_correct": true, "explanation": "正确。访问指学者来校进行交流、了解情况，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：学者来校结婚不符合此处的来访目的。"}, {"text": "抢劫", "is_correct": false, "explanation": "配价：「抢劫」需要带受害对象作宾语，单用不能表示来校的活动。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「生病」是身体状况，不能表示来校进行的活动。"}], "explanations": {"访问": "正确。访问指学者来校进行交流、了解情况，符合句意。", "结婚": "语义：学者来校结婚不符合此处的来访目的。", "抢劫": "配价：「抢劫」需要带受害对象作宾语，单用不能表示来校的活动。", "生病": "语义：「生病」是身体状况，不能表示来校进行的活动。"}, "sentence_index": 6, "correct_answer": "访问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察访问了那辆汽车，并把它开走了。", "explanation": "这里应该用〈扣押〉。访问的对象是人、地方或机构，汽车是物品，扣押汽车应说扣押。"}, {"text": "春节我们去墓地访问，给爷爷上香。", "explanation": "这里应该用〈扫墓〉。访问是去见活人或了解情况，祭扫坟墓要说扫墓。"}, {"text": "这份报告我们访问了三次。", "explanation": "这里应该用〈阅读〉。访问的对象是人、地方或机构，报告是文件，读报告要说阅读或研究。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "代表团昨天不访问了那个国家。", "corrected_sentence": "代表团昨天访问了那个国家。", "error_description": "「不」不能否定已经完成的动作（「了」的否定要用「没」），应去掉「不」，说「访问了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们下个月将访问过那所大学。", "corrected_sentence": "他们下个月将访问那所大学。", "error_description": "「过」表示已经完成，与表示将来的「下个月」矛盾，应去掉「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
