INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89483, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大声告诉大家，请大家一起来做一件事。", "primary_collocate": null, "pronunciation": "dòng yuán", "ipa": "tʊŋ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "校长动员全校同学参加植树活动。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长在会上动员大家一起打扫卫生。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长动员村民一起修路。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师动员同学们给灾区捐书。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他动员邻居们一起照顾老人。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理动员大家周末加班。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长大声动员同学们去操场集合。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈动员全家人一起搬家。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区主任动员居民参加清洁活动。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她动员了很多朋友来看比赛。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动员了", "label": "完成体"}, {"form": "动员过", "label": "经历体"}, {"form": "動員", "label": "繁体"}], "register": "通用", "sense_fingerprint": "当众讲话，请大家一起参与做某件事（日常、小范围）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动员", "is_correct": true, "explanation": "动员：号召全校同学参加活动，与“校长”和“参加植树活动”的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，植树是值得鼓励的集体活动，校长不会嘲笑全校同学参加它。"}, {"text": "逃避", "is_correct": false, "explanation": "配价：逃避的宾语应是责任、困难之类，不能直接以“全校同学”作宾语，句子说不通。"}, {"text": "指责", "is_correct": false, "explanation": "语义：指责是批评过失，同学参加植树活动是正当的，句中没有可指责的过错。"}], "explanations": {"动员": "动员：号召全校同学参加活动，与“校长”和“参加植树活动”的语境相符。", "嘲笑": "语义：嘲笑是取笑别人，植树是值得鼓励的集体活动，校长不会嘲笑全校同学参加它。", "逃避": "配价：逃避的宾语应是责任、困难之类，不能直接以“全校同学”作宾语，句子说不通。", "指责": "语义：指责是批评过失，同学参加植树活动是正当的，句中没有可指责的过错。"}, "sentence_index": 0, "correct_answer": "动员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校动员了一次捐书活动。", "explanation": "这里应该用〈发动〉。发动可用于活动、运动，如发动一次捐书活动；动员的对象是人，不能直接以“活动”作宾语。"}, {"text": "他动员了那辆旧自行车去上班。", "explanation": "这里应该用〈骑〉。骑用于自行车，如骑自行车去上班；动员的对象是人，不能指自行车。"}, {"text": "工厂动员了这台打印机。", "explanation": "这里应该用〈修理〉。修理用于机器、设备，如修理这台打印机；动员的对象是人，不能指机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动员", "is_correct": true, "explanation": "动员：号召同学们集合，与“班长大声”和“去操场集合”的语境相符。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：原谅的宾语是过错，不能带“同学们去操场集合”这样的小句，句子说不通。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：观察是细致地看，不能说“大声观察”，与句中的“大声”不搭配。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是因他人而生的不满，班长并不会因为同学去操场集合而嫉妒他们。"}], "explanations": {"动员": "动员：号召同学们集合，与“班长大声”和“去操场集合”的语境相符。", "原谅": "配价：原谅的宾语是过错，不能带“同学们去操场集合”这样的小句，句子说不通。", "观察": "搭配：观察是细致地看，不能说“大声观察”，与句中的“大声”不搭配。", "嫉妒": "语义：嫉妒是因他人而生的不满，班长并不会因为同学去操场集合而嫉妒他们。"}, "sentence_index": 6, "correct_answer": "动员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师动员了很多作业。", "explanation": "这里应该用〈布置〉。布置用于作业、任务，如布置很多作业；动员的对象是人，不能指作业。"}, {"text": "工人动员了新的空调。", "explanation": "这里应该用〈安装〉。安装用于空调、设备，如安装新的空调；动员的对象是人，不能指空调。"}, {"text": "她动员了那间乱糟糟的房间。", "explanation": "这里应该用〈收拾〉。收拾用于房间、物品，如收拾房间；动员的对象是人，不能指房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师了动员全班同学一起打扫教室。", "corrected_sentence": "老师动员全班同学一起打扫教室。", "error_description": "错误：“了”放在了动词“动员”之前，写成“了动员”。动词前不能加动态助词“了”，这里不需要“了”，去掉即可，正确说法是“老师动员全班同学一起打扫教室。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师正在动员了同学们捐书。", "corrected_sentence": "老师正在动员同学们捐书。", "error_description": "体标错误：“正在”表示动作进行中，“动员”后不能再加表示完成的“了”，应去掉“了”，说“老师正在动员同学们捐书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
