INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "号召并组织人们参加某项活动或工作。", "primary_collocate": null, "pronunciation": "dòng yuán", "ipa": "tʊŋ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "政府动员群众参加抗洪救灾。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校动员学生参加志愿服务。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院动员医生去山区工作。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司动员员工参加环保活动。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府动员了上万人参加植树。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会动员工人参加培训。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府已经动员各方力量救灾。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们动员过不少青年去农村工作。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红十字会动员市民给灾区献血。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村干部动员农民一起建水库。", "target_word": "动员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动员了", "label": "完成体"}, {"form": "动员过", "label": "经历体"}, {"form": "動員", "label": "繁体"}], "register": "通用", "sense_fingerprint": "由政府、机构等号召并组织较多的人参加某项活动或工作（较正式、大范围）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动员", "is_correct": true, "explanation": "动员：政府号召群众参加抗洪救灾，与“政府”和“群众”的语境相符。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：讽刺是用话挖苦人，政府号召群众救灾不应被讽刺，句意不通。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：原谅的宾语是过错，不能带“群众参加抗洪救灾”这样的小句。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离是把人与外界分开，政府不会隔离群众使其无法参加救灾，句意相反。"}], "explanations": {"动员": "动员：政府号召群众参加抗洪救灾，与“政府”和“群众”的语境相符。", "讽刺": "语义：讽刺是用话挖苦人，政府号召群众救灾不应被讽刺，句意不通。", "原谅": "配价：原谅的宾语是过错，不能带“群众参加抗洪救灾”这样的小句。", "隔离": "语义：隔离是把人与外界分开，政府不会隔离群众使其无法参加救灾，句意相反。"}, "sentence_index": 0, "correct_answer": "动员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府动员了这份报告。", "explanation": "这里应该用〈发布〉。发布用于报告、公告等文件，如发布这份报告；动员的对象是人，不能指报告。"}, {"text": "市里动员了应急预案。", "explanation": "这里应该用〈启动〉。启动用于应急预案、机制等，如启动应急预案；动员的对象是人。"}, {"text": "社区动员了一次清洁活动。", "explanation": "这里应该用〈开展〉。开展用于活动、工作，如开展一次清洁活动；动员的对象是人，不能直接以“活动”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动员", "is_correct": true, "explanation": "动员：政府调动并组织各方力量参与救灾，与“已经”和“各方力量救灾”的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，政府不会嘲笑各方力量救灾，句意不通。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是因他人而生的不满，政府对各方力量救灾不会有这种情绪。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：观察是细看，不能用来指组织各方力量救灾，与“各方力量”不搭配。"}], "explanations": {"动员": "动员：政府调动并组织各方力量参与救灾，与“已经”和“各方力量救灾”的语境相符。", "嘲笑": "语义：嘲笑是取笑别人，政府不会嘲笑各方力量救灾，句意不通。", "嫉妒": "语义：嫉妒是因他人而生的不满，政府对各方力量救灾不会有这种情绪。", "观察": "搭配：观察是细看，不能用来指组织各方力量救灾，与“各方力量”不搭配。"}, "sentence_index": 6, "correct_answer": "动员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她动员了一首诗。", "explanation": "这里应该用〈朗读〉。朗读用于诗文、课文，如朗读一首诗；动员的对象是人，不能指诗。"}, {"text": "法院动员了这起案件。", "explanation": "这里应该用〈审理〉。审理用于案件、诉讼，如审理这起案件；动员的对象是人，不能指案件。"}, {"text": "他们动员了那套新房子。", "explanation": "这里应该用〈装修〉。装修用于房屋、房间，如装修新房子；动员的对象是人，不能指房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县政府动员得全县干部参加抗洪救灾。", "corrected_sentence": "县政府动员了全县干部参加抗洪救灾。", "error_description": "错误：“得”不能表示动作完成，应改为“了”。“得”是结构助词，不是动态助词；表示完成的动态助词是“了”，正确形式是“县政府动员了全县干部参加抗洪救灾。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府很动员群众捐款。", "corrected_sentence": "政府动员群众捐款。", "error_description": "程度副词错误：“动员”是动作动词，前面不能加程度副词“很”，应去掉“很”，说“政府动员群众捐款。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
