INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89485, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "借鉴是看别人怎么做，学他好的地方。", "primary_collocate": null, "pronunciation": "jiè jiàn", "ipa": "tɕjɛ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我借鉴了同学的学习方法，成绩好多了。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看看别人怎么做，借鉴一下好的地方吧。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐做饭很好吃，我想借鉴她的做法。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发言很清楚，我们可以借鉴一下。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜单设计得好，我们也借鉴了一下。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑步的姿势很好，你可以借鉴。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的房间很整齐，我想借鉴她放东西的办法。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的笔记做得很清楚，大家都来借鉴。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌的方法我借鉴过，真的很有用。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用自己想，借鉴一下别人的好办法就行。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "借鉴了", "label": "体标：了"}, {"form": "借鉴过", "label": "体标：过"}, {"form": "借鉴着", "label": "体标：着"}, {"form": "借鑒", "label": "繁体"}, {"form": "借鉴意义", "label": "复合词"}], "register": "口语", "sense_fingerprint": "借鉴：看别人怎么做，学他好的地方（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借鉴", "is_correct": true, "explanation": "正确。借鉴指看别人怎么做，学他好的地方，与“学了同学的方法，成绩好多了”相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评同学的学习方法与“成绩好多了”的因果关系不符，句子不通。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：嫌弃同学的方法就不会去学它，与“成绩好多了”的因果关系矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记了学习方法，成绩不可能好多了，与句子的因果关系不符。"}], "explanations": {"借鉴": "正确。借鉴指看别人怎么做，学他好的地方，与“学了同学的方法，成绩好多了”相符。", "批评": "语义：批评同学的学习方法与“成绩好多了”的因果关系不符，句子不通。", "嫌弃": "语义：嫌弃同学的方法就不会去学它，与“成绩好多了”的因果关系矛盾。", "忘记": "语义：忘记了学习方法，成绩不可能好多了，与句子的因果关系不符。"}, "sentence_index": 0, "correct_answer": "借鉴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "能借鉴一下你的笔吗？", "explanation": "这里应该用〈借〉。借鉴指学别人的做法，借笔这类物品要说借。"}, {"text": "我借鉴了你的伞，明天还你。", "explanation": "这里应该用〈借用〉。借鉴指学别人的做法，借伞这类物品要说借用。"}, {"text": "我借鉴手电筒找到了钥匙。", "explanation": "这里应该用〈借助〉。借鉴指学别人的做法，凭借工具找东西要说借助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借鉴", "is_correct": true, "explanation": "正确。借鉴指学别人好的做法，与“我想……她放东西的办法”相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视她的办法就不会想去学，与“我想”的意愿矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌她的办法就不会想去学它，与“我想”的意愿矛盾。"}, {"text": "冒犯", "is_correct": false, "explanation": "搭配：“冒犯”接的是人，不能接“办法”作宾语。"}], "explanations": {"借鉴": "正确。借鉴指学别人好的做法，与“我想……她放东西的办法”相符。", "忽视": "语义：忽视她的办法就不会想去学，与“我想”的意愿矛盾。", "讨厌": "语义：讨厌她的办法就不会想去学它，与“我想”的意愿矛盾。", "冒犯": "搭配：“冒犯”接的是人，不能接“办法”作宾语。"}, "sentence_index": 6, "correct_answer": "借鉴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈借鉴了一把钥匙，就把门打开了。", "explanation": "这里不能用〈借鉴〉。借鉴指学别人的做法，把钥匙借来开门这种意思不能用借鉴表达。"}, {"text": "我借鉴了一张凳子，坐在上面吃饭。", "explanation": "这里不能用〈借鉴〉。借鉴指学别人的做法，把凳子借来坐这种意思不能用借鉴表达。"}, {"text": "他借鉴了一只鞋子，穿着去上学。", "explanation": "这里不能用〈借鉴〉。借鉴指学别人的做法，把鞋子借来穿这种意思不能用借鉴表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我借鉴了过他的做法，效果很好。", "corrected_sentence": "我借鉴过他的做法，效果很好。", "error_description": "错误在于「了」和「过」同时出现。「借鉴过」表示有过这种经历，不能再加「了」。正确说法是「我借鉴过他的做法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可以借鉴了他的做法。", "corrected_sentence": "你可以借鉴他的做法。", "error_description": "错误在于「了」加在了「借鉴」后。「可以」表示建议或许可，不能和表示完成的「了」同用。正确说法是「你可以借鉴他的做法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
