INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以别人的做法或经验为参考。", "primary_collocate": null, "pronunciation": "jiè jiàn", "ipa": "tɕjɛ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们可以借鉴其他公司的成功经验。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市借鉴了国外的做法，建了很多自行车道。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写这篇文章时，他借鉴了不少前人的研究。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校想借鉴别的学校的管理办法。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新老师应该借鉴有经验的老师的上课方法。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的做法很值得别人借鉴。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借鉴别人的经验，可以少走很多弯路。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计这座桥时，工程师借鉴过古代的方法。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的教育制度，我们只能借鉴，不能照搬。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把国外的好经验借鉴过来，用在自己的工作中。", "target_word": "借鉴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "借鉴了", "label": "体标：了"}, {"form": "借鉴过", "label": "体标：过"}, {"form": "借鉴着", "label": "体标：着"}, {"form": "借鑒", "label": "繁体"}, {"form": "借鉴意义", "label": "复合词"}], "register": "书面", "sense_fingerprint": "借鉴：以别人的做法或经验为参考（正式用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借鉴", "is_correct": true, "explanation": "正确。借鉴指参考别人的做法或经验，与“可以……其他公司的成功经验”相符。"}, {"text": "投诉", "is_correct": false, "explanation": "语义：投诉是向有关方面反映问题，不能用来表示学习别人的成功经验。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝其他公司的成功经验与句中“可以”所表示的参考建议相反，句子不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑别人的成功经验与“可以……成功经验”的建议相矛盾。"}], "explanations": {"借鉴": "正确。借鉴指参考别人的做法或经验，与“可以……其他公司的成功经验”相符。", "投诉": "语义：投诉是向有关方面反映问题，不能用来表示学习别人的成功经验。", "拒绝": "语义：拒绝其他公司的成功经验与句中“可以”所表示的参考建议相反，句子不通。", "嘲笑": "语义：嘲笑别人的成功经验与“可以……成功经验”的建议相矛盾。"}, "sentence_index": 0, "correct_answer": "借鉴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校借鉴了别的学校的操场。", "explanation": "这里应该用〈借用〉。借鉴指参考别人的做法或经验，借用场地、物品要说借用。"}, {"text": "他向朋友借鉴了一千块钱。", "explanation": "这里应该用〈借〉。借鉴只用于做法或经验，向朋友借钱要说借。"}, {"text": "他借鉴望远镜看清了远处的船。", "explanation": "这里应该用〈借助〉。借鉴指参考做法或经验，凭借工具看清东西要说借助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借鉴", "is_correct": true, "explanation": "正确。借鉴指参考别人的做法，与“借鉴别人的经验，可以少走很多弯路”相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视别人的经验不能减少弯路，与句子的建议相矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌别人的经验不会帮人少走弯路，与句子的语境不符。"}, {"text": "冒犯", "is_correct": false, "explanation": "搭配：“冒犯”接的是人，不能接“经验”作宾语。"}], "explanations": {"借鉴": "正确。借鉴指参考别人的做法，与“借鉴别人的经验，可以少走很多弯路”相符。", "忽视": "语义：忽视别人的经验不能减少弯路，与句子的建议相矛盾。", "讨厌": "语义：讨厌别人的经验不会帮人少走弯路，与句子的语境不符。", "冒犯": "搭配：“冒犯”接的是人，不能接“经验”作宾语。"}, "sentence_index": 6, "correct_answer": "借鉴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借鉴了一张桌子，搬回了家。", "explanation": "这里不能用〈借鉴〉。借鉴指参考别人的做法或经验，把桌子借来用这种意思不能用借鉴表达。"}, {"text": "我借鉴了一条裤子，穿了一整天。", "explanation": "这里不能用〈借鉴〉。借鉴指参考别人的做法或经验，把裤子借来穿这种意思不能用借鉴表达。"}, {"text": "妈妈借鉴了一袋米，送给了邻居。", "explanation": "这里不能用〈借鉴〉。借鉴指参考别人的做法或经验，把一袋米借来送人这种意思不能用借鉴表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该借鉴了先进城市的经验。", "corrected_sentence": "我们应该借鉴先进城市的经验。", "error_description": "错误在于「借鉴」后多加了「了」。「应该」表示义务，不能和表示完成的「了」同用。正确说法是「我们应该借鉴先进城市的经验」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不借鉴了这种做法，因为它不适合我们。", "corrected_sentence": "我不借鉴这种做法，因为它不适合我们。", "error_description": "错误在于「了」加在了否定句的动词「借鉴」后。「不」否定的是未发生的动作，不能和表示完成的「了」同用。正确说法是「我不借鉴这种做法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
