INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（书面）离开本国。", "primary_collocate": null, "pronunciation": "qù guó", "ipa": "tɕʰy˥˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "诗人去国之后，写下了很多思乡的诗。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自幼去国，晚年才回到故土。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位学者去国数十年，仍然心系祖国。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三十岁那年去国，从此再没回来。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国多年的游子，终于回到了家乡。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一年他去国，什么也没带。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去国前，在故乡的老屋住了最后一夜。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战乱之年，不少读书人只好去国避难。", "target_word": "去国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去国之人，最怕听到乡音。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早年去国求学，后来在海外任教。", "target_word": "去国", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "去国怀乡", "label": "复合"}], "register": "书面", "sense_fingerprint": "书面语：离开本国，远走他乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "团聚", "is_correct": false, "explanation": "语义：团聚之后不会写思乡的诗，与句中的“思乡”矛盾。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国，与后文“写下了很多思乡的诗”相符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能作诗人的人生事件，与“之后”的句式不合。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世之后无法写诗，与句意矛盾。"}], "explanations": {"团聚": "语义：团聚之后不会写思乡的诗，与句中的“思乡”矛盾。", "去国": "去国：离开本国，与后文“写下了很多思乡的诗”相符。", "装修": "搭配：“装修”的对象是房屋，不能作诗人的人生事件，与“之后”的句式不合。", "去世": "语义：去世之后无法写诗，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都去国做饭。", "explanation": "这里应该用〈下厨〉。去国指离开本国，不能用来说在家里做饭。"}, {"text": "她每周都去国逛街。", "explanation": "这里应该用〈上街〉。去国指离开本国，不能用来说在本地外出逛街。"}, {"text": "他周末总是去国整理房间。", "explanation": "这里应该用〈在家〉。去国指离开本国，不能用来说在家里做家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：出生前不可能住在老屋，与句中的情况矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“住了最后一夜”的离别语境不合。"}, {"text": "去国", "is_correct": true, "explanation": "去国：离开本国，与“在故乡住了最后一夜”的离别语境相符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”与“在故乡住了最后一夜”的离别语境不合。"}], "explanations": {"出生": "语义：出生前不可能住在老屋，与句中的情况矛盾。", "唱歌": "语义：“唱歌”与“住了最后一夜”的离别语境不合。", "去国": "去国：离开本国，与“在故乡住了最后一夜”的离别语境相符。", "下棋": "语义：“下棋”与“在故乡住了最后一夜”的离别语境不合。"}, "sentence_index": 6, "correct_answer": "去国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家上个月去国到郊区。", "explanation": "这里应该用〈搬家〉。去国是离开本国，不能用来说在国内搬到郊区。"}, {"text": "知青们去国插队。", "explanation": "这里应该用〈下乡〉。去国指离开本国，不能用来说到农村插队。"}, {"text": "他每天早上去国散步。", "explanation": "这里应该用〈出门〉。去国指离开本国，不能用来说早上外出散步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去国着十年，从未回乡。", "corrected_sentence": "他去国十年，从未回乡。", "error_description": "体标错误：“去国”表示一次性离开的瞬时动作，不能用“着”表示持续，“去国着十年”不成立；应去掉“着”，写作“他去国十年，从未回乡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很去国三年，再也没有回家。", "corrected_sentence": "他去国三年，再也没有回家。", "error_description": "副词错误：程度副词“很”不能修饰动作动词“去国”，应去掉“很”，写作“他去国三年，再也没有回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系上", "is_correct": true, "explanation": "反义：「系上」与「解开」相对，指把鞋带、绳子等重新绑住或扣住。"}, {"text": "拿起", "is_correct": false, "explanation": "无关：「拿起」指用手把东西提起，与「解开」没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "无关：「清洗」指用水把东西弄干净，与「解开」没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "无关：「出发」指开始行程，与「解开」没有反义关系。"}], "correct_answer": "系上", "explanations": {"系上": "反义：「系上」与「解开」相对，指把鞋带、绳子等重新绑住或扣住。", "拿起": "无关：「拿起」指用手把东西提起，与「解开」没有反义关系。", "清洗": "无关：「清洗」指用水把东西弄干净，与「解开」没有反义关系。", "出发": "无关：「出发」指开始行程，与「解开」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系上", "is_correct": true, "explanation": "反义：「系上」与「解开」相对，指把船上的绳子重新绑住。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：「搬运」指把东西从一处运到另一处，与「解开」没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "无关：「收集」指把分散的东西聚到一起，与「解开」没有反义关系。"}, {"text": "挑选", "is_correct": false, "explanation": "无关：「挑选」指从许多东西中选出需要的，与「解开」没有反义关系。"}], "correct_answer": "系上", "explanations": {"系上": "反义：「系上」与「解开」相对，指把船上的绳子重新绑住。", "搬运": "无关：「搬运」指把东西从一处运到另一处，与「解开」没有反义关系。", "收集": "无关：「收集」指把分散的东西聚到一起，与「解开」没有反义关系。", "挑选": "无关：「挑选」指从许多东西中选出需要的，与「解开」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解开是把绑着的结或扣着的东西弄松，打开。", "primary_collocate": null, "pronunciation": "jiě kāi", "ipa": "tɕje˨˩˦ kʰaj˥", "syllable_count": 2, "sentences": [{"text": "我解开了鞋带。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把绳子上的结解开了。", "target_word": "解开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我解开袋子上的绳子。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈解开围巾，放在桌子上。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他慢慢解开衬衫的扣子。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气热了，他解开了外衣的第一个扣子。", "target_word": "解开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的绳子太紧，我用了很久才解开。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她解开背包上的带子，拿出一本书。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把盒子上的带子解开，里面有一只小猫。", "target_word": "解开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水手解开船上的绳子，船慢慢走了。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解开了", "label": "体标（完成）"}, {"form": "解开过", "label": "体标（经历）"}, {"form": "解不开", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "把绳结、扣子、带子等绑着或扣着的东西弄松打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解开", "is_correct": true, "explanation": "正确：「解开」指把绑着的鞋带弄松打开，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指把食物咽下去，鞋带不能吃。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指用水加热食物，与鞋带无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」的对象是歌曲，鞋带不能唱，句意不通。"}], "explanations": {"解开": "正确：「解开」指把绑着的鞋带弄松打开，句意通顺。", "吃": "语义：「吃」指把食物咽下去，鞋带不能吃。", "煮": "语义：「煮」指用水加热食物，与鞋带无关。", "唱": "语义：「唱」的对象是歌曲，鞋带不能唱，句意不通。"}, "sentence_index": 0, "correct_answer": "解开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她解开了柜子，拿出了一件毛衣。", "explanation": "这里应该用〈拉开〉。柜门要拉开，柜子没有被系住或扣住，解开不能用于柜子。"}, {"text": "他解开了窗户，让风吹进来。", "explanation": "这里应该用〈打开〉。解开指松开系着或扣着的东西，窗户没有被系住，开窗要用打开。"}, {"text": "她解开了那封信，读了起来。", "explanation": "这里应该用〈拆开〉。拆开指撕开信封或包装，解开用于系着、扣着的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解开", "is_correct": true, "explanation": "正确：绳子太紧需要慢慢松开，「解开」与「用了很久才」搭配，句意通顺。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，不能用于绳子。"}, {"text": "烤", "is_correct": false, "explanation": "语义：「烤」指用火加热食物，与绳子太紧的情境不符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」指用布等摩擦表面去掉脏东西，与解开绳子的情境不符。"}], "explanations": {"解开": "正确：绳子太紧需要慢慢松开，「解开」与「用了很久才」搭配，句意通顺。", "唱": "搭配：「唱」的对象是歌曲，不能用于绳子。", "烤": "语义：「烤」指用火加热食物，与绳子太紧的情境不符。", "擦": "语义：「擦」指用布等摩擦表面去掉脏东西，与解开绳子的情境不符。"}, "sentence_index": 6, "correct_answer": "解开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶解开了锅盖，闻到了汤的香味。", "explanation": "这里应该用〈揭开〉。揭开指把盖子掀起来，锅盖没有绳结或扣子，不能用解开。"}, {"text": "他解开了篮子里的苹果，拿了一个。", "explanation": "这里应该用〈拿出〉。解开指松开系着或扣着的东西，苹果没有被绑住，取出要用拿出。"}, {"text": "他解开了书架上的那本书，放进了包里。", "explanation": "这里应该用〈抽出〉。书是从书架上抽出来的，书本没有被系住或扣住，解开不能用于书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你帮我把解开袋子上的绳子。", "corrected_sentence": "请你帮我解开袋子上的绳子。", "error_description": "「把」字用错：「把」字句要把宾语放在「解开」前面，此句宾语「袋子上的绳子」在「解开」后面，不用「把」。正确说法是「请你帮我解开袋子上的绳子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水手把解开了船上的绳子，船慢慢走了。", "corrected_sentence": "水手解开了船上的绳子，船慢慢走了。", "error_description": "「把」字用错：「把」字句要把宾语放在动词前，此句宾语「船上的绳子」在动词后，不用「把」。正确说法是「水手解开了船上的绳子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
