INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把疑问、谜团、难题等弄明白，找到答案。", "primary_collocate": null, "pronunciation": "jiě kāi", "ipa": "tɕje˨˩˦ kʰaj˥", "syllable_count": 2, "sentences": [{"text": "这道题很难，我想了很久才解开。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师终于解开了这个谜。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把事情说清楚，终于解开了我们之间的误会。", "target_word": "解开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察解开了案子里的谜团。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们一起解开了黑板上的数学难题。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了一个晚上，终于解开了这个问题。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的话解开了我心里的疑问。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家想解开宇宙的秘密。", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题困扰了大家很久，直到昨天才被解开。", "target_word": "解开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谜语很有意思，你解开了吗？", "target_word": "解开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解开了", "label": "体标（完成）"}, {"form": "解开过", "label": "体标（经历）"}, {"form": "解不开", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "弄明白疑问、谜团、难题，找到答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解开", "is_correct": true, "explanation": "正确：「解开」指弄明白难题，「想了很久才」与「这道题很难」照应，句意通顺。"}, {"text": "摘", "is_correct": false, "explanation": "语义：「摘」指采下或取下植物、果实，与「题」不搭。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」的对象是衣服、鞋袜，不说「穿题」。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」指把液体咽下去，与「题」不搭。"}], "explanations": {"解开": "正确：「解开」指弄明白难题，「想了很久才」与「这道题很难」照应，句意通顺。", "摘": "语义：「摘」指采下或取下植物、果实，与「题」不搭。", "穿": "搭配：「穿」的对象是衣服、鞋袜，不说「穿题」。", "喝": "语义：「喝」指把液体咽下去，与「题」不搭。"}, "sentence_index": 0, "correct_answer": "解开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她终于解开了心扉，和大家聊起了过去。", "explanation": "这里应该用〈打开〉。打开心扉指愿意敞开心意，解开只用于疑问、谜团或系着的东西。"}, {"text": "他解开了那扇门，走了进去。", "explanation": "这里应该用〈推开〉。门没有被系住或缠住，推门要用推开，解开不能用于门。"}, {"text": "会上没人说话，他第一个解开了沉默。", "explanation": "这里应该用〈打破〉。打破沉默指结束安静的局面，解开不能用于沉默。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解开", "is_correct": true, "explanation": "正确：「解开」指消除疑问，「她的话」与「疑问」搭配，句意通顺。"}, {"text": "烤", "is_correct": false, "explanation": "语义：「烤」指用火加热食物，与疑问不搭。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」的对象是表面的脏东西，不说「擦疑问」。"}, {"text": "摔", "is_correct": false, "explanation": "语义：「摔」指使劲扔到地上，与「疑问」不搭。"}], "explanations": {"解开": "正确：「解开」指消除疑问，「她的话」与「疑问」搭配，句意通顺。", "烤": "语义：「烤」指用火加热食物，与疑问不搭。", "擦": "搭配：「擦」的对象是表面的脏东西，不说「擦疑问」。", "摔": "语义：「摔」指使劲扔到地上，与「疑问」不搭。"}, "sentence_index": 6, "correct_answer": "解开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他解开了抽屉，拿出一把钥匙。", "explanation": "这里应该用〈拉开〉。抽屉是被拉出来的，没有被系住或扣住，解开不能用于抽屉。"}, {"text": "妈妈解开了衣服上的污渍。", "explanation": "这里应该用〈擦掉〉。污渍是擦掉的，不是系着或缠着的，解开不能用于污渍。"}, {"text": "工人解开了墙上的钉子。", "explanation": "这里应该用〈拔出〉。钉子是拔出来的，不是系着或缠着的，解开不能用于钉子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师终于解开着这个谜。", "corrected_sentence": "老师终于解开了这个谜。", "error_description": "体标误用：「解开」表示动作有了结果，「终于」说明事情已经完成，要用「了」，不能用表示持续的「着」。正确说法是「老师终于解开了这个谜」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把解开了这个难题。", "corrected_sentence": "他终于解开了这个难题。", "error_description": "「把」字用错：「把」字句要把宾语放在动词前，此句宾语「这个难题」在动词后，不用「把」。正确说法是「他终于解开了这个难题」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
