INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兔子是长耳朵的小动物，爱吃萝卜和青菜。", "primary_collocate": null, "pronunciation": "tù zi", "ipa": "tʰu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "这只兔子最爱吃萝卜。", "target_word": "兔子", "complexity_tier": "T3", "furigana": "zhè zhī tù zi zuì ài chī luó bo", "sentence_source": "generated"}, {"text": "白兔子的耳朵又长又大。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家养了两只兔子。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子正在草地上吃青菜。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的草地上蹲着一只兔子。", "target_word": "兔子", "complexity_tier": "T3", "furigana": "gōng yuán de cǎo dì shàng dūn zhe yī zhī tù zi", "sentence_source": "generated"}, {"text": "这只兔子的眼睛是红的。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给兔子买了很多青菜。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子一听到声音就跑了。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一只灰兔子。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友给兔子取了个名字。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "长耳朵、爱吃萝卜青菜的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兔子", "is_correct": true, "explanation": "正确：兔子是长耳朵、爱吃萝卜的小动物，“这只兔子最爱吃萝卜”说得通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不会吃东西，“最爱吃萝卜”的主语必须是能进食的动物。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴用品，不能爱吃萝卜，与句中“吃萝卜”冲突。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“吃”不能与“椅子”搭配，“最爱吃萝卜”只能说能进食的生物。"}], "explanations": {"兔子": "正确：兔子是长耳朵、爱吃萝卜的小动物，“这只兔子最爱吃萝卜”说得通。", "杯子": "语义：杯子不会吃东西，“最爱吃萝卜”的主语必须是能进食的动物。", "手套": "语义：手套是穿戴用品，不能爱吃萝卜，与句中“吃萝卜”冲突。", "椅子": "搭配：“吃”不能与“椅子”搭配，“最爱吃萝卜”只能说能进食的生物。"}, "sentence_index": 0, "correct_answer": "兔子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐兔子去上学。", "explanation": "这里把〈兔子〉当成了〈公交车〉这类交通工具。兔子是小动物，不能坐着去上学。"}, {"text": "这件毛衣是用兔子做的。", "explanation": "这里应该用〈兔毛〉。兔毛是纺织衣物的材料，兔子是动物，不能用来做毛衣。"}, {"text": "这只兔子是我们的数学老师。", "explanation": "这里把〈兔子〉当成了〈人〉。兔子是动物，不能当老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兔子", "is_correct": true, "explanation": "正确：兔子爱吃青菜，妈妈可以给兔子买很多青菜。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不吃青菜，“给……买青菜”的对象必须是能吃青菜的生物。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子也不会吃青菜，与句中“买很多青菜”的对象不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“给……买青菜”要求能进食的对象，石头不能与之搭配。"}], "explanations": {"兔子": "正确：兔子爱吃青菜，妈妈可以给兔子买很多青菜。", "汽车": "语义：汽车不吃青菜，“给……买青菜”的对象必须是能吃青菜的生物。", "桌子": "语义：桌子也不会吃青菜，与句中“买很多青菜”的对象不符。", "石头": "搭配：“给……买青菜”要求能进食的对象，石头不能与之搭配。"}, "sentence_index": 6, "correct_answer": "兔子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天去兔子那里上课。", "explanation": "这里把〈兔子〉当成了〈教室〉这类地点。兔子是动物，不能作为上课的地方。"}, {"text": "他每天用兔子刷牙。", "explanation": "这里把〈兔子〉当成了〈牙刷〉这类工具。兔子是动物，不能用来刷牙，应说牙刷。"}, {"text": "他兔子了我的钱。", "explanation": "这里把〈兔子〉当成了动词〈偷〉。兔子是名词，没有偷走的意思，这个用法不存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草地上有一匹兔子。", "corrected_sentence": "草地上有一只兔子。", "error_description": "量词错误：“匹”用于马等牲口，兔子应用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把两匹兔子关进了笼子。", "corrected_sentence": "我把两只兔子关进了笼子。", "error_description": "量词错误：“匹”用于马等牲口，兔子应用“只”，应说“两只兔子”而不是“两匹兔子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
