INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哺乳动物，耳朵长，尾巴短，善于跳跃。", "primary_collocate": null, "pronunciation": "tù zi", "ipa": "tʰu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "兔子的尾巴很短。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子跳得又高又远。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子是一种哺乳动物。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子的后腿比前腿长。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在山上看见了一只兔子。", "target_word": "兔子", "complexity_tier": "T3", "furigana": "wǒ zài shān shàng kàn jiàn le yī zhī tù zi", "sentence_source": "generated"}, {"text": "那只兔子跳过了小河。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子的耳朵很长，听得很清楚。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草丛里跳出来一只兔子。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子不像猫，它的尾巴短。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子跳起来的样子很有意思。", "target_word": "兔子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "耳朵长、尾巴短、善于跳跃的哺乳动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兔子", "is_correct": true, "explanation": "正确：兔子是耳朵长、尾巴短的哺乳动物，“兔子的尾巴很短”成立。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，没有尾巴，“的尾巴很短”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“尾巴”只属于动物，不能与“桌子”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的矿物，不会有尾巴，与句子的描述矛盾。"}], "explanations": {"兔子": "正确：兔子是耳朵长、尾巴短的哺乳动物，“兔子的尾巴很短”成立。", "房子": "语义：房子是建筑，没有尾巴，“的尾巴很短”不成立。", "桌子": "搭配：“尾巴”只属于动物，不能与“桌子”搭配。", "石头": "语义：石头是无生命的矿物，不会有尾巴，与句子的描述矛盾。"}, "sentence_index": 0, "correct_answer": "兔子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把兔子插在花瓶里。", "explanation": "这里把〈兔子〉当成了〈花〉。兔子是会跳的哺乳动物，不能插在花瓶里。"}, {"text": "这件毛衣是用兔子做的。", "explanation": "这里应该用〈兔毛〉。兔毛是纺织衣物的材料，兔子是动物，不能用来做毛衣。"}, {"text": "兔子是一种乐器。", "explanation": "这里把〈兔子〉当成了〈器具〉。兔子是哺乳动物，不能算作器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兔子", "is_correct": true, "explanation": "正确：兔子的耳朵长，所以听得很清楚，描述合理。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子没有耳朵，“耳朵很长，听得很清楚”描述的是有听觉的动物。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“听得很清楚”的主体须是有听觉的生物，电脑不能与此搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有听觉，与“听得很清楚”冲突。"}], "explanations": {"兔子": "正确：兔子的耳朵长，所以听得很清楚，描述合理。", "杯子": "语义：杯子没有耳朵，“耳朵很长，听得很清楚”描述的是有听觉的动物。", "电脑": "搭配：“听得很清楚”的主体须是有听觉的生物，电脑不能与此搭配。", "石头": "语义：石头没有听觉，与“听得很清楚”冲突。"}, "sentence_index": 6, "correct_answer": "兔子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兔子是我们班的班长。", "explanation": "这里把〈兔子〉当成了〈人〉。兔子是动物，不能担任班长。"}, {"text": "我每天用兔子擦地板。", "explanation": "这里把〈兔子〉当成了〈抹布〉这类工具。兔子是动物，不能用来擦地板。"}, {"text": "他兔子了我的钱。", "explanation": "这里把〈兔子〉当成了动词〈偷〉。兔子是名词，没有偷走的意思，这个用法不存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那张兔子跑得很快。", "corrected_sentence": "那只兔子跑得很快。", "error_description": "量词错误：“张”用于纸张、桌子等平面的东西，兔子应用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在草地上数了三兔子。", "corrected_sentence": "我在草地上数了三只兔子。", "error_description": "量词漏掉：数词后接名词时要加量词“只”，应说“三只兔子”，不能说“三兔子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
